quests[25420] = { id = 25420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Hindernisse", description = "Ich habe dieses Tor jahrelang untersucht und versucht, einen Eingang zu finden, der die uralte Architektur nicht beeinträchtigt. Und dann kommen ein paar enorme Erdbeben und schlagen das ganze Ding entzwei! Was geschehen ist, ist geschehen und nun liegt der Eingang nach Uldum frei.\n\nIch hatte aber nicht damit gerechnet, dass etwas aus den Ruinen kommt, bevor wir hineingehen. Eine Masse von Golems rennen nun im Tal umher, und drinnen sind noch mehr. Jemand muss sie aus dem Weg schaffen, damit wir ins Innere können.", sourceObjective = "Zerstört 6 Sandsteingolems.", completion = "Gute Arbeit, {class}. Wir sind den Geheimnissen Uldums schon einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[25421] = { id = 25421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Tafel", description = "Auf dem Boden der Truhe findet Ihr eine große Tafel. Das Material scheint Stein zu ähneln, ist aber ganz sanft und fein anzusehen und mit seltsamen Schriften versehen.\n\nEin Teil der Schrift ist der gleiche wie an den Mauern, doch es sind auch andere Schriften darauf zu finden. Gunstan wird sich sicherlich dafür interessieren.", sourceObjective = "Bringt die große Tafel zu Gunstan.", progress = "Ihr seid zurück! Was habt Ihr gefunden?", completion = "Das ist wirklich unglaublich. Die Hieroglyphen sind zweifellos von den Titanen, aber die Markierungen darunter...\n\nIch würde hoffen, dass es sich dabei um den gleichen Text in meheren uralten Sprachen handelt. Wir könnten es benutzen, um die Hieroglyphen zu entziffern! Wenn die Vorkammer wirklich voll mit diesen Schriften ist, so werden wir noch weitaus mehr lernen können.\n\nIch möchte Euch gerne eine große Belohnung geben, {name}. Das ist der Fund des Jahrhunderts!", sourceObjectiveStatus = "unverified-source-field" }
quests[25422] = { id = 25422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Graunebelvermächtnis", description = "Ich bin an diesen Ort gekettet... es kostet viel Energie, nur mit Euch zu sprechen. Ich halte es kaum aus, in dieser Form zu bleiben.\n\nIch kann Euch helfen, aber bitte helft mir zuerst, in dieser Welt fußzufassen. Sobald ich es geschafft habe, meine Konzentration auf diese Ebene zu lenken, sollte ich Euch helfen können...\n\nBitte, bringt mir etwas von der Erde außerhalb der Gruft. Sie ist voller uralter arkaner Ablagerungen und liegt seit Jahrhunderten vergessen dort.", sourceObjective = "Sammelt 6 Haufen leuchtende Erde.", progress = "Habt Ihr die Erde? Es fällt mir wirklich schwer, mich zusammenzuhalten... Beeilt Euch...", completion = "Vielen Dank! Ich danke Euch...\n\nEs geht mir schon viel besser. Noch ein bisschen mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[25423] = { id = 25423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Leiden", description = "Seid vorsichtig, wenn Ihr Eure Reise fortsetzt. Andere Geister sind an diesen Ort gebunden, bösartige Geister voller Hass. Sie haben zu viel gelitten.\n\nNichts, was sie einst waren, ist noch übrig, nur ihr Leid und der Wille, zu leben. Wir brauchen diesen Willen, um den Oberanführer zu beschwören, der mich hier festhält. Bitte, sammelt die Seelenessenzen der Geister und bringt sie mir.", sourceObjective = "Sammelt 6 Seelenessenzen.", progress = "Habt Ihr sie erhalten können?", completion = "Ihr könnt ihre Pein spüren, nicht wahr?\n\nMeine armen Freunde. Wenigstens kann ich sie benutzen, um hier etwas zu verändern...", sourceObjectiveStatus = "unverified-source-field" }
quests[25424] = { id = 25424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Alysra", description = "Ich danke Euch, dass Ihr mich befreit habt, {name}. Ich werde unseren Verbündeten von unseren Erkenntnissen berichten.\n\nIch schlage vor, dass Ihr zu dem Smaragddrachen zurückkehrt, der Euch geschickt hat.\n\nDer Schattenhammer versucht mit diesem Angriff nicht nur, neue Gebiete zu erobern. Sie sind auch hinter einem Gefangenen her.\n\nFandral Hirschhaupt wird in den Grabhügeln gefangen gehalten. Der Angriff dient auch als Ablenkungsmanöver, um ihn zu befreien. Welchen Zweck das haben soll, weiß ich nicht. Vielleicht kann unser Drachenverbündeter etwas Licht ins Dunkel bringen.", sourceObjective = "Kehrt zu Alysra bei den Ruinen von Lar'donir auf dem Hyjal zurück.", completion = "Diese Entwicklung ist sehr beunruhigend, {name}. Wir müssen schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25426] = { id = 25426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Waldpfoten", description = "Der erste direkte Befehl von Shandris lautet, die Waldpfotengnolle hier unter Kontrolle zu bringen. Sie haben sich zu schnell zu weit verbreitet und wachsen zu einer Bedrohung für den Wald und für unsere Kriegsanstrengungen heran.\n\nSie wissen, dass wir hier sind. Nachdem wir dieses Lager eingenommen haben, haben wir verdeckte Angriffe gegen sie durchgeführt. Es ist an der Zeit einen Großangriff zu starten; bringt mir zehn von ihren Mähnen, dann sind wir bereit für die nächste Phase.", sourceObjective = "Sammelt 10 Mähnen von Waldpfotengnollen.", progress = "Die Mähnen sind keinesfalls bloß als Trophäen gedacht. Wenn es schon Blutvergießen geben muss, dann sollten wir daraus auch einen Nutzen ziehen.", completion = "Ausgezeichnete Arbeit, {name}. Wusste ich es doch, dass diese Gnolle kein Problem für Euch sein würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25427] = { id = 25427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlag gegen die Alphas", description = "Man sollte keine Gefahr jemals unterschätzen. Die Gnolle sehen wie einfache Rohlinge aus, aber sie haben die Gerissenheit von Tieren.\n\nDie Gnolle sind ein Rudel und jedes Rudel hat Alphamännchen: die stärksten, größten und rücksichtslosesten Mitglieder des Rudels, die sich ihre Dominanz durch nichts als den Einsatz ihrer Klauen sichern. Sie sind auch diejenigen, die die Befehle erteilen und genau deswegen diejenigen, die wir als nächstes töten werden.\n\nEs gibt mindestens fünf von ihnen in den verschiedenen Lagern verstreut. Ihr erkennt sie an ihrem unfreundlichen Verhalten den anderen gegenüber. Findet sie und verhaltet Euch ihnen gegenüber noch unfreundlicher.", sourceObjective = "Tötet 5 Alphas der Waldpfoten.", completion = "Perfekt. Die Gnolle, die noch übrig sind, sind nichts weiter als Beute, die in den Wäldern verloren gegangen ist.\n\nHehe... hier, Soldat, nehmt diese Belohnung, bevor ich es vergesse. Es gibt noch andere Gefahren, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25428] = { id = 25428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwarze Herz der Flamme", description = "Jetzt werdet Ihr unser neu gewonnenes Wissen nutzen, um Thol'embaar auf die Ebene der Sterblichen zu zerren, wie ein schreiendes Kind aus dem Leib der Mutter. Und dann werdet Ihr ihn vernichten.\n\nDas Ritual ist einfach: Nehmt diesen verkohlten Ast, stoßt ihn dreimal auf den Boden und sprecht laut seinen Namen.\n\nIhr müsst ihn mitten aus dem Herz des Infernos rufen. Vernichtet ihn und bringt mir sein schwarzes Herz.", sourceObjective = "Benutzt den verkohlten Ast im Inferno, um Thol'embaar herbeizurufen. Tötet ihn und nehmt Euch Thol'embaars schwarzes Herz.", progress = "Sagt mir! Habt Ihr schon gegen Thol'embaar gekämpft?\n\nIch lebe mein Leben stellvertretend durch Euch, {race}. Also enttäuscht mich nicht!", completion = "Da ist es! Welch Trophäe! Geboren in den Feuern einer anderen Ebene…\n\nLos, {race}. Zerquetscht es. Zerquetscht sein verkohltes Herz in Euren Händen und lasst den Wind die Asche forttragen… Ja, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[25429] = { id = 25429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash-Plage", description = "Jetzt, da die Gnolle aus dem Weg geräumt sind, können wir uns unseren anderen Feinden widmen. Unsere Späher haben in der Nähe eine Art Schwarmbau entdeckt, der sich tief unter dem Boden ausbreitet.\n\nDie Insekten in diesem Bau sind sehr groß und aggressiv. Wahrscheinlich sind sie eine noch größere Bedrohung als die Gnolle. Ich möchte, dass Ihr Euch mit äußerster Vorsicht dem Schwarmbau nähert. Vernichtet eine ansehnliche Menge der Käfer und bringt mir ihre Knochenpanzer, damit ich sie weiter untersuchen kann.", sourceObjective = "Sammelt 20 Zukk'ashknochenpanzer.", progress = "Was macht die Jagd, {name}? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Also handelt es sich dabei doch um Silithiden… Ich war mir nicht sicher, da ich nie persönlich einen zu Gesicht bekommen habe. Wir hatten in Gilneas so unsere Probleme, aber zumindest gibt es bei uns nicht solche riesigen Monstrositäten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25430] = { id = 25430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgrüne Verbündete", description = "Die Druiden des Hyjal sind nicht die Einzigen, die geschworen haben, dieses Land zu beschützen. Auch die Smaragddrachen haben sich uns erneut angeschlossen, um uns bei unserer Aufgabe zu unterstützen.\n\nSprecht mit Alysra bei den Ruinen von Lar'donir im Norden und findet heraus, wie Ihr helfen könnt.", sourceObjective = "Sprecht mit Alysra bei den Ruinen von Lar'donir am Berg Hyjal.", completion = "Meine Pflicht hier besteht darin, die Bewegung des Feindes von oben zu beobachten und unseren Armeen bei Bedarf Anweisungen zu geben.\n\nEure Hilfe kommt mir sehr gelegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25431] = { id = 25431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornstachel", description = "Die meisten Insekten, die wir aus dem Schwarm bisher gesehen haben, waren groß genug, aber meine Späher haben von einem enorm großen Insekt berichtet. Anscheinend ist es eine riesige Wespe, die in erster Linie die Arbeiter an die Erde leitet.\n\nIch kenne mich damit nicht wirklich aus, aber wenn sie sich mit dieser Erdgrube nicht mehr zufrieden geben, werden wir ihnen ein Ende bereiten müssen. Tötet diese Riesenwespe und kehrt dann zu mir zurück.", sourceObjective = "Tötet Zornstachel in der Gewundenen Tiefe.", completion = "Gut gemacht, {name}! Ihr stellt Euch als äußerst nützlich bei der Sicherung dieses Gebiets für die Allianz heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25432] = { id = 25432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht aller Oger Abend", description = "Wir haben den Gordunni in Düsterbruch viel Schaden zugefügt, aber wir sind noch nicht ganz fertig mit unserem Vorhaben. Meine Späher berichten von einer Gruppe von Gordunni, die sich in den Hügeln nördlich von hier aus irgendeinem Grund versammelt haben.\n\nVielleicht sind sie an dem Lager der Horde in der Nähe interessiert, aber ich muss es mit Sicherheit wissen. Erkundet die Gegend, tötet alle Oger, die Euch über den Weg laufen, und meldet Euch wieder bei mir.", sourceObjective = "Tötet 5 Hügelwächter der Gordunni.", completion = "Gut, Euch wiederzusehen. Wir haben viel über die Situation der Oger in Erfahrung gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25433] = { id = 25433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch-Sichtung", description = "Ihr habt es vielleicht selbst schon gesehen - unsere Späher berichten von einer enormen Bestie, die von den Ogern gefangen gehalten wird. Es wird gesagt, sie sehe wie ein Sasquatch aus, und wenn das der Fall ist, dann ist es wohl der größte Sasquatch, der je in Feralas gesichtet wurde.\n\nDie Oger haben wohl vor, ihn zu zähmen. Die Vorstellung ist zwar schon fast amüsant, aber ich werde nicht rumsitzen und zuschauen, wie sie dem Ding beibringen, sich auf Kommando auf die Seite zu rollen. Kehrt zu den Hügeln zurück und tötet den Sasquatch.", sourceObjective = "Tötet Großfaust.", completion = "Gut gemacht, {name}, auf Euch kann man sich verlassen. Eine weitere Gefahr wurde dank Euch aus Feralas entfernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25434] = { id = 25434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmer zähmen", description = "Die Sasquatch mögen die größere Bedrohung sein, aber zuerst müssen wir uns um die Oger kümmern. Die Gordunni sind uns schon lange ein Dorn im Auge und Lady Shandris möchte, dass wir sie ausmerzen. Hoffen wir, dass es wirklich die letzten sind.\n\nTötet die Zähmer der Gordunni, die die Biester in Ketten halten, und stellt sicher, dass sie den Preis für ihre Taten zahlen werden.", sourceObjective = "Tötet 6 Zähmer der Gordunni.", completion = "Gute Arbeit - die sind wir los! Ich hoffe, wir werden hier nie wieder irgendwelche Oger sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25435] = { id = 25435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwimmt Euch in den Sattel", description = "'N Tag, <Kumpel/Mädel>.\n\nIch bin Rendel.\n\nSieht aus, als wär'n die gute alte Moanah und ich gerade rechtzeitig hier eingetroffen, was?\n\nErunak hat nicht gescherzt, als er sagte, es ginge um Leben oder Tod!\n\nWährend er sich bemüht, ein kuscheliges Versteck für uns zu finden, werd' ich mal versuchen, Euch ein Reittier zu sichern.\n\nIch bin jetzt vielleicht nicht so auf dem Laufenden, was das Leben im Meer angeht, aber die Naga scheinen hier unten bestens zurecht zu kommen.\n\nWarum sucht Ihr nicht ein paar Kleinigkeiten für das Zaumzeug zusammen? Ich arbeite solange schon einmal an der Verzauberung.", sourceObjective = "Sammelt 3 Haisehnen von gefräßigen Dreschern und 2 geschärfte Krebsscheren von Säbelklauenhuschern.\n\nIhr könnt die gefräßigen Drescher auch mit Krebsinnereien herbeirufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25436] = { id = 25436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boshafte Schwestern", description = "Es ist etwas sehr beunruhigendes passiert. Auf einer ihrer Patrouillen wurden ein paar meiner Späher von Dryaden angegriffen.\n\nDie Dryaden sind enge Verbündete der Nachtelfen und Wächter des Waldes. Zuerst dachte ich, der Anblick der Worgen hätte ihnen Angst eingejagt, aber auch die Schildwachen, die ich danach losgeschickt habe, wurden angegriffen.\n\nIch weiß nicht, was hier vor sich geht, aber ich weiß, dass es mir nicht gefällt. Ich möchte, dass Ihr die Sache untersucht. Wenn auch die Dryaden der Verderbnis zum Opfer gefallen sind, so müsst Ihr sie töten.", sourceObjective = "Tötet 8 verderbte Dryaden.", completion = "Ich möchte Euch nicht ängstigen, aber wir befinden uns in einer furchtbaren Lage. Wenn das Portal im Traumgeäst verschlossen wurde und die Verderbnis sich trotzdem weiter ausbreitet...", sourceObjectiveStatus = "unverified-source-field" }
quests[25437] = { id = 25437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Aufforderung", description = "Ein Drache des smaragdgrünen Traums... worauf habt Ihr Euch nur eingelassen, {name}?\n\nIch würde sie an Eurer Stelle nicht warten lassen. Der Ort, von dem sie sprach, ist der Smaragdgipfel. Ein Pfad, weitab der Hauptstraße, führt durch die Untere Wildnis zu den hohen Steinplateaus. Dort befindet sich ein Schrein.\n\nIch wünsche Euch viel Glück, {name}. Ich hoffe, Ihr kommt sicher zurück.", sourceObjective = "Sprecht mit Ysondre auf dem Smaragdgipfel in der Unteren Wildnis.", completion = "Ihr seid angekommen.\n\nIch schäme mich, Euch diese Aufgabe aufzubürden, {class}, aber ich bin schon zu lange vor ihm auf der Flucht. Taerar muss aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25438] = { id = 25438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Abschied", description = "Nun bin nur noch ich übrig.\n\nSelbst wenn ich in dieser Welt bleiben sollte, so kann ich dem grünen Schwarm nicht wieder beitreten. Dieser Sieg erfüllt mich jedoch mit Hoffnung. Vielleicht kann ich zu gegebener Zeit ein einfaches Leben in Frieden unter den Sterblichen führen.\n\nIhr müsst zu Eurem Volk zurück. Berichtet ihnen, dass die Drachen des Alptraums nicht länger sind und diese Länder nicht mehr bedrohen werden.", sourceObjective = "Sprecht mit Adella im Schattengeäst.", completion = "In einen Kampf der Drachen verwickelt zu werden... ich weiß nicht, ob Ihr gesegnet oder verflucht seid.\n\nLady Shandris hat von all Euren Taten gehört und hat Euch dies persönlich als Belohnung überbringen lassen. Ich bin froh, dass Ihr heil hier angekommen seid, um es in Empfang zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25439] = { id = 25439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rachsüchtige Herz", description = "Das sind die Naga, die unsere Leute entführt haben. Ich brauche nur einen, um ihn zu befragen. Tötet den Rest.\n\nHabt kein Erbarmen, {class}, denn auch sie würden uns kein Mitleid gewähren.", sourceObjective = "Tötet 10 Verheerer des Zin'jatar.", completion = "Es ist gut, einen echten Krieger an meiner Seite zu haben. Meine Schamanenbrüder sind der Aufgabe zu oft einfach nicht gewachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25440] = { id = 25440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenlord Zin'jatar", description = "Der Tiefenlord ist hier, am anderen Ende der Ruinen. Er hat noch einige Verletzungen von unserer letzten Schlacht.\n\nIch überlasse Euch das Vergnügen, aber gebt Acht, dass er uns dieses Mal nicht entwischt!", sourceObjective = "Tötet Tiefenlord Zin'jatar.", completion = "Und damit verebben ihre Angriffe auf uns hoffentlich für eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[25441] = { id = 25441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "Ich bin kein Freund von Schlangen, noch weniger von denen hier unten. Zu unserem Glück gehorcht das Wasser vorerst noch meinem Willen.\n\nNehmt diese Kugeln und werft sie auf den Boden, damit sich ein Vortex bildet, der alle Schlangen in der Nähe mit sich reißt. Die Naga werden die Schlangen sicher gegen uns einsetzen, also tragt die Kugeln besser immer bei Euch.", sourceObjective = "Benutzt die Kugeln des stürmischen Wassers, um 30 schwärmende Schlangen einzufangen.", completion = "Wir werden oft mit Druiden verwechselt. Bei einigen Schamanen mag das ja stimmen, aber lasst Euch nicht von dem allgemeinen Irrglauben täuschen, dass wir immer friedlich wären.\n\nNichts von dem, was ich tue, ist harmonisch. Ich beherrsche die Elemente ganz so, wie ich es will. Dafür gibt es keine Gegenleistung. Und ich würde es mir auch nicht anders wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25442] = { id = 25442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Perle der Weisheit", description = "<Diese Perle ist anders als alles, was Ihr je gesehen habt. Sie verströmt Licht und, falls Ihr Euch nicht täuscht, auch mächtige Magie.>\n\n<Erdheiler Duarn in der Silberfluthöhle wäre sicher sehr an ihr interessiert.>", sourceObjective = "Bringt die leuchtende Perle zu Erdheiler Duarn in der Silberfluthöhle.", progress = "Ja, {class}? Habt Ihr etwas gefunden?", completion = "Was ist das? Eine Perle? Hm, viel mehr noch, glaube ich.\n\nGenau danach habe ich gesucht. Vielen Dank, dass Ihr sie mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25443] = { id = 25443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Unaussprechliche", description = "Hat mein Trank gewirkt? Habt Ihr mit einem von ihnen gesprochen?\n\nDann wisst Ihr ja, was zu tun ist. Der Name ihres Elementarmeisters steht auf drei Feuersteinen geschrieben, die überall im Inferno verstreut sind. Überprüft jeden einzelnen von diesen Steinen und wir haben den Namen, den wir brauchen.\n\nSchnell! Euer geliebter Wald brennt!", sourceObjective = "Setzt den wahren Namen zusammen, indem Ihr die drei Feuersteine im Inferno untersucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25444] = { id = 25444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekten Spione", description = "Es wär dumm, hia blind zu arbeiten, also mach' ich 'n paar winzige Spione, die für Vol'jin Informationen sammeln soll'n. Er muss wissen, was drüben auf den Inseln passiat.\n\nIch könnt' die Hilfe brauch'n, wenn Euch danach is. Ich sag' Euch, was zu tun is. East müsst Iah die Frösche fang'n. Sie bleim gean im Schatten dea Palmen um Sen'jin rum.\n\nWenn Iah die Frösche habt, bringtse hia rüber zu mei'm Totem des Wachens un' stimmt se auf meine Sicht ab.", sourceObjective = "Fangt 5 Frösche aus Sen'jin und stimmt sie bei Vaniras Totem des Wachens auf ihre Sicht ab.", progress = "Helft Iah jetzt mit die Frösche oder nich?", completion = "Das is genug für meine Zwecke. Nu zum schwierigen Teil.", sourceObjectiveStatus = "unverified-source-field" }
quests[25445] = { id = 25445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazanes Sturz", description = "Die Zeit zum Kämpfen ist jetzt! Schon bald brechen wir auf zu den Inseln, halt dich also bereit.\n\nZalazane hat nicht mehr viel Zeit.", sourceObjective = "Helft Vol'jin die Echoinseln zurückzuerobern und Zalazane zu töten.", completion = "{name}, du bist ein mächtiger Krieger und ein leidenschaftlicher Kamerad der Dunkelspeere. Die Echoinseln sind jetzt UNSER und wir hätten es ohne dich nie schaffen können.\n\nNimm diesen Umhang. Trag ihn mit Stolz. Jetzt bist du Mitglied des Stamms!\n\nBald haben die Trolle wieder eine Heimat und wir haben dir dafür zu danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25446] = { id = 25446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frösche frei!", description = "Nu, wo die Frösche startklar sin', brauch' ich Eure Hilfe, um sie rüba auf die Inseln zu schick'n.\n\nIm Osten von Sen'jin is Tiaführer Marnlek. Eah füaht die Fledamäuse für Vol'jins Späher und kann Euch 'ne Fledermaus leih'n, um raus zu den Inseln zu kommen.\n\nNehmt den Sack Frösche hia mit. Ich hab' die Geista um Hilfe gebeten. Sie ham Rauch geschickt, um Euch zu zeig'n, wo ich die Augen am meisten brauch. Wenn Iah auf'er Fledermaus sitzt, greift in'n Sack un' werft die Frösche in'n weißen Rauch.", sourceObjective = "Benutzt, während Ihr Euch auf dem Rücken einer Fledermaus befindet, den Sack Frösche, um 12 abgestimmte Frösche bei den Markierungen auf den Echoinseln zu platzieren.", completion = "Ich seh' schon, was die Frösche seh'n. Iah habt das pafekt gemacht, {name}. Nu können Vol'jin un' ich seh'n, was Zalazane voahat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25447] = { id = 25447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Wandels", description = "Eine üble Krankheit hat die Kreaturen unseres Waldes heimgesucht. Zuerst dachte ich, es wäre einfach eine der Tücken der Natur, aber der Krankheit scheint kein Heilungsprozess zu folgen.\n\nDie Hirsche des Waldes, die normalerweise sehr stark und friedlich sind, haben am meisten gelitten. Einige finden in ihrer Schwäche ihr Ende. Andere sind tollwütig und sehr gefährlich. Um die Geister zu befragen und mehr über die Krankheit in Erfahrung zu bringen, benötige ich die Geweihe der Hirsche.", sourceObjective = "Sammelt 8 infizierte Hirschgeweihe.", progress = "Es ist keine schöne Aufgabe, aber es muss getan werden, {name}.", completion = "Zumindest haben wir dem Leiden dieser Kreaturen ein Ende bereitet. Lasst uns hoffen, dass durch ihr Opfer weiteres Leid verhindert werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25448] = { id = 25448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nordschwingenbedrohung", description = "Meine Aufgabe ist es, über Telaron zu wachen. Auch ohne die Meditation, die ihn so verletzlich macht, gibt es in diesem Wald genügend Bedrohungen, die uns beschäftigen.\n\nGenau deshalb stört es mich so sehr, dass ich das Camp nicht verlassen kann. Mehr Harpyien als je zuvor suchen das Gebiet im Nordwesten heim... bösartige Kreaturen, die ihren Dreck überall in den alten Ruinen hinterlassen und sich nicht daran stören.\n\nSie sind eine Bedrohung für unser Lager und haben an diesen Orten nichts zu suchen. Ich werde Euch reichlich belohnen, wenn Ihr Euch ihnen annehmt.", sourceObjective = "Tötet 6 Harpyien der Nordschwingen und 6 Windruferinnen der Nordschwingen.", completion = "Danke, {class}. Eine Störung weniger, um die ich mich kümmern muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25449] = { id = 25449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen der Qualität", description = "Meine Einstellung zur Lederverarbeitung verlangt, dass die Arbeit von bestmöglicher Qualität zu sein hat - ohne Kompromisse. Jeder, der behauptet, Qualität sei unwichtig, wird auch versuchen, Euch ein Küstengrundstück in Dun Morogh zu verkaufen!\n\nAuf meiner jüngsten Suche nach hochwertigem Material fand ich dicke Yetibälge. Die Yetis sind in Feralas zuhause und viele findet man in der Wutschrammfeste im Nordosten. Ich hätte gern ein paar Bälge und wenn Ihr mir zehn davon bringt, dürft Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Haltet Ihr das für angemessen? Dann sind wir im Geschäft.", sourceObjective = "Sammelt 10 dicke Yetibälge.", progress = "Für zehn Yetibälge könnt Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Qualität ist mir wichtig und Ihr könnt Euch sicher sein, dass Ihr etwas Hochwertiges erhalten werdet!", completion = "Hattet Ihr die Zeit, die Beschaffenheit dieser Bälge zu bewundern? Richtig verarbeitet können sie widerstandsfähiger sein als Eisen. Nur wenige Leute sind mit diesen Bälgen vertraut und in Verbindung mit bestimmten Lösungen kann ich damit richtige Qualitätswaren herstellen - dank Euch natürlich!\n\nBitte, sucht Euch etwas aus meinem Sortiment aus, als Dank für Eure Mühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25450] = { id = 25450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Es ist schon faszinierend, wie sich die Dinge ändern. Die Yetis aus dem Norden haben immer die besten Bälge gehabt, aber diese hier... die Qualität ist wirklich nicht so gut wie sie einst war. Vielleicht sind sie krank, oder werden von etwas krank gemacht.\n\nGlücklicherweise sieht es bei den Wildschrammyetis viel besser aus als früher. Ich wette, dass ihre Bälge jetzt weitaus besser als früher sind!\n\nIch würde Euch für zehn ihrer Bälge gebührend entlohnen. Bringt mir die Bälge, und wir sind im Geschäft.", sourceObjective = "Sammelt 10 Wildschrammyetibälge.", progress = "Diese Bälge sind zwar nicht so widerstandsfähig wie Thorium, aber sie sind gut und fest.", completion = "Exzellent, Exzellent! Ich denke, diese Bälge werden ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, {name}. Hier, nehmt eine meiner neuesten Kreationen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25451] = { id = 25451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Yetibalg", description = "Ihr habt einen makellosen Yetibalg gefunden, der besonders dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Pratt McGrubben in der Mondfederfeste mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste den makellosen Yetibalg.", progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Fantastisch! Es sieht so aus, als hättet Ihr die Mutter aller Yetibälger gefunden!\n\nIhr könnt Euch darauf verlassen, dass mir dieser Fund einiges wert ist. Normalerweise zahle ich niemandem so viel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, dass Ihr bei Eurem Fund an mich gedacht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25452] = { id = 25452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen der Qualität", description = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!\n\nAuf meiner jüngsten Suche nach hochwertigem Material habe ich dicke Yetibälge entdeckt. Die Yetis sind in Feralas beheimatet und man findet sie nördlich von hier, in der Wutschrammfeste. Ihr dürft Euch ein beliebiges Stück meiner Lederwaren aussuchen für einen Zehnerstapel Yetibälge. Wenn das für Euch akzeptabel ist, dann sind wir im Geschäft!", sourceObjective = "Sammelt 10 dicke Yetibälge.", progress = "Konntet Ihr alle Yetibälge besorgen? Meine Lederwaren sind unvergleichlich und ich werde Euch ein Stück meiner handverarbeiteten Qualitätswaren zukommen lassen, wenn Ihr die Bälge habt.", completion = "Ah, wunderbar! Ich sage Euch, diese Bälge sind so widerstandsfähig wie Eisen, man muss ihnen nur eine besondere Behandlung zuteilwerden lassen. Es wird einige Versuche kosten, die richtige Mischung zum Gerben zu finden, aber ich bin zuversichtlich, dass sie mein Zeichen der Qualität noch weiter aufwerten werden.\n\nAber nun zu Euch, {name}: Eure Hilfe hat sich als unschätzbar für mich erwiesen. Bitte sucht Euch einen der Gegenstände aus, die ich hergestellt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25453] = { id = 25453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Ich bin etwas verwirrt. Die Wutschrammyetis waren einst die Quelle des besten Leders dieser Länder... aber diese Bälge sind schwach und an manchen Stellen verrottet. Die Kreaturen müssen an einer Art Krankheit leiden.\n\nIch werde eine andere Bezugsquelle finden müssen. Die Yetis aus Wildschrammtal im Süden haben auch sehr starke Bälge. Sie sind aber auch viel gefährlicher; man sollte bei der Jagd auf sie sehr vorsichtig sein.", sourceObjective = "Sammelt 10 Wildschrammyetibälge von Wildschrammyetis.", progress = "Sind die Wildschrammyetis noch da? Habt Ihr die Bälge?", completion = "Exzellent, Exzellent! Ich denke, diese Bälge werden ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, {name}. Hier, nehmt eine meiner neuesten Kreationen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25454] = { id = 25454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekter Yetibalg", description = "Ihr habt einen Yetibalg gefunden, der beinahe perfekt scheint. Euch fällt schnell auf, dass dieser außergewöhnlich dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Jangdor Flinkschreiter in der Festung der Steinbrecher mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Jangdor Flinkschreiter in der Steinbrecherfestung in Feralas den perfekten Yetibalg.", progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Dieser Fund ist einfach unglaublich! Ich glaube dies hier ist der beste Balg, den ich je gesehen habe!\n\nTatsächlich wäre hier eine großzügige Belohnung angebracht. Normalerweise zahle ich niemandem so viel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, dass Ihr bei Eurem Fund an mich gedacht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25456] = { id = 25456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unversehrte Rückkehr", description = "Ja, ja, ich bin mir sicher, dass Felora Euch zurückhaben möchte. Diese Frau hat einfach keinen Respekt vor Innovationen. Als ich ihr von den Modifizierungen für meinen Erdelementar erzählt habe, hat sie fast einen Anfall bekommen.\n\nGeht schon und sagt ihr, dass alles fein und klärchen ist. Und sagt ihr auch, dass ich ihr nichts von meinem unausbleiblichen Vermögen abgeben werde.\n\nWahrscheinlich schläft sie sowieso am liebsten auf dem Felsen.", sourceObjective = "Kehrt zu Felora Feuerkranz in der Silberfluthöhle zurück.", completion = "Also ist Sam unversehrt? Und seine arme Assistentin Felice? Das ist gut zu hören.\n\nIch hoffe, dass die Elemente für ihn eines Tages mehr als nur Werkzeuge sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25458] = { id = 25458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Skessesh", description = "Die Anführer dieser Streitmächte müssen fallen! Die Offensive der Naga wird zerbrechen, wenn niemand mehr da ist, um sie anzuführen.\n\nIch habe gesehen, wie der Feigling sich in einem der verlassenen Gebäude versteckt hat. Bahnt Euren Weg durch die anderen und besorgt mir seinen Kopf! Lady Shandris wird ihn selbst in den Händen halten wollen.", sourceObjective = "Tötet General Skessesh und nehmt seinen Kopf.", progress = "Ist der General gefallen?", completion = "Gut gemacht, diese garstigen Kreaturen verdienen es nicht anders. Mögen die Naga ins Meer zurückglitschen und diesen Ort nie wieder aufsuchen.\n\nIhr habt Euch auf dem Schlachtfeld bewiesen, {name}. Ich werde bei der Verteidigung dieser Länder Eure Hilfe noch öfter in Anspruch nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25459] = { id = 25459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ophidophobie", description = "Wenn es eine Sache gibt, die ich nicht leiden kann, dann sind es Schlangen. Alle Schlangen, egal welche Art.\n\nWährend ich da draußen nach verwertbaren Teilen gesucht habe, habe ich ein Nest von Seeschlangen um das nahegelegene Wrack herum gesehen.\n\nIch fühle mich einfach nicht wohl bei dem Gedanken, dass diese schrecklichen Biester sich jeden Moment hier herein schlängeln könnten.\n\nBitte, {class}! Unternehmt etwas gegen sie!", sourceObjective = "Tötet 4 Laugenschuppenschlangen in Gorroks Klage.", completion = "Da fällt mir aber ein Stein vom Herzen.\n\nVielen Dank noch einmal, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25460] = { id = 25460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde erhebt sich", description = "Sogar hier, so nahe am Weltenbaum, fühlen wir die Folgen des Angriffs des Schattenhammers.\n\nUnd da die Bäume in Flammen stehen, wendet sich sogar die Erde in rasendem Zorn gegen uns.\n\nWir dürfen nicht zulassen, dass die Elementare frei durch die Gegend streifen. Geht und helft unseren Männern, ihrer Herr zu werden.", sourceObjective = "Tötet 8 brühende Felselementare.", completion = "Ich danke Euch, {name}. Euer Kampfgeschick ist beeindruckend. Ihr werdet in unserem Bestreben, dem Angriff der Elementare ein Ende zu setzen, eine entscheidende Rolle spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25461] = { id = 25461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwillige Trolle vor!", description = "Vol'jin hat mir seine Kriegstrommeln gegeben und mia die Verantwortung für die Ausbildung von den neuen Rekruten hia übageben. Das Dumme is nur, dass wia keine neuen Rekruten ham.\n\nWenn ich Euch diese Trommel leih'n wüade, wüadet Iah füa Vol'jin nach Klingenhügel gehn un da den Kriegsruf vabreiten? Wenn Iah auch nua n paar Trolle dazu inspirian könntet, sich anzuschließn, wüade das schon nen Untaschied machen. Wenn Iah sie übazeugt habt, sich freiwillig zu meld'n, bringt sie zu mia zum Ausbilden zurück. Geht rüba zu Tiaführer Marnlek im Süd'n. Eah kann Euch eine Fledamaus für den Flug nach Klingenhügel leih'n.", sourceObjective = "Benutzt Vol'jins Kriegstrommeln, um 5 Trollbürger in Klingenhügel zu rekrutieren.\n\nIhr könnt mit Tierführer Marnlek sprechen, um eine Fledermaus nach Klingenhügel zu bekommen.", progress = "Wia brauch'n alle Freiwilligen, die wia krieg'n könn'.", completion = "Iah habt 'n paa gute Rekrut'n gefund'n. Ich trainier' sie hart, un' wia wern nich' aufhör'n, bis wia Zalazane von unsern Inseln vartrieben ham.", sourceObjectiveStatus = "unverified-source-field" }
quests[25462] = { id = 25462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter kommen sie alle", description = "Fürchtet Euch nicht vor den Bären in diesem Hain, {class}. Ich habe sie für eine Weile besänftigt.\n\nIch sorge mich vielmehr um das Wohlergehen der Bärenjungen. Aus Angst vor dem Feuer sind die Kleinen auf die Bäume geflüchtet und sitzen jetzt dort fest. Wir müssen die Bären wieder heil auf den Boden bringen!\n\nFliegende Wesen schüchtern sie ein, also müsst Ihr wohl selbst auf die Bäume klettern. Sucht die Stämme nach geeigneten Stellen ab, klettert auf die Bäume, schnappt Euch die Bären und werft sie VORSICHTIG auf das Ziel hier.\n\nDieser Plan ist narrensicher.", sourceObjective = "Klettert auf die Bäume im Rauschenden Hain, greift nach hilflosen Hyjalbärenjungen und werft sie oben vom Baum aus auf das weiche Ziel. Ihnen kann nichts passieren.", completion = "Ich danke Euch, {name}. Diese kleinen Bären haben einiges mitgemacht, aber sie werden überleben.\n\nZumindest die, die auf der Matte gelandet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25463] = { id = 25463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichtet Silvia", description = "Ein hochgeborener Magus namens Estulan hat östlich von hier einen Turm gebaut, nachdem er sich von seinen überlebenden Brüdern entfremdet hat, und unterrichtet dort nun junge Nachtelfen in arkaner Magie.\n\nWenn Hohepriesterin Tyrande nicht vor Kurzem Gnade über die Seinen hätte walten lassen, so wäre es nun laut unserer Gesetze meine Aufgabe, ihn hinzurichten. Er wird streng bewacht, doch nur aus Stolz kann ich den Schildwachen Hilfe nicht abschlagen.\n\nIch habe Silvia vorgeschickt, um beim Turm von Estulan die Offensive gegen die Oger in der Nähe einzuleiten, die die Wälder in der Nähe heimsuchen. Meldet Euch bei ihr, um weitere Anweisungen zu erhalten.", sourceObjective = "Meldet Euch bei Siliva am Turm von Estulan.", completion = "Gut, Euch hier zu sehen. Estulan ist... schwierig. Wir werden uns zuerst für Shandris alleine um die Oger kümmern müssen, bevor Estulan eine Entscheidung treffen wird, ob er uns helfen möchte oder nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25464] = { id = 25464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Geddons Rückkehr", description = "Ragnaros ist nicht der einzige mächtige Elementar, der wieder in unsere Welt gelangt ist.\n\nDer gefürchtete Baron Geddon führt das Massaker an. Wir müssen seiner Zerstörungswut ein Ende setzen.\n\nDer Flammenseherstab hat sich als sehr mächtig erwiesen. Vielleicht ist er mächtig genug, um den Baron so zu schwächen, dass unsere Erzdruiden ihn an Ort und Stelle fesseln können.\n\nGeht, {name}, und seid vorsichtig. Baron Geddon ist ein rachsüchtiges und heimtückisches Wesen.", sourceObjective = "Nutzt die Macht des Flammenseherstabs, um Baron Geddon zu schwächen.", completion = "Gut gemacht, {name}. Wir können es uns nicht leisten, noch mehr Gebiete auf dem Hyjal zu verlieren.\n\nBaron Geddon auszuschalten hat unserem Feind einen schweren Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25465] = { id = 25465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch am Riesen schrumpfen", description = "He, Ihr da! Ich arbeite immer noch an einer Variante von gnomischen Schrumpfstrahlen, benutze aber die weitaus bessere GOBLIN-Technologien dafür! Um Unannehmlichkeiten wie beispielsweise meinen Tod zu vermeiden, möchte ich Euch bitten, es für mich an den Meeresriesen an der Küste zu testen. Ihr solltet nach dem Prozess Schrumpfüberreste auf ihnen finden, bringt mir diese bitte!", sourceObjective = "Benutzt Zorbins Ultraschrumpfer, um Uferschreiter zu schrumpfen und sammelt 6 Schrumpfüberreste.", progress = "Ich musste den Schrumpfer überarbeiten, damit er nicht mehr bei Bergriesen funktioniert. Ich bin zwar nicht rumgerannt und hab wie wild alles geschrumpft, aber die Nachtelfen haben mir ganz schön einen übergehauen, als sie gesehen haben, dass die Bergriesen geschrumpft waren.", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultraschrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, {name}. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[25466] = { id = 25466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Treibstoff fürs Schrumpfen", description = "Wenn ich gegen mein besseres Wissen und Gewissen handele und nun doch bleibe, um meinen Ingenieurladen an der Vergessenen Küste aufzumachen, muss ich mich dringend um diese nervigen Elementare kümmern. Verdammt sei der unkontrollierte Elementalismus, sage ich!\n\nGlücklicherweise stellen die Elementare eine ideale Quelle reiner Kraft für meinen Ultraschrumpfer dar – insofern, gebt ihnen Saures! Wenn Ihr dies allerdings tut, bringt mir doch bitte auch ein paar Elementarkerne.", sourceObjective = "Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern.", progress = "Ich könnte Euch natürlich auch mit den technischen Einzelheiten langweilen, die sich hinter den Elementarkernen verstecken, aber stattdessen werde ich Euch dazu bringen, diese Aufgabe abzuschließen, indem ich Euch wertvolle Münzen und Belohnungen dafür anbiete. Seid Ihr schon fertig?", completion = "Hervorragend! Diese Kerne werden mich einige Zeit beschäftigen. Nicht zu vergessen, dass es entlang der Küste nun weniger Elementare gibt, die uns Sorgen bereiten werden. Möglicherweise muss ich mich jetzt nicht mehr in den Schlaf weinen, wenn ich daran denke, dass ich mein Lager ausgerechnet am schlimmsten Ort der Welt aufgeschlagen habe.\n\nVielen Dank, {name}, für Eure Hilfe in dieser Angelegenheit. Es mag vielleicht meine Finanzen ein wenig überstrapazieren, aber ich denke, ich möchte mein Wohlwollen Euch gegenüber in einer Weise ausdrücken, die Ihr versteht... ich hätte da etwas Ausrüstung für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[25467] = { id = 25467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kliklaks Kehle", description = "<Ihr seid angenehm überrascht, dass die Karte noch gut lesbar ist, nachdem sie von einem Meereskrebs so zerfetzt und zerkaut wurde.>\n\n<Sie zeigt ganz deutlich, dass im Tang'tharwald hinter einem riesigen Schalentier eine Schließkiste vergraben liegt.>\n\n<Eine gut getroffene Zeichnung auf der Rückseite der Karte zeigt, dass der Besitzer zusammen mit dem Schlüssel von einem überdimensionalen Krustentier namens Kliklak gefressen wurde.>", sourceObjective = "Beschafft Euch den rostigen Schlüssel von Kliklak, um die halb vergrabene Schließkiste im Tang'tharwald zu öffnen.", progress = "<Das Schlüsselloch der Kiste ist mit kleinen Muscheln verkrustet, sieht aber noch funktionstüchtig aus.>", completion = "<Dem befriedigenden Geräusch einer sich öffnenden Truhe folgt der Anblick eines einst versteckten Schatzes.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25468] = { id = 25468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Feendrachen", description = "Man sieht es ihnen wirklich nicht an, aber die reizenden Feendrachen dieses Waldes können sich mit der richtigen Abrichtung als furchterregend erweisen. Sie können unglaubliche Sachen mit magischer Energie anstellen... sie aufsaugen, umleiten und sogar komplett auslöschen.\n\nAlleine sind sie beinahe harmlos, aber in Gruppen können sie in einem Kampf für überwältigende Ergebnisse sorgen. Ihr könnt Feendrachen in den Feldern nordwestlich von hier finden, aber seid vorsichtig, denn die Horde ist in der Nähe.", sourceObjective = "Benutzt Jesanas Feendrachenlockruf, um 10 Grimmlingdrachen oder Grimmlingflitzer zu versammeln.", completion = "Sind sie nicht entzückend? Die Welpen sind sogar noch süßer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25469] = { id = 25469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Bergriesen", description = "Die Bergriesen sind unsere mächtigsten Verbündeten in den Wäldern. Sie bestehen aus dem Land selbst.\n\nWenige unserer Feinde wollen sich mit einem wandelnden Berg anlegen. Schon allein ein paar wenige Bergriesen können den Ausgang einer Schlacht bestimmen.\n\nDie Bergriesen hier leiden aber seit einiger Zeit an einer Krankheit - die Bergriesen im Südwesten scheinen aber gesund zu sein.", sourceObjective = "Benutzt Jesanas Riesenlockruf, um 5 Bergriesen zu versammeln.", completion = "Ausgezeichnet!\n\n{name}, Ihr habt uns geholfen, unsere Streitkräfte zu stärken und habt viele dieser Waldkreaturen vor der Horde gerettet. Unsere Armee ist bereit und Mondfederfeste wird allen Bedrohungen standhalten, von der Horde und anderen Feinden!\n\nIm Namen von Lady Mondfeder überreiche ich Euch diese Waffe, die einer Schildwache würdig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25470] = { id = 25470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin der Tiger", description = "Erinnat Iah Euch an die Frösche, die Iah zu mein'n Augen un' Ohren gemacht habt? Tja, die ham was Intressantes gefund'n.\n\nAuf 'ner Insel im Südosten ham sie 'nen Tiger entdeckt, den soga die andern Katzen fürcht'n. Diesa Tiger, so was hab'ich noch nie geseh'n.\n\nDea jagt mit'm Instinkt von 'ner Katze, aber dem Vastand von 'ner Person. Könnte 'n mächtiger Geist sein, und 'n starka Vabündeta.\n\nIch ruf den Geist vom Tiger auf Euch runter. Benutzt seine Talente, um die Katze zu find'n un' rauszufordern. Seht zu, dass Iah ihre Hilfe in unserm Kampf um die Inseln gewinnt.", sourceObjective = "Lockt die Tigermatriarchin aus ihrem Versteck, während Ihr vom Geist des Tigers erfüllt seid, und benutzt Eure neuen Fähigkeiten, um sie im Kampf zu besiegen.", progress = "Habta schon was üba diesen Tiger rausgefund'n?", completion = "Vaniras Frösche sagen also die Wahrheit? Dieser Tiger ist eine Druidin und eine Verbündete? Das hätte nicht besser laufen können. Das ist ein gutes Omen für die kommende Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25471] = { id = 25471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über den Großen Graben", description = "Wenn wir herausfinden wollen, was die Naga hier vorhaben, müssen wir weiter nach Vashj'ir vordringen.\n\nGeht zu den Lichtlosen Weiten, der riesigen Schlucht, die an den Tang'tharwald im Westen grenzt. Wenn Ihr hinüberseht, solltet Ihr eine Ansammlung von Pflanzen sehen, die den Eingang zur Dunstlichtkammer umgeben.\n\nSobald Ihr in der Höhle seid, dauert es eine ganze Weile, bis Ihr an die Oberfläche kommt, aber ich habe dort Freunde, die Euch herzlich willkommen heißen werden.", sourceObjective = "Sprecht mit Scharfseher Gadra in der Dunstlichtkammer.", completion = "Hallo, Mann! Ihr seht kompetenter aus als die meist'n, die hier durchkomm'n.\n\nKommt und ruht Euch 'n wenig aus. Fühlt Euch ganz wie daheim!", sourceObjectiveStatus = "unverified-source-field" }
quests[25472] = { id = 25472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flammenseherstab", description = "Ein mächtiges Artefakt, das als Flammenseherstab bekannt ist, befand sich das letzte Mal, als der Hyjal angegriffen wurde, im Besitz eines Ältesten der Tauren. Es war ein uralter Knochenstab, der seinem Besitzer die Macht über die Feuerelemente verlieh.\n\nSeine Fragmente sind überall hier verstreut. Findet sie und bringt sie zu Malfurion. Vielleicht können wir die Macht des Artefakts noch nutzen.", sourceObjective = "Sammelt 8 verkohlte Knochenstabfragmente.", progress = "Ja, {name}?", completion = "Ausgezeichnet, {name}. Dies wird eine ausgezeichnete Waffe gegen die feindlichen Armeen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25473] = { id = 25473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola", description = "Sassy Hartzang hat mich damit gelöchert, ihr etwas Kaja'Cola für die Party zu Euren Ehren heute Abend zu besorgen.\n\nUps, war das eine Überraschung? Von mir habt Ihr es nicht!\n\nNaja, aber mit dem Produktionstief der letzten paar Tage ist das hier alles, was ich herstellen konnte. Könntet Ihr es ihr bringen?", sourceObjective = "Bringt das Sechserpack Kaja'Cola zu Sassy Hartzang im Hauptquartier der HGK in Kezan.", progress = "<Sassy beobachtet das Sechserpack als würde sie erwarten dass es explodiert, sobald Ihr es ihr gegeben habt.>\n\nWir brauchen mehr Kaja'Cola als das.\n\nIch schwöre, ich werde Feuchtlunte feuern, wenn ich ihn nicht zuerst umbringe!", completion = "Nur dass Ihr es wisst: Kaja'Cola gibt es überall hier im Ort. Es ist das meistverkaufte Produkt des Bilgewasserkartells aller Zeiten! \n\nVergesst nicht, dass ein gepflegtes Image das A und O ist, wenn Ihr auf eine weitere Beförderung aus seid!\n\nNein, wartet! Profit ist das A und O! Aber Explosionen kommen gleich danach. Und dann: Image!", sourceObjectiveStatus = "unverified-source-field" }
quests[25474] = { id = 25474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmaal mit Gefühl", description = "Aale gehören zu den widerlichsten Wesen in ganz Azeroth.\n\nSicher, da gibt es diejenigen, denen sie angeblich egal sind. Und dann noch diejenigen, die sogar behaupten, sie zu mögen.\n\nSie lügen.\n\nIn Wahrheit mag nämlich niemand Aale. Nicht einmal Aale mögen Aale.\n\nAzeroth wäre ein besserer Ort, wenn niemand sich ausmalen müsste, wie ein glitschiger Aal sich aus den trüben Tiefen hervor windet und zubeißt.\n\nMitten ins Gesicht.", sourceObjective = "Tötet 15 beliebige Aale im Tang'tharwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[25475] = { id = 25475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet OOX-22/FE!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zum Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Glotz Widrikus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe des Wildschrammtals abgestürzt!\"", sourceObjective = "Bringt das Notrufsignal zu Glotz' Leitroboter in einer Höhle in der Nähe des Wildschrammtals.", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Beutebucht zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Glotz ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-22/FE funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[25476] = { id = 25476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet OOX-22/FE", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder zum Funktionieren zu bringen. Eskortiert den Roboter von seinem momentanen Standort zu, ach, sagen wir mal, der Hauptstraße. Das sollte der perfekte Ort für mein Vorhaben sein und bis Ihr dort seid, sollte ich auch alles vorbereitet und aktiviert haben.\"\n\n\"Eskortiert ihn dorthin und kommt dann zu mir nach Beutebucht! Glotz Widrikus - Ende!\"", sourceObjective = "Bringt OOX-22/FE in Sicherheit und meldet Euch dann bei Glotz Widrikus in Beutebucht.", completion = "Ach, IHR habt so heldenhaft OOX-22/FE gerettet! Ich kann meine Dankbarkeit für Eure Hilfe nicht einmal ansatzweise ausdrücken! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, {name}; meine Roboter und ich stehen in Eurer Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[25477] = { id = 25477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als tot", description = "Grüße, Freund.\n\nSchön zu sehen, dass Ihr die Schlacht heil überlebt habt.\n\nWährend Erunak nach einem sicheren Zufluchtsort für uns sucht, werde ich Euch dabei helfen, ein weniger anstrengendes Transportmittel zu finden.\n\nIch habe Euch einen Köderstab vorbereitet. Benutzt ihn in der Nähe einer Meeresschildkröte. Es ist vielleicht etwas primitiv, aber damit solltet Ihr das Tier unter Eure Kontrolle bekommen.\n\nSobald Ihr Euch mit der Schildkröte vertraut gemacht habt, führt sie einfach hierher zu mir.", sourceObjective = "Benutzt Moanahs Köderstab bei einer gesprenkelten Meeresschildkröte und reitet dann mit ihr zurück zu Moanah.", progress = "Konntet Ihr eine Meeresschildkröte zähmen, {name}?", completion = "Wie überaus bedauerlich…\n\nNun, in Anbetracht der Tatsache bin ich froh, dass Ihr unversehrt zurückgekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[25478] = { id = 25478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gipfel", description = "Wir sind dabei, am Westlichen Gipfel für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Der Goblin Dyslix Silberraff wird Euch meinen Windreiter zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Kanati Grauwolke, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Dyslix Silberraff einen Windreiter und sprecht mit Kanati Grauwolke am Westlichen Gipfel in Tausend Nadeln.", completion = "Nyse schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25479] = { id = 25479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Neu-Thalanaar", description = "Wir sind dabei, in Neu-Thalanaar für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Der Goblin Dyslix Silberraff wird Euch meinen Hippogryph zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Caryssia Jägermond, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Dyslix Silberraff einen Hippogryph und sprecht mit Caryssia Jägermond in Neu-Thalanaar in Feralas.", completion = "Thyssiana schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25480] = { id = 25480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanz der Geister", description = "Die Zeit ist reif, über den Angriff nachzudenken. Champion Uru'zin sagt, seine Männer wären bereit. Ihr und Vanira habt gute Arbeit geleistet, indem ihr Informationen gesammelt und uns neue Verbündete gefunden habt.\n\nJetzt lesen wir die Omen. Wir müssen rausfinden, wann wir den Angriff starten können.\n\nFindet Hexendoktor Hez'tok beim Kreis der Ritualtänzer. Er wird das Ritual anfangen, sobald Ihr bereit seid.", sourceObjective = "Sprecht beim Kreis der Ritualtänzer außerhalb von Sen'jin mit Hexendoktor Hez'tok, wenn Ihr bereit seid, die Omen zu konsultieren.", progress = "Und, was sagen die Omen?", completion = "Ich werde mir den Rat der Geister zu Herzen nehmen. Mit ihnen hinter uns und der Macht der uralten Loas des Dunkelspeerstammes sind wir bereit, uns zurückzuholen, was uns gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[25481] = { id = 25481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Neu-Thalanaar", description = "Wir sind dabei, in Neu-Thalanaar für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Seyala Elmsfeuer wird Euch meinen Hippogryph zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Caryssia Jägermond, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Seyala Elmsfeuer einen Hippogryph und sprecht mit Caryssia Jägermond in Neu-Thalanaar in Feralas.", completion = "Falfindel Wegeshut schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25482] = { id = 25482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Headless Horseman" }
quests[25483] = { id = 25483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Coren Direbrew" }
quests[25484] = { id = 25484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Ahune" }
quests[25485] = { id = 25485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[25486] = { id = 25486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grimmtotem kommen", description = "Es wird eine Zeit lang dauern, aber ich bin sicher, dass wir sie zurückschlagen können.\n\nIhr könnt Tausend Nadeln am besten von einem anderen Ort aus helfen. Es wurde uns berichtet, dass die Gnome und Goblins in den überfluteten Salzwüsten es irgendwie geschafft haben, irgendwie auf einem riesigen Dampfer zu überleben! Rendow an den Docks hat ein Boot, das sie Euch geben kann, um zu dem Dampfer zu gelangen.\n\nEs stört Euch doch nicht, uns auf dem Weg zu ihm ein wenig zu helfen?", sourceObjective = "Tötet 7 Marodeure der Grimmtotem.", completion = "Ein Boot? Ja, dieses hier könnt Ihr haben. Es ist das letzte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25487] = { id = 25487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grimmtotem kommen", description = "Die feigen Grimmtotem haben uns überraschenderweise angegriffen, als wir überhaupt nicht vorbereitet waren!\n\nIhr werdet Tausend Nadeln von einem anderen Ort aus besser helfen können, {class}. Es gehen Gerüchte um, dass die Goblins und Gnome irgendwie auf einem Dampfer in den Salzwüsten überlebt haben.\n\nMotega Feuermähne ist auf dem Hügelplateau zu finden - er kann Euch ein Kanu geben, um dorthin zu gelangen.\n\nStört es Euch, wenn Ihr auf Eurem Weg dorthin ein paar Grimmtotem für uns bekämpft?", sourceObjective = "Tötet 7 Plünderer der Grimmtotem.", completion = "Ihr möchtet ein Kanu, um nach Salzwüste zu gelangen? Die Rennbahn wurde doch komplett zerstört?!\n\nWie dem auch sei, für Euren Mut werde ich Euch mein letztes Kanu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25488] = { id = 25488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei per Boot", description = "Seid Ihr bereit, {class}? Eine der Schildwachen wird Euch zu der Illusionenrennbahn begleiten.\n\nFalls es dort Überlebende geben sollte, helft ihnen bitte.\n\nDie Göttin stehe Euch bei!", sourceObjective = "Sprecht mit Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", completion = "JA?! Unterbreche ich etwa Eure faszinierende Diskussion?\n\nNein... Nein, bitte, redet nur weiter. Ich bin sicher, dass Eure Störung mit etwas sehr Wichtigem zu tun hat. Wichtiger, als sich um das Überleben aller hier zu kümmern, ganz bestimmt.\n\n<Fizzel wippt ungeduldig mit dem Fuß.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25489] = { id = 25489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei per Boot", description = "Seid Ihr bereit, {class}? Einer unserer Kriegerhelden wird Euch zu der Illusionenrennbahn rudern.\n\nFalls es dort Überlebende geben sollte, so werden sie Eure Hilfe dringend benötigen.\n\nMöge die Erdmutter Euch mit einem Lächeln segnen!", sourceObjective = "Sprecht mit Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", completion = "Hallo, Kindchen, ich bin gleich bei Euch. Muss vorher nur diesen Gnomheini hier dazu bringen, den Mund zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25490] = { id = 25490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche auf ihr Haupt", description = "{name}, diese Fanatiker des Schattenhammers wollen alles Leben auf diesem Berg vernichten. Selbst jetzt folgen sie diesem Inferno und legen auf ihrem Weg alles in Schutt und Asche.\n\nErzdruide Hamuul Runentotem ist den Feuern auf den Fersen und versucht, die Wildnis zu retten, bevor sie voll und ganz von der Karte verschwindet. Reist nach Südosten durch das Inferno und die dahinterliegende Straße entlang. Findet den Erzdruiden und helft ihm.\n\nBefreit auf Eurem Weg dorthin die Straßen von allen Versengern, die Euch begegnen.", sourceObjective = "Tötet 8 Versenger.", completion = "Sehr gut. Wir müssen dem Schattenhammer deutlich klar machen, dass wir nie aufgeben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25491] = { id = 25491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robuste Saat", description = "Dieses Land wurde vom Feuer völlig versengt, aber es kann sich vielleicht dennoch wieder erholen.\n\nEinige Samen tief im Boden haben die sengende Hitze in der Flammenschneise möglicherweise überlebt. Diese robusten Samen sind der Schlüssel zur Wiedererweckung dieses Waldes. Bitte, sammelt einige dieser Setzlinge für mich.", sourceObjective = "Sammelt 10 Hyjalsetzlinge aus den Haufen versengter Erde.", progress = "Ich glaube, dass immer noch Leben unter der Asche herrscht. Was konntet Ihr finden?", completion = "<Der Erzdruide untersucht die Setzlinge.>\n\nDiese Setzlinge haben einen Weltuntergang überlebt. Selbst wenn es nur eine Handvoll ist, haben sie doch unglaubliche Macht. Das Leben erholt sich stets von ganz alleine und ist danach oft stärker als je zuvor.\n\nSobald der Weg frei ist, werden wir diese Setzlinge benutzen, um auf diesem Berg ein Wunder zu wirken, {name}. Ihr werdet schon sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25492] = { id = 25492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerschneise", description = "In ihrem Bestreben, den Hyjal zu vernichten, lassen die Schattenhammer Elementare die Erde nach dem Feuer versengen.\n\nSie pulverisieren den Boden, wühlen in der Asche und graben jede noch so kleine Pflanze aus, die überlebt hat, um sie zu zerstören. Es scheint fast so, als würden sie den Weg pflastern für... Ich möchte es mir nicht einmal vorstellen.\n\nHaltet sie auf, bevor es kein Leben mehr auf dem Hyjal gibt. Tötet die Lavawoger!", sourceObjective = "Tötet 10 Lavawoger.", completion = "Gute Arbeit, {name}. Der Wald hat eine Chance, sich doch noch zu erholen.\n\nDoch es gibt noch etwas anderes, was Ihr für mich erledigen sollt…", sourceObjectiveStatus = "unverified-source-field" }
quests[25493] = { id = 25493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Köder", description = "Ich war sehr überrascht, zu erfahren, dass der Schattenhammer den großen Schildkrötenahnen Tortolla gefunden und gefangen genommen hat. In diesem Moment ist er am Rande des trüben Aschensees angekettet.\n\nTortolla aus seinen Banden zu befreien wird nicht einfach, aber wir werden einfach einen Schritt nach dem anderen tun.\n\nGeht in die Flammenschneise und sammelt mir Kernhundinnereien. Ich erkläre Euch später warum.\n\nUnd hütet Euch vor Nemesis dem Usurpator, wenn Ihr dort seid! Seine Zeit wird auch noch kommen, aber noch sind wir nicht bereit.", sourceObjective = "Sammelt 4 Kernhundinnereien.", progress = "Habt Ihr die Innereien gesammelt?\n\nKernhunde sind in diesem Teil der Welt nicht heimisch. Sie sind dem Schattenhammer aus den Netherregionen der Erde gefolgt. Lasst Euch von ihrer Ausrottung nicht beunruhigen.", completion = "Sehr gut. Wir werden die Innereien als Köder brauchen, solange sie noch warm sind.\n\nHier ist mein Plan…", sourceObjectiveStatus = "unverified-source-field" }
quests[25494] = { id = 25494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Halsband für einen Champion", description = "Dieser kleiner Kerl ist wirklich bedrohlich, was?\n\nWenn er ein richtiger Kampfwelpe werden soll, müssen wir ihm ein angemessenes Halsband besorgen.\n\nDie Basiliskenmatriarchin hat ihr Nest an der Straße nach Winterquell errichtet. Bringt mir ihre stachelige Haut, damit wir ein schönes Halsband für unseren kleinen Killer hier daraus machen können.", sourceObjective = "Besorgt Euch die stachelige Basiliskenhaut von der Dornenschuppenmatriarchin.", progress = "Habt Ihr sie bekommen?", completion = "Ausgezeichnet! Unser Welpe ist jetzt bereit für den Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25495] = { id = 25495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf die Schlacht", description = "Vol'jin macht seine Ausrüstung klar und die Kriega bereit. Er hat mich gebet'n, Euch zu sag'n, dass Iah ihn und Vanira auf dea Insel im Osten treffen sollt.\n\nVon da werd'n er un die Krieger Zalazane angreif'n. Die Vorfahr'n soll'n Euch beisteh'n, {name}. Ohne Euch wär' diese Sache nur'n Schatten von dem, was sie is. Redet mit Tierführer Marnlek im Süden, un' er wird Euch 'ne Fledermaus geben, die Euch zum Sammelpunkt fliegt.", sourceObjective = "Sprecht mit Tierführer Marnlek, um einen Flug zum Sammelpunkt zu bekommen. Trefft Euch auf der Insel östlich des Kriegslagers mit Vol'jin.", completion = "Endlich, alles fertig. Jetzt zeigen wir Zalazane was mit denen passiert, die sich den Dunkelspeeren in den Weg stellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25496] = { id = 25496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbitterter Zweikampf", description = "Ich weiß nicht, ob Ihr davon gehört habt, aber es gibt eine gewisse Rivalität zwischen den Ogern im Schattenhammerkult und dem Rest von uns.\n\nWas mich angeht… ist die Sache persönlich.\n\nDieser Oger namens Gromm'ko hat einen Raptor als Haustier, sein Name ist Schlächter. Er hat meine letzten drei Kernhundwelpen getötet.\n\nAber mit diesem hier wird er das nicht schaffen. Er hat einen echten Killerinstinkt.\n\nGeht zum Sitz der Auserwählten und fordert Gromm'ko zu einem Duell zwischen den beiden Tieren heraus. Erniedrigt ihn für mich, {name}damus.", sourceObjective = "Fordert Gromm'ko am Sitz der Auserwählten auf dem Hyjal heraus.", progress = "Habt Ihr es geschafft, Ntonjaloleydamus? Hat unser kleiner Champion sich gut geschlagen?", completion = "Genau so macht man das!", sourceObjectiveStatus = "unverified-source-field" }
quests[25497] = { id = 25497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf hoch und Arsch in den Sattel", description = "Unsere Lage hier wird immer verzweifelter, {race}.\n\nWir müssen uns auf die Naga und ihre Gefangenen konzentrieren, aber ohne die richtige Vorbereitung wäre das reiner Selbstmord. Und hier unten heißt das, dass Ihr eine schnellere Fortbewegungsmethode braucht.\n\nDiese Haie mögen Meeresschildkrötenfleisch offensichtlich sehr gerne. Wollen wir doch mal sehen, ob wir das zu unserem Vorteil nutzen können.", sourceObjective = "Benutzt 6 Stück Schildkrötenfleisch, um einen Haihappen herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25499] = { id = 25499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweglichkeitstraining: Rennt wie der Teufel!", description = "Bevor wir weitergehen, müssen wir Euch erstmal in Form bringen.\n\nErgebenheit gegenüber den alten Göttern wird Euch nicht retten, wenn ein Smaragddrache hinter Euch her ist. Leichtfüßigkeit ist das Stichwort.\n\nDoch genug geredet. Wir werden Euren Trainer herbeirufen. Eure Aufgabe besteht darin, vor ihm wegzurennen, ohne dieses Lager zu verlassen.\n\nLos!", sourceObjective = "Rennt 1 Minute lang vor dem flammenden Trainer weg. Verlasst die Schmiede der Unterwerfung dabei nicht.", progress = "Ja?", completion = "Oh. Ihr seid noch am Leben.\n\nNicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25500] = { id = 25500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wortübermittlung", description = "Da haben wir sie. Das ist die Rede, {name}!\n\nSie hat alles, was ein guter Schlachtauftakt braucht: sie ist inspirierend, benutzt eloquente Sprache und spricht den einfachen Gnom direkt an. Nie wurde eine bessere Rede geschrieben!\n\nGebt sie Hauptmann Tret Funkdüse und fragt ihn, ob er noch etwas von Euch braucht.", sourceObjective = "Gebt die Rede Hauptmann Tret Funkdüse bei Stahlrosts Depot.", progress = "Was habt Ihr da, Rekrut?", completion = "Das ist also Tobys Rede? Fantastisch!\n\nRekrut, Ihr habt alles getan, was wir von Euch verlangen können und die Armee Gnomeregans dankt Euch dafür!\n\nWir haben ein Einsatzteam nach Gnomeregan entsendet und ohne Eure Unterstützung wäre das nicht möglich gewesen! Wir möchten Euch bitten, den Reservisten Gnomeregans beizutreten!\n\nDer Sold ist zwar nicht der Rede wert, aber dafür bekommt Ihr diesen todschicken Helm. Passt gut auf ihn auf, eines Tages könntet Ihr ihn brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25502] = { id = 25502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung des Bodens", description = "Der Erzdruide hat mich damit beauftragt, eine Reihe von Flammenzauberschutzen entlang der Grenze dieses Gebiets aufzustellen. Sobald diese aktiviert sind, können wir weitere Angriffe der Feuerelementare vermeiden, die dieses Tal in Schutt und Asche gelegt haben.\n\nSie schützen und nähren zudem den Boden, was auch immer Hamuul damit bezwecken will.\n\nEs ist an der Zeit, zu beginnen. Sucht einen der fünf Flammenzauberschutze, die ich für Euch auf der Karte markiert habe, aktiviert ihn und verteidigt ihn vor einem Gegenangriff, bis seine Magie zu wirken beginnt. Es wird nicht länger als eine Minute dauern.", sourceObjective = "Aktiviert und verteidigt einen Flammenzauberschutz.", completion = "Das ist gut! Dank Eurer Arbeit und der Arbeit anderer ist dieses Tal vor einem Gegenangriff geschützt.\n\nIch habe alles getan, was ich konnte. Jetzt liegt der Rest bei Euch und dem Erzdruiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25503] = { id = 25503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzflosses Beute", description = "<Vor dem letzten Eintrag befindet sich eine lädierte Seite, auf der steht:>\n\nUnser selbsternannter König schreckt vor nichts zurück, um an das Vermögen meiner Familie zu gelangen. Er hat mich unaufhörlich bedroht und belästigt.\n\nIch ertrage es nicht mehr!\n\nIch habe den Schatz vergraben und die Karte an Schwarzflosse verfüttert.\n\nDas sollte die gierigen kleinen Griffel meines Vetters von unseren wertvollen Erbstücken fernhalten!", sourceObjective = "Tötet den Orca Schwarzflosse, um an Gilblingels Karte zu kommen.", progress = "Ihr habt Gilblingels Familienschatz entdeckt!", completion = "Dieser Gegenstand war in den Augen der hiesigen Gilblinbevölkerung von unschätzbarem Wert und wurde sogar von König Gurboggel selbst heiß begehrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25504] = { id = 25504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Gefallen?", description = "Hallo. Schön, Euch kennenzulernen. Ich bin Fizzel Kupferbolz. Willkommen auf meinem Turbodampfer.\n\nWie auch Euch ist mir die Unterstützung von Tausend Nadeln wichtig, und ich bin davon überzeugt, dass der Turbodampfer der ganzen Region neue Hoffnung bringen kann.\n\nVielleicht könnt Ihr uns hier ein wenig helfen? Ich werde sicherstellen, dass Ihr mit allem versorgt werdet, was dafür benötigt ist.\n\nIhr könnt direkt anfangen, indem Ihr diese Bauteilliste zu Jinky Pfuschelfix in ihrem Laden bringt.", sourceObjective = "Bringt die Bauteilliste zu Jinky Pfuschelfix auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Ist das jetzt endlich die Bauteilliste? Darauf warte ich schon den ganzen Tag!", completion = "<Jinky wirft einen Blick auf die Liste und spuckt aus!>\n\nIch habe nicht mal die Hälfte von dem Kram hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[25505] = { id = 25505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Gefallen?", description = "Ja hallo, {name}. Ich bin Pozzik, der weltbekannte Raketenwagenfahrer. Willkommen auf meinem Turbodampfer.\n\nWie auch Euch ist mir die Unterstützung von Tausend Nadeln wichtig, und ich bin davon überzeugt, dass der Turbodampfer der ganzen Region neue Hoffnung bringen kann.\n\nVielleicht könnt Ihr uns hier ein wenig helfen? Ich werde sicherstellen, dass Ihr mit allem versorgt werdet, was dafür benötigt ist.\n\nIhr könnt direkt anfangen, indem Ihr diese Bauteilliste zu Razzeric in seinem Laden bringt.", sourceObjective = "Bringt die Bauteilliste zu Razzeric auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Ist das meine Bauteilliste von Pozzik?", completion = "Heya, Kumpel, kann ich einen Blick auf die Liste werfen?\n\n<Razzeric spuckt fast aus!>\n\nWas denkt sich Pozzik eigentlich? Er weiß doch, dass ich noch nicht mal die Hälfte von dem Zeug hier habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25506] = { id = 25506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeseilt", description = "Unsere Zeit hier nähert sich dem Ende.\n\nIch muss über die Schlucht reisen und herausfinden, was die Naga hier tun und warum.\n\nWenn Ihr mir folgen möchtet, solltet Ihr erst Eure Suche nach einem geeigneten Reittier abschließen.\n\nSucht nördlich von hier nach einem jungen Kugelfisch. Sobald Ihr einen gefangen habt, bringt ihn zum Graben im Westen. Ich werde dort alles vorbereiten, was Ihr braucht.", sourceObjective = "Findet einen jungen Kugelfisch auf Nagers Friedhof und bringt ihn zum Abgrund in der Nähe der Pferche.", sourceObjectiveStatus = "unverified-source-field" }
quests[25507] = { id = 25507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerknacker", description = "Diese frischen und stinkenden Innereien sind ein unwiderstehliches Festmahl für Nemesis, den verderbten Schildkrötengott, den der Schattenhammer erschaffen hat. Nemesis muss vernichtet werden, aber noch brauchen wir ihn.\n\nOder besser gesagt ein Stück seines steinigen Panzers. Damit können wir ein magisches Ritual durchführen, um den wahren Ahn zu befreien.\n\nGeht in die Flammenschneise und legt diesen Köder in der Nähe von Nemesis aus. Das wird ihn ablenken. Springt auf seinen Rücken und besorgt Euch ein Stück seines Panzers... Und dann rennt, wenn Ihr die Begegnung überleben wollt.", sourceObjective = "Benutzt die Kernhundinnereien in der Nähe von Nemesis, um ihn abzulenken. Sammelt ein Panzerfragment von Nemesis auf.", progress = "Nemesis besteht aus reinem, kochenden Zorn in einem steinernen Panzer aus Hass.\n\nSeine Zeit wird kommen.", completion = "<Der Erzdruide nimmt mit einer überraschenden Ehrfurcht den Panzer von Euch entgegen.>\n\nNemesis ist ein Instrument des Bösen, aber er wurde aus einem Panzerfragment des wahren Ahnen erschaffen.\n\nDiese Verbindung werden wir uns zu Nutze machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25509] = { id = 25509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperliches Training: Zwangsarbeit", description = "Das Training, das nötig ist, um zu uns zu gehören, ist nicht gerade angenehm. Warum sollte es das auch sein?\n\nDer Pfad zum Diener der alten Götter ist lang, schmerzhaft und die reinste Seelenqual. Betrachtet dies als Euren ersten Schritt.\n\nNehmt diese Hacke und baut die Leitsteinvorkommen in der Schlucht ab.\n\nNein, wir brauchen nichts von dem Erz. Dies dient ausschließlich Eurem Vorteil.", sourceObjective = "Baut 5 Flüsterleitsteine ab.", completion = "Sehr gut. Zumindest seid Ihr fähig genug herauszufinden, was man mit dem spitzen Ende einer Hacke anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25510] = { id = 25510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla spricht", description = "<Der Erzdruide füllt das Panzerfragment mit Wasser, welches sofort zu kochen beginnt. Er fügt ein Bündel Kräuter hinzu und flüstert ein Gebet vor der Statue Malornes.>\n\n{name}, Tortolla, der Schildkrötenahn, kennt kein Alter. Er ist seit der Zeit der Titanen Teil dieser Welt. Er spricht eine Sprache, die älter ist als alles, was wir kennen.\n\nTrinkt dies und begebt Euch an einen Ort der inneren Ruhe. Ihr werdet in der Lage sein, Tortollas Sprache zu verstehen. Geht gleich zu ihm in den Aschensee. Erlangt das Vertrauen des Ahnen. Das Schicksal des Hyjal hängt davon ab.", sourceObjective = "Geht zu Tortolla, dem Schildkrötenahnen, im Aschensee auf dem Hyjal.", completion = "{race}.\n\nDiese Sprache. Ist nicht Eure.\n\nWas wollt Ihr... Peiniger?", sourceObjectiveStatus = "unverified-source-field" }
quests[25513] = { id = 25513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Erbitterter Zweikampf", description = "Wir haben eine Sonderanfrage erhalten! Ich habe hier eine Notiz von einer Kelsey Stahlfunken, die den Käfig betreten und etwas aus der Welt schaffen möchte.\n\nSie hat Euch als Wunschpartner angegeben, {name}. Ein Fan Eurer alten Erfolge? Oder vielleicht kennt Ihr Euch von woanders?\n\nIch würde an Eurer Stelle nicht absagen. Das klingt nach einem wunderbaren Finale...", sourceObjective = "Besiegt Megs Schredderschreck.", completion = "Fantastisch. Ich werde Euch selbst vielleicht einmal zu einem Duell herausfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25514] = { id = 25514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bande brechen", description = "Aus den Tiefen…\nEin Reich der Dunkelheit und des Feuers.\nGreift nach mir in meinem Schlaf.\n\nIch bin gefesselt, {race}.\n\nSchatten lauern in den Feuerruten neben mir.\n\nTötet sie.\n\nAuf dass ich wieder frei sei.", sourceObjective = "Deaktiviert die beiden Ruten der Unterwerfung, die Tortolla binden.", completion = "<Tortolla zittert und schüttelt den Schmutz von seinem riesigen Rücken.>\n\nIhr…\nSeid nicht wie die anderen.\n\nIch bin wieder frei.\n\nDie anderen…\nWerden bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25515] = { id = 25515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Tiefen", description = "<Jinky krempelt die Ärmel hoch und streicht sich die Haare aus dem Gesicht, während sie Euch genau beobachtet.>\n\nNun gut, wenn Fizzel will, dass Ihr Euer eigenes Boot bekommt, dann müssen wir zuerst die Teile dafür besorgen. Und jetzt ratet mal, wer sie besorgen wird!\n\n<Jinky lächelt, zeigt nach unten und holt daraufhin einen Ersatztaucherhelm und Flossen hervor.>\n\nGenau, <Bruder/Schwester>. Ihr werdet Euch in die Tiefen wagen und alle Raketenwagenteile bergen, die Ihr in den Rennbahnruinen finden könnt.", sourceObjective = "Sammelt 10 Raketenwagenteile.", progress = "Eure Arbeitszeit werde ich erst festhalten, wenn Ihr mir alle Teile gebracht habt, die auf der Bauteilliste stehen.", completion = "Fürs Erste werden wir uns damit zufriedengeben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25516] = { id = 25516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Tiefen", description = "Nun gut, wenn Pozzik möchte, dass Ihr Euer eigenes Boot bekommt, dann müssen wir zuerst die Teile dafür besorgen. Und jetzt ratet mal, wer sie besorgen wird!\n\n<Razzeric lächelt und zeigt nach unten; daraufhin holt er einen Ersatztaucherhelm und Flossen hervor.>\n\nJa, Ihr habt leider recht. Ihr werdet Euch in die Tiefen wagen und alle Raketenwagenteile bergen, die Ihr in den Rennbahnruinen finden könnt.", sourceObjective = "Sammelt 10 Raketenwagenteile.", progress = "Wir können anfangen, sobald wir alle Teile von der Liste haben.", completion = "Das ist schon mal ein guter Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[25517] = { id = 25517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schenkenschlägerei!", description = "Diese stinkenden Goblinnichtsnutze werden trotz ihres hellgrünen Alters jetzt etwas erleben!\n\nGeht zur Turbodampferschenke, bestellt eine Flasche Grog, und haut einem der Goblins damit auf den Kopf!\n\nMacht ihnen klar, dass wir ihre Frechheiten nicht länger dulden werden, {name}!", sourceObjective = "Provoziert eine Schlägerei in der Schenke!", completion = "So ist es richtig! Ihr seid ein wahrer Segen für die Allianz!\n\nIhr solltet wissen, dass Ihr das in der Schenke jederzeit wieder machen könnt, wenn Ihr wollt. Ich kann Euch dazu nur ermuntern!", sourceObjectiveStatus = "unverified-source-field" }
quests[25518] = { id = 25518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schenkenschlägerei!", description = "Diese winzigen, hässlichen und nichtexplodierenden Gnome werden jetzt etwas erleben!\n\nGeht zur Turbodampferschenke, bestellt eine Flasche Grog, und haut einem der Gnome die Flasche über den Kopf!\n\nMacht ihnen klar, dass wir ihre arrogante Art nicht länger dulden werden, {name}!", sourceObjective = "Provoziert eine Schlägerei in der Schenke!", completion = "Ja! Ihr seid sehr nützlich für die Horde!\n\nIhr solltet wissen, dass Ihr das in der Bar jederzeit wieder machen könnt, wenn Ihr wollt. Ich kann Euch dazu nur ermuntern!", sourceObjectiveStatus = "unverified-source-field" }
quests[25519] = { id = 25519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abkömmlinge von Tortolla", description = "Meine Kinder.\n\nSie liegen in der Tiefe.\n\nIn Schlick und Sand.\n\nDie anderen verderben sie.\n\nVerdunkeln ihre Seelen im Panzer.\n\nTötet die anderen.\n\nTötet die Verderber.\n\nRettet sie…", sourceObjective = "Tötet 6 Tiefe Verderber, die Tortollas Eier im Aschensee angreifen.", completion = "{race}.\nIhr seid nicht wie die anderen.\n\nMutiger. Stärker.\nEin Teil von dieser Welt…\nNicht wie der Schatten, der zuvor zu mir kam.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25520] = { id = 25520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ahn erwacht", description = "Ich schlummerte im heiligen Schlick des Hyjal.\nIch schlief, bis die Welt aufbrach.\nAls die anderen kamen, war ich nicht vorbereitet.\n\nJetzt bin ich vorbereitet, {race}.\n\nMeine Kinder und ich. Unseren Zorn erregt man nicht leicht.\nDoch er ist endgültig.\n\nSagt denen, die Euch geschickt haben, dass wir für den Krieg bereit sind.\n\nDie anderen werden vom Berg verbannt.", sourceObjective = "Kehrt zu Erzdruide Hamuul Runentotem im Heiligtum von Malorne zurück.", completion = "{name}!\n\nIhr konntet das Vertrauen des Ahnen gewinnen?\n\nWunderbar! Wir sind einen Schritt näher daran, diesen Berg zurückzugewinnen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25521] = { id = 25521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorpidooh!", description = "Ihr müsst mir helfen, Ihr müsst, bitte! Ich kam mit Chelsea hierher, um ein bisschen Gold zu machen, ehrliche Arbeit, ein paar Sachen verkaufen. Und jetzt liegt sie auf dem Sterbebett! Sie hat Fieber, das selbst einen Schmied umhauen würde und sie halluziniert...\n\nIch glaube, sie wurde von einem der Skorpide hier gestochen! Ich hab das schon einmal gesehen, es ist kein schöner Anblick. Ich brauche ein paar Giftdrüsen, um ein Gegengift herzustellen, aber ich kann sie nicht alleine lassen!\n\nBitte, helft mir! Besorgt mir die Giftdrüsen!", sourceObjective = "Sammelt 6 Dünenscherenstachel von Dünenscherenpeitschern.", progress = "Habt Ihr sie? Oh, bitte...", completion = "Oh ich danke Euch! Vielen Dank! Ich kenne mich ein bisschen mit Alchemie aus, ich kann auch etwas. Hier wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[25522] = { id = 25522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargantapid", description = "Nein! Es hat nicht funktioniert! Ich weiß nicht, was ich tun soll, es sei denn...\n\nOh nein, es ist schlimmer, als ich dachte! Sie muss von dem gestochen worden sein, der sich in der Höhle versteckt hat. Ich habe ihn gesehen, als wir angekommen sind. Seine Klauen sind so groß wie Goblins. Sein Schwanz ist so groß wie ein Baum! Wir haben uns am Lagerfeuer leise über ihn unterhalten... wir haben ihn GARGANTAPID getauft!\n\n... hey, lacht Ihr etwa? Hört auf! Das ist alles ernst hier! Chelseas Leben ist in Gefahr! Bitte, ich werde dafür sorgen, dass es sich für Euch lohnt... bringt mir Gargantapids Giftdrüse!", sourceObjective = "Erhaltet Gargantapids Giftdrüse.", progress = "Ihr seid zurück! Habt Ihr sie?", completion = "Ich kann es kaum fassen! Ihr seid großartig! Hier, bitte, nehmt diese Belohnung, nehmt alles, was Ihr wollt. Ich muss Chelsea retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25523] = { id = 25523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen in den Feuerlanden", description = "{name}, unser Feind nutzt diese Grotte in den Feuerlanden, um eine Invasion vorzubereiten. Wir werden hart zuschlagen, und zwar direkt dort, wo sie leben.\n\nAber zuerst müsst Ihr Euch Eure Flügel verdienen. In den Feuerlanden funktioniert das Fliegen nicht so wie in der Außenwelt. Das hat etwas mit der dichten, überhitzten Luft zu tun. Ihr braucht Übung!\n\nNehmt Euch eine Zwielichtfeuerlanze aus dem Regal hinter mir und schwingt Euch auf einen von Avianas Wächtern. Übt das Fliegen. Ihr müsst nur mit den Flügeln schlagen! Fliegt zu der Fahne, die ich auf dem Sims unter uns aufgestellt habe, und kehrt dann zurück.", sourceObjective = "Nehmt Euch eine Zwielichtfeuerlanze aus dem Regal hinter Farden und legt sie an. Steigt auf einen von Avianas Wächtern und fliegt zum Sims unter Euch. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Gut gemacht! Wie fühlt es sich an?\n\nEs ist eine echte Herausforderung, in dieser brennenden Ödnis die Flugkunst zu beherrschen, aber das ist der einzige Weg.\n\nIch hoffe, dass Ihr für die Schlacht bereit seid, {name}…", sourceObjectiveStatus = "unverified-source-field" }
quests[25524] = { id = 25524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Plumpsklo", description = "Hallo? Hallo! HILFE!\n\nIch bekomme fast keine Luft mehr! Ihr müsst mich hier rausholen!\n\n<Von innen erklingt ein Würgegeräusch.>\n\nEiner von diesen Schatzjägern der Südmeerfreibeuter hat bestimmt ein Brecheisen bei sich!", sourceObjective = "Erhaltet ein Piratenbrecheisen und versucht, die Tür des Plumpsklos unter Wasser aufzubrechen.", progress = "Oh, um des Lichtes Willen, habt Ihr das Brecheisen? Ich bin hier am Ertrinken!", completion = "Oh, was für ein Glück! Nur noch ein bisschen mehr drücken...", sourceObjectiveStatus = "unverified-source-field" }
quests[25525] = { id = 25525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Welle", description = "Da kommen sie, {name}! Die Zwielichtritter auf ihren schwarzen, in den sengenden Schwefelbrutstätten der Feuerlande geschlüpften Bussarden. Der einzige Weg, sie zu besiegen, führt durch die Luft.\n\nSchwingt Euch erneut in den Himmel, {class}, und tötet sie.\n\nRammt Eure Lanze in die Ritter, um sie zu vernichten.\n\nHinfort! Fliegt, Ihr Narr. Fliegt!", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt auf Avianas Wächter. Tötet 10 Zwielichtritter, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Ein spektakulärer Flug, {name}! Ihre gequälten Schreie haben die Wände dieser lichtverlassenen Höhle zum Beben gebracht.\n\nDoch unsere Arbeit ist noch nicht zu Ende…", sourceObjectiveStatus = "unverified-source-field" }
quests[25526] = { id = 25526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Plumpsklo", description = "Hallo? Hallo! HILFE!\n\nIch bekomme fast keine Luft mehr! Ihr müsst mich hier rausholen!\n\n<Von innen erklingt ein Würgegeräusch.>\n\nEiner von diesen dreckigen Schatzjägern der Südmeerfreibeuter hat bestimmt ein Brecheisen bei sich!", sourceObjective = "Erhaltet ein Piratenbrecheisen und versucht, die Tür des Plumpsklos unter Wasser aufzubrechen.", progress = "Oh, um Goldes Willen, habt Ihr das Brecheisen? Ich bin hier am Ertrinken!", completion = "Oh, was für ein Glück! Nur noch ein bisschen mehr drücken...", sourceObjectiveStatus = "unverified-source-field" }
quests[25531] = { id = 25531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtaufstand", description = "Ich bin Euch dankbar, dass Ihr mich befreit habt. Lasst uns den Aufruhr, den Ihr verursacht habt, nutzen und hier verschwinden.\n\nWir müssen uns beeilen, bevor die Kultisten uns auf die Schliche kommen.\n\nSucht mich wieder auf, wenn wir diesen Ort verlassen haben.", sourceObjective = "Sprecht mit Jarod Schattensang an den Toren von Sothann auf dem Hyjal.", completion = "Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25532] = { id = 25532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserte Piratenpräzision", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber die Kanonenkugeln treffen. Es scheint, als würden die Piraten der Südmeerfreibeuter präziser werden... das Schiff brennt!\n\nIhr habt ja jetzt ein Rennboot. Sprecht mit Mazzer Schrottschrauber. \n\nLöscht die Feuer!", sourceObjective = "Holt von Mazzer Schrottschrauber ein Rennboot und benutzt die Frostkanone, um 15 Feuer zu löschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25533] = { id = 25533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserte Piratenpräzision", description = "Oh nein, {name} - die Kanonenkugeln treffen den Turbodampfer! Es scheint, als würden die Piraten der Südmeerfreibeuter präziser werden... das Schiff brennt!\n\nIhr habt ja jetzt ein Rennboot. Bitte, sprecht mit Griznak.\n\nLöscht die Feuer!", sourceObjective = "Holt von Griznak ein Rennboot und benutzt die Frostkanone, um 15 Feuer zu löschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25534] = { id = 25534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gebrüllt", description = "Vielleicht habt Ihr schon gesehen, dass an dem Schiff, das nördlich von hier angedockt hat, die Kanonen gefeuert werden. Es ist zwar recht lustig, den Gnomen dabei zuzuschauen, mit dem Gesicht voran in den Eisenregen zu rennen, aber leider machen meine Haudraufs das Gleiche, und das ist für meine Gemeinkosten kaum tragbar.\n\nKönntet Ihr versuchen, durch den Kanonenhagel durchzukommen, auf das Schiff zu gelangen und den Zuchtmeister zu töten, der die Kanoniere antreibt? Der Rest der Besatzung wird ein Haufen Trottel ohne Rückgrat sein; wenn er erledigt wurde, sollten sie kein Problem mehr darstellen.", sourceObjective = "Tötet den Zuchtmeister der Südmeerfreibeuter.", completion = "Gute Arbeit Kindchen. Knapp mit dem Leben davongekommen? Von einer Kanonenkugel gekratzt?\n\nNein? Gut, wir haben hier noch anderes zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25535] = { id = 25535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger", description = "Die Armen. Sie sind am Verhungern.\n\nEs gibt viele Dinge, um die wir uns kümmern müssen, nicht zuletzt um die Naga. Doch zuerst müssen wir ihre Mägen füllen. Ich bin mir nicht sicher, was die Naga da oben in der Muschel ihnen gefüttert haben, aber sie sehen ganz schön mitgenommen aus.\n\nEine beträchtliche Zahl Überlebende hat es in die Glimmertiefenschlucht im Nordwesten geschafft. Schließt Euch ihnen an und helft ihnen. Mit ein bisschen Muschelfleisch bekommen wir die Überlebenden sicher schnell hochgepäppelt.", sourceObjective = "Sprecht mit Tauchbegleiter Birmingham in der Glimmertiefenschlucht.", completion = "Noch mehr Hilfe! Spitze! Wir können sie wirklich brauchen, soviel steht fest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25536] = { id = 25536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuchter Händedruck", description = "Viele der Überlebenden haben sich in die Glimmertiefenschlucht aufgemacht, um beim Muscheltauchen zu helfen. Wir haben Berichte erhalten, laut denen dort unten eine Art Murlocstamm unsere Leute willkürlich angreift.\n\nDer Admiral muss hier bleiben, da sich immer mehr Männer aus der Schnecke melden. Ich kann ihn einfach nicht überreden, den Tauchern ein paar starke Arme zu Hilfe zu schicken. Wenn Ihr Lust habt, würden sie Eure Hilfe sicher dankend annehmen.\n\nKehrt zu mir zurück und gebt mir Bescheid, ob Ihr die Lage in den Griff bekommen habt.", sourceObjective = "Tötet 10 Gezeitenjäger der Glimmertiefen.", completion = "Vielen Dank, dass Ihr Euch darum gekümmert habt, {class}. Ich weiß, dass wir derzeit viele Sorgen haben, die uns den Kopf zerbrechen, aber die Sicherheit der Überlebenden ist für mich die oberste Priorität.", sourceObjectiveStatus = "unverified-source-field" }
quests[25537] = { id = 25537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Anlockung", description = "Ich habe eine Idee. Eine brillante Idee! Diese clownartigen Fische sind zu ihrer Verteidigung eine symbiotische Beziehung mit den Anemonen eingegangen. Nachdem ich den Versuch aufgegeben habe, die Taucher als Anemonen zu verkleiden, habe ich den chemischen Lockstoff entdeckt, der die Fische magisch anzieht.\n\nIch habe einen gyroskopischen Thermaseptextraktor mit hierher gebracht, um Proben zu nehmen. Benutzt ihn, um den chemischen Lockstoff aus verschiedenen Anemonen zu extrahieren, und bringt mir dann die Proben, damit ich ihn schnell künstlich herstellen und verteilen kann.\n\nSchnell! Die Brillanz wartet nicht!", sourceObjective = "Benutzt die Extraktionsapparatur für Anemonenchemikalien, um 8 chemische Anemonenproben von den roten Anemonen entlang der Wände der Glimmertiefenschlucht zu sammeln.", completion = "Hervorragend! Chemikalien in Hülle und Fülle!\n\nMein chemischer Direktsynthetisierer ist bereits getestet und vorbereitet. Die Mischung sollte in einem Wimpernschlag bereit zur Verteilung sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[25538] = { id = 25538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geruchsverschleierung", description = "Eine herausragende Arbeit, wenn ich mich einmal selbst loben darf. Bereit zur Verteilung.\n\nSprüht einfach die Muscheltaucher mit einem Hauch dieser Chemikalie ein und schon bald sollten sie einen schuppigen Begleiter haben, der sie beschützt. Wenn Ihr wünscht könnt Ihr Euch auch selbst einsprühen, um den gleichen Effekt zu erzielen.\n\nDa wir gerade von Wünschen sprechen: Ich empfehle Euch, den chemischen Lockstoff nur in sehr geringen Dosen zu verwenden. Wenn Ihr zu viel davon verwendet, kann das unerwünschte Folgen haben...\n\nZumindest unerwünscht für Euch. Wahrscheinlich jedoch sehr wünschenswert für die Fische.\n\nHinfort mit Euch!", sourceObjective = "Benutzt die Applikationsapparatur für Anemonenchemikalien an 8 Muscheltauchern.", completion = "Gut gemacht, mein dufter Handlanger! Ihr seid sowohl schnell als auch eifrig, wenn ich das so sagen darf. Mögen Eure weiteren Reisen vor Inspiration und Opulenz nur so überschäumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25539] = { id = 25539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgetaucht", description = "Seid Ihr hier, um beim Muscheltauchen zu helfen?\n\nDann mal los! Hier sind fast überall Muscheln, die ertaucht werden wollen.", sourceObjective = "Sammelt 16 Glimmertiefenmuscheln.", progress = "Hat Eurer Ausflug Meeresfrüchte getragen?", completion = "In der Tat, sehr gut gemacht. Dieses beträchtlichen Berges an Muscheln braucht Ihr Euch wahrlich nicht zu schämen. Die Überlebenden in der Höhle werden Euch sicher dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25540] = { id = 25540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Mäuler warten", description = "Wir haben einen riesen Haufen Muscheln gesammelt, der zurück in die Höhle geschleppt werden müsste, und ich habe einfach erwartet, dass Ihr das Schleppen übernehmt. Ihr habt Euch als gefährlich genug erwiesen, um genau <der/die> Richtige für diese Aufgabe zu sein.\n\nIch rechne nämlich damit, dass die Raubtiere auf dem Rückweg nicht ohne Kampf auf solch ein feines Mahl verzichten. Daher solltet Ihr so schnell wie möglich aufbrechen.\n\nVielen Dank für Eure Hilfe, Freund. Es war mir ein Vergnügen.", sourceObjective = "Bringt den großen Sack Muscheln zum Stillen Strand.", progress = "Ihr seht aus, als wärt Ihr aus einem bestimmten Grund zu uns zurückgekehrt. War Eure Reise erfolgreich?", completion = "Das ist wunderbar. Ich werde sie sofort kochen. Es ist beruhigend zu wissen, dass wir jetzt wenigstens keine Angst haben müssen, zu verhungern.\n\nIch könnte mir vorstellen, dass der Admiral mit vielen Aufgaben auf Euch wartet. Daher möchte ich Euch zumindest eine Weile lang nicht mehr aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25541] = { id = 25541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir füllen uns die Taschen", description = "Wir haben eigentlich alles geplündert, was nicht niet- und nagelfest ist, aber fertig sind wir noch nicht hier. Wenn wir dem Dampfdruckkartell schon die Arbeit abnehmen, dann müssen wir schon sicherstellen, dass wir hier auch gut verdienen.\n\nIch habe an den Piraten nur wenige Ohrringe gesehen - das heißt, dass sie ihr Gold am nächstsichersten Ort aufbewahren... in ihren Zähnen. Die Musketiere und Schläger der Südmeerfreibeuter südlich von hier haben in ihren Rängen mehr zu sagen. An ihnen wird man mehr dieser Verschönerungen finden. Bringt mir eine Handvoll Goldfüllungen.", sourceObjective = "Sammelt 20 Goldfüllungen von den Musketieren der Südmeerfreibeuter oder den Schlägern der Südmeerfreibeuter.", progress = "Jetzt werdet hier mal nicht zimperlich.", completion = "Toll! Gold ist Gold, egal aus welchem Mund, welcher Nase oder wo auch immer man es ziehen musste.\n\nUnd nach dem Schmelzen ist es auch alles ganz hygienisch. Zumindest hygienischer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25542] = { id = 25542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer haben wir unter Kontrolle, aber einige der Piraten der Südmeerfreibeuter machen sich bereit, um den Turbodampfer einzunehmen.\n\nEs ist an der Zeit, dass wir die Kanone der anderen Seite benutzen und sie versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", completion = "Geschafft! Ihr habt es geschafft!\n\n<Jinky packt Euch und gibt Euch einen Schmatzer auf die Wange! Sie findet ihren Anstand wieder und streicht ihre Kleidung straff.>\n\nDanke, dass Ihr meinen Turbodampfer gerettet habt, Kapitän {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25543] = { id = 25543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer haben wir unter Kontrolle, aber einige der Piraten der Südmeerfreibeuter machen sich bereit, um den Turbodampfer einzunehmen.\n\nEs ist an der Zeit, dass wir die Kanone der anderen Seite benutzen und sie versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", completion = "Ihr habt meinen Turbodampfer gerettet!\n\n<Razzeric umarmt Euch kameradschaftlich!>\n\nIch kann gar nicht in Worte fassen, wie erleichtert ich bin, Kapitän {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25544] = { id = 25544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Welle", description = "Da habt Ihr in ein Wespennest gestochen, {name}. Uns fällt hier die Decke auf den Kopf! Und ihre stärksten Krieger schwingen sich auf Kreaturen, die von dieser Flammenwelt entstellt und verunstaltet wurden.\n\nKehrt noch einmal zurück und holt sie vom Himmel! Gebt jedoch auf die flammenden Brocken Acht.", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt Avianas Wächter. Tötet 10 Zwielichttjoster, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Bei Avianas Schwingen, Ihr wurdet zum Fliegen geboren, {name}!\n\nSchnell, lasst uns dorthin zurückkehren und erneut zuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25545] = { id = 25545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen!", description = "In unserem Kampf gegen das Ertrinken waren meine Männer und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich bin geneigt, ihm zu glauben.\n\nWenn wir eine Chance haben wollen, ihnen Stand zu halten, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen. Es sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks liegen.\n\nSchnell, {race}. Wir sind hier vollkommen schutzlos.", sourceObjective = "Sammelt 4 Speere von Sturmwind, 4 Brustplatten von Sturmwind, 4 Schilde von Sturmwind und 4 Helme von Sturmwind.\n\nIhr könnt die Ausrüstung auch von Strauchdieben der Gilblin sammeln.", progress = "Habt Ihr unsere Ausrüstung zurückgeholt, {race}?", completion = "Gut gemacht, {class}!\n\nDank Euch werden meine Männer sich gegen den Feind wehren können, wenn er angreift.", sourceObjectiveStatus = "unverified-source-field" }
quests[25546] = { id = 25546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege gehen durch den Magen", description = "Wenn ich diese Männer für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Essen, kein Sieg.\n\nDiese Soldaten sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass sie zu den Waffen greifen müssen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", sourceObjective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", progress = "Konntet Ihr etwas Essbares für meine Männer und mich finden, {class}?", completion = "Das sollte gegen die Erschöpfung helfen.\n\nUnd wieder sind wir Euch sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25547] = { id = 25547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu unseren eigenen Bedingungen", description = "Wir sind so bereit, wie man nur sein kann. Es bringt nichts, hier herumzusitzen und darauf zu warten, dass die Naga uns finden.\n\nIch werde mit den Männern sprechen und dann treffen wir unter unseren eigenen Bedingungen auf den Feind und lassen das Schicksal entscheiden, wie es ausgeht.", sourceObjective = "Sprecht mit Kapitän Taylor im Salzkutter.", completion = "Es ist keine Zeit, um noch zu den Truppen zu sprechen.\n\nAuch gut. Sie wissen, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25548] = { id = 25548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Feuerfürsten", description = "Ich wurde damit beauftragt, unsere militärischen Schachzüge gegen den Feind zu leiten. Eine demutsvolle Aufgabe, wenn man bedenkt, dass Halbgötter unter uns wandeln.\n\nIch muss Euch bitten, einige Überfälle auf Seiten des Feindes durchzuführen. Dabei ist es besonders wichtig, dass Ihr den Feind überrascht und ihn dezimiert, um unsere Hauptstreitmacht zu unterstützen.\n\nEuer erstes Ziel ist die Anhöhe des Aszendenten, wo die am besten ausgebildeten Anhänger des Schattenklans teilweise schon einen elementaren Zustand erreicht haben.", sourceObjective = "Tötet 4 Flammenaszendenten und 5 Zwielichtunterwerfer auf der Anhöhe des Aszendenten auf dem Hyjal.", completion = "Das habt Ihr gut gemacht, {name}. Ich habe ein neues Ziel für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25549] = { id = 25549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sanktum der Propheten", description = "Die verrückten Propheten des Schattenhammers versammeln sich in einem Gebiet direkt nördlich des Zirkels des Aszendenten.\n\nMan sagt, dass sie ihre düsteren Visionen direkt von den alten Göttern empfangen. Ganz gleich, ob das stimmt oder nicht, sie sind wichtige spirituelle Vordenker des Kults. Wenn wir das Sanktum der Propheten angreifen, können wir der Moral unserer Gegner einen schweren Schlag versetzen. Und falls wir Glück haben, lauft Ihr dort auch noch einem persönlichen Abgesandten des Feuerfürsten über den Weg.", sourceObjective = "Tötet 4 Zwielichtauguren, 4 Zwielichtanhänger und 1 Abgesandten der Flamme im Sanktum der Propheten.", completion = "Ihr beweist weiterhin Euren Heldenmut, {name}. Wenn Ihr so weitermacht, kann der Hyjal dieses Martyrium vielleicht doch überstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25550] = { id = 25550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmamonarch", description = "Die Magmariesen, die Ragnaros dienen, stehen unter dem strengen Befehl ihres Königs. Wenn wir ihn ausschalten, werden die anderen sicher in Verwirrung geraten.\n\nOhne die Riesen fällt der Kampf bestimmt ausgeglichener aus. Vielleicht können wir sogar einen Vorteil erringen.\n\nDen Magmamonarchen zu erlegen wird sicher keine einfache Aufgabe. Benutzt diese Trommeln, um den großartigen Tortolla zu Hilfe zu rufen. Er kann König Lavatron bis in alle Ewigkeit in Schach halten. Doch ihn in Schach zu halten wird nicht reichen - und da kommt Ihr ins Spiel.", sourceObjective = "Benutzt die Trommeln des Schildkrötengottes, um für den Kampf gegen König Lavatron Unterstützung zu erhalten.", completion = "Ausgezeichnete Arbeit, {name}. Bald schon werden wir den Sieg auf dem Hyjal erringen.\n\nEs war mir eine Ehre, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25551] = { id = 25551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feuerfürst", description = "Jetzt, da der Torwächter aus dem Weg geräumt ist, können die Wächter des Hyjal endlich auf die Sulfuronspitze gelangen.\n\nRagnaros hat keine andere Möglichkeit, als den Hauptweg in die Feuerlande selbst zu verteidigen.\n\nGeht durch das Portal des Schattenhammers im Sanktum der Propheten und trefft mich dort. Malfurion und Hamuul werden Euch dort ebenfalls helfen, während die anderen weiterhin den Feind draußen bekämpfen.", sourceObjective = "Geht durch das Portal im Sanktum der Propheten und helft Cenarius dabei, Ragnaros zu besiegen.", progress = "Ja, {name}?", completion = "Hyjal wurde gerettet, {name}. Und das nur dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25552] = { id = 25552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut des Bösen", description = "Dieses Ei, das Ihr beschafft habt, bietet Anlass zur Beunruhigung, {name}. Die Zwielichtdrachen werden in der Regel aus gestohlenen Eiern anderer Drachenschwärme aufgezogen, die dann durch dunkle Magie verändert werden.\n\nDieses \"natürliche\" Ei ist der Beweis, dass eine ihrer Matriarchinnen inzwischen in der Lage ist, selbst Eier zu legen. Wir müssen sie vernichten, bevor ihre Brut sich ausbreiten kann.\n\nGeht zur Anhöhe des Aszendenten, wo diese entarteten Wesen gehalten werden sollen, und tötet einen der Jungdrachen. Wir werden seinen Schädel benutzen, um seine Mutter hervorzulocken.", sourceObjective = "Besorgt Euch den Schädel eines jungen Zwielichtdrachen auf der Anhöhe des Aszendenten auf dem Hyjal.", progress = "Ihr seid zurück, {name}.", completion = "Das habt Ihr gut gemacht. Wir werden das hier verwenden, um die Zwielichtmatriarchin aus ihrem Versteck zu locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25553] = { id = 25553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Brutmutter", description = "Wir haben die Futterstelle der Matriarchin südlich des Zirkels des Aszendenten ausfindig gemacht.\n\nSie wird sehr wütend sein, wenn sie merkt, dass sie einen ihrer Drachen verloren hat. Legt den Schädel in der Nähe des Aases ab, das sie verschlingt. Wenn sie ihn sieht, wird sie hervorkommen und versuchen, Rache zu nehmen.\n\nDann wartet eine nette Überraschung auf sie.", sourceObjective = "Legt den Zwielichtdrachenschädel an der Futterstelle südlich des Zirkels des Aszendenten ab und tötet Desperiona.", completion = "Das lief… noch besser als erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25554] = { id = 25554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Flamme", description = "Wenn wir Ragnaros wieder in die Feuerlande verbannen wollen, müssen wir uns Zugang zur Sulfuronspitze verschaffen.\n\nNur den vertrauenswürdigsten Mitgliedern des Schattenhammerkults werden diese wertvollen Informationen anvertraut.\n\nGeht und sucht auf der Anhöhe des Aszendenten nach Folianten. So übel diese Bücher auch sein mögen, wir können uns die Gelegenheit nicht entgehen lassen, mehr über die Schwächen unseres Feinds zu erfahren.", sourceObjective = "Beschafft Euch den Kodex des Aszendenten, die brennenden Litaneien und den Folianten der Flamme auf der Anhöhe des Aszendenten auf dem Hyjal.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, {name}?", completion = "Diese grauenvollen Bücher sollte es besser gar nicht geben. Und doch sind die darin enthaltenen Informationen für uns von größter Wichtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25555] = { id = 25555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Torwächter", description = "Laut diesen Folianten dient einer von Ragnaros' mächtigsten Leutnants als einziger Torwächter der Sulfuronspitze.\n\nIhr werdet ihn nicht alleine besiegen können.\n\nBlast in dieses Horn, wenn Ihr Euch in den Kampf mit Azralon stürzt. Daraufhin werden alle in der Nähe befindlichen Streitkräfte zu Eurer Hilfe eilen.\n\nIhr müsst Euch beeilen, {name}. Der Feuerfürst kommt unseren Plänen sicher schnell auf die Schliche.", sourceObjective = "Benutzt das Horn des Cenarius, um Hilfe dabei zu erhalten, Azralon den Torwächter zu töten.", completion = "Es ist vollbracht. Nun bleibt Euch nur noch Eines zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[25556] = { id = 25556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Zul'Farrak", description = "Dieser üble Verräter... ich hätte es besser wissen müssen, als jemand seines Schlags zu vertrauen. Die Suche nach Sul'thraze hat mich geblendet.\n\nVergebt mir, {name}. Mazoga ist nach Zul'Farrak geflohen, der bevölkerungsreichste Teil der Länder der Sandwüter.\n\nIhr müsst ihm folgen, wenn Ihr das Schwert wirklich haben wollt. Geht nicht alleine; der Stamm der Sandwüter liegt hinter diesen Mauern auf der Lauer und sie werden Euch nicht willkommen heißen.\n\nIch werde hier bleiben. Ich muss die Suche nach der Klinge beenden. Solltet Ihr sie finden, so behaltet sie. Ich muss aufhören, bevor es mich verzehrt.", sourceObjective = "Findet Mazoga in Zul'Farrak.", completion = "<Mazogas Geist grinst Euch blutverschmiert an.>\n\nHey, wie geht's, Mann?", sourceObjectiveStatus = "unverified-source-field" }
quests[25558] = { id = 25558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles oder nichts", description = "Es ist soweit.\n\nHier werden wir uns zur Wehr setzen.\n\nWir müssen dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass diese Narren es sich zweimal überlegen, bevor sie sich ihm erneut nähern!\n\nMögen unsere Klingen ihnen Angst und Schrecken einjagen!", sourceObjective = "Helft Kapitän Taylor bei der Verteidigung des Salzkutters.", completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", sourceObjectiveStatus = "unverified-source-field" }
quests[25559] = { id = 25559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anspruch erheben", description = "Es scheint, als wären nicht nur wir an den Ruinen interessiert. Jetzt haben wir ausgerechnet Blutelfen bei unseren Ausgrabunsstellen.\n\nIch hatte damit gerechnet, dass sie in der Hitze und ohne ihre schicken Brunnen und weichen Kissen eingehen würden, aber bisher halten sie sich erstaunlich gut und versuchen, uns mit Gewalt aus den Südmondruinen zu verteiben.\n\nEs ist an der Zeit, ein paar Schädel zu zertrümmern. Macht Euch auf und zeigt diesen Elfen, dass mit uns nicht zu scherzen ist!", sourceObjective = "Tötet 10 Ruinenjäger der Blutelfen.", completion = "Das wird es der Horde zweimal zeigen! Die Geschichte der Zwerge in Ruhe zu lassen und keine zerbrechlichen Sofaliebhaber in den Kampf zu schicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[25560] = { id = 25560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierwelle", description = "Ohne Verteidiger sind die Eier der Feuerlande angreifbar.\n\nSchwingt Euch erneut in die Lüfte und zerschmettert diese Eier! Rauscht einfach über sie hinüber, um sie zu zerbrechen. Sucht in jeder Ritze, Felsspalte und Seitenhöhle nach ihnen. Schnell!", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt Avianas Wächter. Zerstört 40 Eier der Feuerlande, indem Ihr über sie rauscht. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Ein entscheidender Schlag!", sourceObjectiveStatus = "unverified-source-field" }
quests[25561] = { id = 25561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer mögen unter Kontrolle sein, aber die Piraten der Südmeerfreibeuter machen sich trotzdem bereit, um den Turbodampfer einzunehmen!\n\n{name}, Ihr müsst zurück zu Mazzer Schrottschrauber und auf Euer Boot. Benutzt die Kanone, um sie zu versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25562] = { id = 25562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer mögen unter Kontrolle sein, aber die Piraten der Südmeerfreibeuter machen sich trotzdem bereit, um den Turbodampfer einzunehmen!\n\n{name}, Ihr müsst zurück zu Griznak und auf Euer Boot. Benutzt die Kanone, um sie zu versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25564] = { id = 25564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfschwimmer von Sturmwind", description = "Ihr habt uns einen großen Dienst erwiesen, {class}, also werde ich Euch ein kleines Geheimnis verraten. Die Männer, die Ihr heute gerettet habt, gehören nicht zu den normalen Truppen von Sturmwind.\n\nWir sind Teil einer Sondertruppe von Elitesoldaten, die nicht nur hierher geschickt wurden, um uns gegen die Horde zu behaupten, sondern auch, um die massiven geologischen Störungen vom Meeresgrund in der Nähe zu untersuchen.\n\nIch erzähle Euch das, weil unsere streng geheime Ausrüstung unten in den Schiffswracks hier liegt.\n\nDiese Ausrüstung muss dringend geborgen werden!", sourceObjective = "Findet 6 Teile einer Kampfschwimmerausrüstung aus Sturmwind.", progress = "Konntet Ihr die Ausrüstung sicherstellen, {class}?", completion = "Es scheint alles in Ordnung zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25565] = { id = 25565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprachfragmente", description = "Wir haben den ersten richtig großen Fund seit Jahren hier in den Südmondruinen gemacht. Meine Jungs haben Steintafeln ausgegraben, auf denen alte Schriften zu finden sind. \n\nDie Glyphen auf den Tafeln sind uns gänzlich fremd, aber sie könnten mit den Wandschriften der Titanen zusammenhängen, die wir auch gefunden haben.\n\nStellt Euch nur vor, was dieser Fund bedeuten könnte!\n\nGeht für mich zu den Südmondruinen und helft uns, die Tafeln zu sammeln. Die anderen Jungs können nicht von dort weg, weil die Blutelfen sonst den Platz einnehmen werden!", sourceObjective = "Sammelt 5 uralte Hieroglyphen.", progress = "Habt Ihr die Tafeln?", completion = "Seht Euch das an... es ist kein Trollisch, kein Qiraji, nur ein Geheimnis, das gelüftet werden will.\n\nBei Euch sind die Tafeln vorab sicher. Es ist an der Zeit, in die Ruinen aufzubrechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25566] = { id = 25566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse Uldums", description = "Ich habe diese Ruinen jahrelang erforscht, um den Eingang zu finden. Wir haben sogar einen Teil der Tore eingerissen, nur um undurchdringbare Mauern darunter zu finden. Jetzt hat der Kataklysmus da drinnen wahrscheinlich alles komplett zerstört, aber in erster Linie hat er für uns etwas geöffnet, was uns verschlossen war!\n\nEuch soll diese Ehre zukommen, <Junge/Mädchen>: Begebt Euch nach Innen und seht, ob es noch Sachen gibt, die nicht zerstört wurden. Aber seid vorsichtig... wir können nicht wissen, wer oder was sich da drinnen noch befindet.", sourceObjective = "Sucht in der Vorkammer von Uldum nach einem unzerstörten Artefakt.", completion = "Die Truhe liegt ungestört hier und wurde seit Tausenden von Jahren nicht mehr geöffnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25574] = { id = 25574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen von oben", description = "Dank Eurer Arbeit haben wir grob die Richtung bestimmen können, aus der die Eindringlinge kommen.\n\nJetzt müssen wir nur noch ihr Lager außer Gefecht setzen und ihre Vorhaben hier auf dieser Seite von Nordrassil durchkreuzen.\n\nNehmt dieses Horn. Damit könnt Ihr einen unserer Smaragddrachen herbeirufen, der hinabstürzen und diesen Schattenhammerkultisten eine kleine Kostprobe der Flammen geben wird, die sie so wahnsinnig verehren.", sourceObjective = "Sucht das Lager des Schattenhammers nördlich von Nordrassil und benutzt Tholos Horn.", progress = "Ist es schon getan, {name}?", completion = "Ausgezeichnet, {name}. Das sollte die Angriffe ein für alle Mal aufhalten, sobald wir diesen Elementaren den Garaus gemacht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25575] = { id = 25575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmiedet aus Schatten und Flammen", description = "Die Waffen, die der Schattenhammer gegen uns einsetzt, werden von Schmiedemeister Pyrendius in diesen Hallen gefertigt. In der Hand seines Trägers gleitet das Metall durch Rüstungen wie durch Butter. Doch sobald ein anderer die Waffen in den Händen hält, wird der Stahl brüchig und zerbirst.\n\nUnd so sei es, {name}. Ich sehe lieber, wie diese verfluchten Waffen in tausend Stücke zerspringen, als dass sie unserem Feind geliefert werden.\n\nSucht nach den Waffenkisten des Schattenhammers in diesen Höhlen und zerschlagt sie!", sourceObjective = "Zerstört 10 Waffenkisten des Schattenhammers.", completion = "Gut, gut. Nichts gefällt mir besser als mitanzusehen, wie das Werk unserer Feinde vernichtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[25576] = { id = 25576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Wolfsahnen", description = "Da sind wir tief im Reich des Feuergottes und was finden wir? Ragnaros' kleine Marionetten, die sich abrackern, um seinen Willen zu erfüllen.\n\nDiese Arbeiter der Dunkeleisenzwerge vervollständigen und verpacken die Waffen, die der Schattenhammer bei seiner Eroberung des Hyjal einsetzen möchte. Es ist mir egal, ob sie aus freien Stücken hier sind oder ob sie einer Gehirnwäsche unterzogen und hierher verschleppt wurden. Sie sind und bleiben Feinde unseres geliebten Wolfsahnen und müssen dafür mit dem Leben bezahlen.", sourceObjective = "Tötet 12 Arbeiter der Dunkeleisenzwerge.", completion = "Tot? Gut. Sie haben ihr Schicksal selbst besiegelt, als sie sich mit Ragnaros und seinem Königreich des Feuers verbündet haben.\n\nLasst ihre Körper hier unten zu Asche zerfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25577] = { id = 25577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert die Kerne", description = "Diese sengenden Wächter sind der Inbegriff der Blutrünstigkeit! Wir vernichten sie, doch schon ein paar Minuten später entflammen sie wieder aus der Asche.\n\nIch glaube, dass es eine Möglichkeit gibt, sie für immer zu zerstören. Doch dazu benötigen wir jemanden, der sich zu ihren vordersten Reihen durchschlägt.\n\n{name}, tötet die sengenden Wächter und bringt ihre Kerne zu den Ambossen in der Nähe. Zerschmettert sie auf den Ambossen des Schattenhammers und vernichtet sie für immer!", sourceObjective = "Besorgt 8 schwelende Kerne von sengenden Wächtern und zerschmettert sie dann auf den Ambossen des Schattenhammers.", completion = "Tolle Leistung!\n\nEs gab eine Zeit, in der Abenteurer diese Kerne sammelten, um daraus mittelmäßige feuerresistente Rüstungen herzustellen. Aber vorerst bin ich einfach nur froh, dass Ihr diese Ausgeburten ein für alle Mal vernichtet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25578] = { id = 25578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Nordrassil", description = "Ich bringe Fandral schnell zur Mondlichtung. Ich hoffe, dass ich bald zurück bin, um in der Schlacht helfen zu können.\n\nMeldet Euch in der Zwischenzeit bei Ysera und berichtet ihr von den aktuellen Entwicklungen.", sourceObjective = "Sprecht mit Ysera in Nordrassil auf dem Hyjal.", completion = "Alysras Entscheidung war vielleicht nicht die weiseste, {name}. Aber wir haben keine Zeit, um uns darüber Gedanken zu machen.\n\nIch bringe wichtige Erkenntnisse vom Smaragdgrünen Traum.", sourceObjectiveStatus = "unverified-source-field" }
quests[25579] = { id = 25579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", sourceObjective = "Tötet 10 Patrouillen der Azsh'ir.", completion = "Ausgezeichnete Arbeit, {class}.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25580] = { id = 25580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Handeln", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", sourceObjective = "Zerstört 8 Überwacher der Azsh'ir.", completion = "Gut gemacht, {name}. Und genau rechtzeitig. Der Admiral hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25581] = { id = 25581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Vergangenheit", description = "Hört mal... {name}, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nIch möchte nur, dass Ihr, wenn Ihr ohnehin schon in der Stadt seid, nach bedeutenden Objekten Ausschau haltet. Die Statuen interessieren mich ganz besonders.", sourceObjective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25582] = { id = 25582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Standort", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", sourceObjective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Süden der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, {class}.\n\nEs klingt so, als ob das Gebäude unter der Terrasse am anderen Ende der Ruinen einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25583] = { id = 25583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", sourceObjective = "Bringt das Bruchstück zurück zum Stillen Strand.", progress = "Ja, {class}?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25584] = { id = 25584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Ahnen", description = "Es ist unerlässlich, dass wir jeden einzelnen Schrein der Ahnen zurückerobern, {name}.\n\nFolgt der Straße westlich des Saftgrünen Dickichts in die Wolfsschlucht.\n\nWir haben dort ein paar Agenten postiert. Helft ihnen, wo Ihr könnt, und macht Euch auf den Weg zum ersten Schrein.\n\nDer Wolfsgott trug bei den Elfen den Namen Goldrinn und bei den Orcs den Namen Lo'Gosh. Er wird uns im Kampf gegen den Feind ein mächtiger Verbündeter sein.", sourceObjective = "Sprecht mit Oomla Weißhorn in der Wolfsschlucht auf dem Hyjal.", completion = "Ysera hat Euch geschickt? Gut! Wir können hier dringend Hilfe brauchen.\n\nWir werden die Schreine der Ahnen nie zurückgewinnen können, solange der Schattenhammer die Straßen unter seiner Kontrolle hat. Irgendwie müssen wir gegen diese Flut ankämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25585] = { id = 25585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kanonen erstummen lassen", description = "Jetzt können wir uns endlich um die verfluchten Kanonen auf dem Felsen östlich von hier kümmern.\n\nNehmt doch bitte Euer Boot und fahrt damit zum Südmeerstützpunkt. Ihr werdet dort die Kanonen finden, die auf uns feuern.\n\nDie Piraten haben aber vom Ingenieurswesen keine Ahnung. Es sollte also recht einfach sein, die Kanonen zu verstopfen - dann sollten sie einfach explodieren.", sourceObjective = "Zerstört 8 Stützpunktkanonen.", completion = "Sie schießen immer noch, aber schon viel weniger! Yiiiippiiiiiiiiiiiiiiiiiiiiie!", sourceObjectiveStatus = "unverified-source-field" }
quests[25586] = { id = 25586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kanonen erstummen lassen", description = "Jetzt können wir uns endlich um die verfluchten Kanonen auf dem Felsen östlich von hier kümmern.\n\nNehmt doch bitte Euer Boot und fahrt damit zum Südmeerstützpunkt. Ihr werdet dort die Kanonen finden, die auf uns feuern.\n\nDie Piraten haben aber vom Ingenieurswesen keine Ahnung. Es sollte also recht einfach sein, die Kanonen zu verstopfen - dann sollten sie einfach explodieren.", sourceObjective = "Zerstört 8 Stützpunktkanonen.", completion = "Sie schießen immer noch, aber schon viel weniger! Yiiiippiiiiiiiiiiiiiiiiiiiiie!", sourceObjectiveStatus = "unverified-source-field" }
quests[25587] = { id = 25587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atempause", description = "Bitte, {race}! Ihr müsst mir helfen!\n\nDie Naga, Haie und dann dieses schreckliche Monster, das unser Schiff angegriffen hat... Ich bin nur knapp dem Tod entronnen.\n\nIch kann eine Höhle erkennen, die vielleicht sicher ist, aber ich wage mich nicht dorthin bis ich sicher weiß, dass dort Luft ist.\n\nKönntet Ihr nachschauen, ob alles in Ordnung ist?", sourceObjective = "Untersucht den Schmugglerschmiss im Tang'tharwald und signalisiert Adarrah dann, dass sie sicher hineingehen kann.", completion = "Ich kann Euch nicht genug danken, {race}.\n\nIch hoffe nur, dass dieser ganze Alptraum ein glückliches Ende findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25588] = { id = 25588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Vergeltung", description = "Ich glaube, es ist an der Zeit, ein wenig Vergeltung zu üben. Das kann man mir kaum übel nehmen, nachdem sie mich in dem Plumpsklo eingesperrt hatten, um mich zu ertränken?!\n\nEs wird sich für Euch lohnen, wenn Ihr für mich zum Südmeerstützpunkt am östlichen Steilhang reist, und für mich Rache nehmen könntet.", sourceObjective = "Tötet 15 Piraten der Südmeerfreibeuter in Südemeerstützpunkt.", completion = "Das wird diesen gemeinen Hunden eine Lektion erteilen! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25589] = { id = 25589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Vergeltung", description = "Ich glaube, es ist an der Zeit, ein wenig Vergeltung zu üben. Das kann man mir kaum übel nehmen, nachdem sie mich in dem Plumpsklo eingesperrt hatten, um mich zu ertränken?!\n\nEs wird sich für Euch lohnen, wenn Ihr für mich nach Südmeerstützpunkt am östlichen Steilhang reist, und für mich Rache nehmen könntet.", sourceObjective = "Tötet 15 Piraten der Südmeerfreibeuter in Südemeerstützpunkt.", completion = "Das wird diesen gemeinen Hunden eine Lektion erteilen! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25590] = { id = 25590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Wizzel?", description = "Hey, {name}, Ihr habt meinen Bruder Wizzel auch nicht gesehen, oder?\n\nIch weiß nur, dass die Piraten ihn gefangen genommen haben! Er hatte wohl vor, ihnen irgendwelchen Ingenieurskram zu verkaufen.\n\nKönnt Ihr bitte in Südmeerstützpunkt östlich von hier nach ihm suchen? Ich befürchte, dass der nichtsnutzige Goblin Flämmer, mit dem er immer unterwegs ist, ihn in Schwierigkeiten gebracht hat!", sourceObjective = "Findet Wizzel Kupferbolz in Südmeerstützpunkt in Tausend Nadeln.", completion = "Hey! Holt mich hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[25591] = { id = 25591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Erbitterter Zweikampf", description = "Wir haben eine Sonderanfrage erhalten! Ich habe hier eine Notiz von einer Megs Schredderschrek, die den Käfig betreten und etwas aus der Welt schaffen möchte.\n\nSie hat Euch als Wunschpartner angegeben, {name}. Ein Fan Eurer alten Erfolge? Oder vielleicht kennt Ihr Euch von woanders?\n\nIch würde an Eurer Stelle nicht absagen. Das klingt nach einem wunderbaren Finale...", sourceObjective = "Besiegt Kelsey Stahlfunken.", completion = "Fantastisch. Ich werde Euch selbst vielleicht einmal zu einem Duell herausfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25592] = { id = 25592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff aus der Tiefe", description = "Ich konnte ein paar von den Überlebenden in die Höhle helfen, aber so langsam wird die Lage da draußen brenzlig. Als ob wir nicht schon genug Probleme hätten, schleichen sich jetzt auch noch diese leuchtenden Murlocs aus der nahegelegenen Spalte an und überfallen die gestrandeten Überlebenden.\n\nDie Männer da oben sind Krieger und werden sich nicht ohne Kampf ergeben, aber nach dieser verdammten Muschel sind sie alle ganz schön mitgenommen.\n\nWenn Ihr noch ein wenig Atem in Euren Lungen habt, geht nach oben und löscht ein paar dieser Murlocs aus. Höllschreis Augen ruhen auf Euch.", sourceObjective = "Tötet 10 Strauchdiebe der Rotkiemen.", completion = "Ihr wisst wirklich, was Ehre bedeutet, {class}. Ihr erfüllt Höllschrei mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25593] = { id = 25593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gepanzerte Rettung", description = "Viele haben es noch nicht in die Höhle geschafft. Bestimmt sind sie an den Rändern des Grats über uns gestrandet.\n\nWir haben ein paar Spiralungpanzer auf dem Weg hierher gefunden. Sie erzeugen zwar nicht viel Sauerstoff, aber er hat gereicht, um uns zur Höhle zu bringen.\n\nIch muss hier unten bleiben, um die Ankömmlinge zu zählen und sie wieder auf die Beine zu bringen. Tut mir einen Gefallen und sammelt diese Spiralungpanzer. Bringt sie zu meinen Männern oben auf dem Grat und gebt ihnen einen fixen Tritt in den Hintern, damit sie sich hier hinunter bewegen.", sourceObjective = "Sammelt 8 Spiralungpanzer und gebt sie gestrandeten Überlebenden von Nespirah.", completion = "Danke, {class}. Ihr habt Euch als äußerst nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25594] = { id = 25594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garstige Krebse", description = "Das war dieser verdammte Krebs!\n\nUnd ich dachte, all das Training durch den Marsch hierher macht mich richtig stark! Meine Ausrüstung wurde immer leichter und leichter. Aber nein! Dieser Krebs hat ein Loch in meine Tasche geschnitten und all meine Teile sind auf dem ganzen Weg hierher rausgefallen.\n\nBitte, helft einem gutaussehenden Goblin, ja? Geht und sammelt meine fehlenden Teile ein. Ich bin mir sicher, dass diese hinterhältigen, bösartigen kleinen Krebse auch welche davon gestohlen haben.", sourceObjective = "Sammelt 12 von Fiascos fehlenden Teilen.", progress = "Unterschätzt nie die Anziehungskraft von Glitzerkram.", completion = "Schön, dass Ihr leicht verdientes Gold erkennt, wenn es Euch über den Weg läuft. Es war mir eine Freude, mit Euch Geschäfte zu machen, Kumpel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25595] = { id = 25595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Essen", description = "Wollten sie uns zu Tode hungern?! Gefangenen keine Nahrung zu geben ist einfach niederträchtig.\n\nWir müssen diesen Soldaten etwas Essbares geben. Die einfachste Möglichkeit besteht wohl in diesen riesigen Schnappkieferbarschen. Ein paar von denen werden unseren Hunger auf Fleisch sicher ein paar Tage stillen können.\n\nWenn Ihr mir einige bringt, sorge ich dafür, dass sie zubereitet und gerecht verteilt werden.", sourceObjective = "Sammelt 8 Stück Fleisch eines Schnappkieferbarschs.", progress = "Bei all diesen knurrenden Mägen klingt es, als hielte sich ein Monster in dieser Höhle versteckt. Das macht mich ganz schön nervös.", completion = "Jetzt zu meinem Teil der Vereinbarung. Ich sorge sofort dafür, dass das hier zubereitet und verteilt wird.\n\nWir beide müssen uns später weiter unterhalten. Ich brauche Hilfe, die mir diese Soldaten einfach nicht bieten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25596] = { id = 25596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Flämmer?", description = "Hey, {name}, Ihr habt unseren Büchsenmacher Flämmer auch nicht gesehen, oder?\n\nIch weiß nur, dass die Piraten ihn gefangen genommen haben! Er hatte wohl vor, ihnen irgendwelche Waffen zu verkaufen.\n\nKönnt Ihr bitte im Südmeerstützpunkt östlich von hier nach ihm suchen? Ich befürchte, dass der nichtsnutzige Gnom Wizzel Kupferbolz, mit dem er immer unterwegs ist, ihn in Schwierigkeiten gebracht hat!", sourceObjective = "Findet Flämmer in Südmeerstützpunkt in Tausend Nadeln.", completion = "Hey! Holt mich hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[25597] = { id = 25597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Jarod Schattensang", description = "Nur einmal gab es einen Kommandanten, der in der Lage war, Halbgötter und Sterbliche gleichermaßen anzuführen.\n\nSein Name war Jarod Schattensang. Seine Führungsqualitäten waren so überragend, dass Cenarius und die anderen Ahnen sich aus freien Stücken seinem Befehl unterstellt haben.\n\nEr galt viele Jahre als verschollen. Keiner wusste, was mit ihm geschehen war. Bis jetzt.\n\nEr wird in einem Lager des Schattenhammers in der Flüsternden Schlucht gefangen gehalten.\n\nEure Aufgabe besteht darin, ihre Reihen zu unterwandern und Jarod zu befreien. Sprecht mit dem, den sie Ortell nennen, am Flüsternden Pass im Südosten.", sourceObjective = "Sprecht mit Elementarist Ortell am Flüsternden Pass.", completion = "Oh hallo! Ich bin froh, dass sie jemanden mit Eurem Können für dieses Unterfangen geschickt haben.\n\nDieser Auftrag erfordert viel Fingerspitzengefühl. Wir können nicht riskieren, dass Kommandant Schattensang getötet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[25598] = { id = 25598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer geht noch", description = "Jetzt, da Ihr mich in Sicherheit gebracht habt, muss ich Eure Freundlichkeit leider noch etwas weiter strapazieren.\n\nDer Kapitän unseres Schiffes, Samir, ist immer noch da draußen. Und auch Mack. Ich bin mir sicher, dass sie es zum Meeresgrund geschafft haben, aber ich konnte nicht sehen, was dann aus ihnen geworden ist.\n\nOhne ihre Hilfe könnte ich es an einem Ort wie diesem einfach nicht aushalten.\n\nIch habe sie in einem Tanggeflecht westlich des Ortes, an dem Ihr mich gefunden habt, aus den Augen verloren.\n\nBitte, beeilt Euch! Sie können noch nicht weit sein...", sourceObjective = "Findet Samir und Mack.", completion = "Was würde ich nur ohne Euch machen, {race}!\n\nIch mag es mir nicht einmal vorstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25599] = { id = 25599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschenmaul, der Portalmeister", description = "Der Schattenhammer verwendet diese und andere Korridore dieser Art, um Vorräte von den Elementarebenen nach Azeroth zu bringen. Um diese Passagen zu versiegeln, müssen wir wissen, wie sie gebaut sind.\n\nSucht den Foliant der Öffnungen, den die Elementare verwenden, um die Tore zwischen den Ebenen zu öffnen.\n\nDer Portalmeister Aschenmaul sollte einen bei sich tragen. Ihr müsst ihn töten. Aber Vorsicht! Er hat wahrscheinlich den ein oder anderen Trick auf Lager...", sourceObjective = "Tötet Aschenmaul und findet den Foliant der Öffnungen.", progress = "Der Foliant! Habt Ihr ihn gefunden?", completion = "Das ist der Foliant, von dem wir so viel gehört haben?\n\n<Jordan hievt die Steintafel hoch und schaut sie sich an.>\n\nIch verstehe… Wie gut, dass ich ein wenig von der Elementarschrift lesen kann. Ich mache mich gleich an die Übersetzung. In der Zwischenzeit gibt es ein weiteres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25600] = { id = 25600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedemeister Pyrendius", description = "Eine entsetzlich bösartige Macht hat sich mitten im Herzen dieser Höhle niedergelassen, {name}. Schmiedemeister Pyrendius hat viele der verfluchten Waffen, die der Schattenhammer auf seinen Beutezügen oben verwendet, selbst geschmiedet.\n\nBevor wir die Feuerlande verlassen... muss Pyrendius sterben.\n\nEr wird sicher nicht leicht zu besiegen sein, aber wenn ich den Folianten recht verstehe, können wir kurz kleine Tore zum Meeresschlund öffnen, dem Reich des Wassers. Lockt Pyrendius auf eine Portalrune und aktiviert sie, um ihn zu schwächen.", sourceObjective = "Tötet Schmiedemeister Pyrendius. Lockt ihn auf die Portalrunen und benutzt sie, um ihn zu schwächen.", completion = "Es ist vollbracht! Wir werden diese Flammenhölle hinter uns versiegeln und lassen den Schattenhammer die Leichen finden, die wir hinterlassen haben. Ohne Euch hätten wir das nicht geschafft, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25601] = { id = 25601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klassenprimus", description = "Damit ist die Sache klar, \"{name}damus\"! Ihr seid der Klassenprimus!\n\nIhr habt die Ehre, zu einer Masse der fanatischsten, blutdürstigsten und nachweislich geisteskrankesten Leute dieses Planeten zu sprechen.\n\nGeht und meldet Euch bei Eurem Instrukteur, um alle Details zu erhalten. Aber vergesst nicht: Euer Ziel ist es, die Feindschaft zwischen den Ogern am Sitz der Auserwählten und den anderen, weniger privilegierten Rassen zu schüren.\n\nWenn alles gut läuft, werden wir während des darauf folgenden Aufruhrs Jarod hier heraus schmuggeln.", sourceObjective = "Sprecht mit Instrukteurin Mylva an der Schmiede der Unterwerfung auf dem Hyjal.", completion = "Da seid Ihr ja, Kunrebidamus. Ich wollte etwas mit Euch besprechen.\n\nIch habe von dem unglücklichen Vorfall gehört, dem Euer armer Freund Okrog zum Opfer fiel.\n\n<Mylva schaut nach links, dann nach rechts. Schließlich nickt sie und zwinkert Euch verschmitzt zu.>\n\nIhr seid ein besserer Schüler, als ich dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25602] = { id = 25602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zündende Funke", description = "Mack ist immer noch bewusstlos und ich fürchte, dass wir ihn verlieren, wenn wir dieses Feuer nicht in Gang bringen. Da das Holz feucht geworden ist, brauchen wir einen speziellen Zünder.\n\nIn der Nähe befindet sich ein verlassenes Lager. Dort findet Ihr ein Fass mit Sprengstoff. Alleine schaffe ich es nicht bis dorthin.\n\nKönntet Ihr es für uns hierherschleppen? Für Mack?", sourceObjective = "Besorgt Euch das Pulverfass von Budds Ausgrabung.", progress = "Habt Ihr den Sprengstoff aus dem Lager geholt, {class}?", completion = "Ausgezeichnet!\n\nMal schauen, ob das für unsere Zwecke geeignet ist…\n\nTretet zurück, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25607] = { id = 25607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Där Gnomcordär", description = "Diese Goblins ekeln misch an. Die dreckische Goblinteschnique ist jeder Gnomenteschnique unterlegen, abär...\n\n<Professor Xakxak seufzt.>\n\nDas ist die letzte Teil von die Puzzle! Isch kann misch nischt bauen die Gnomcordär, wenn isch nischt 'aben etwas von die dreckische Goblinteschnique!\n\nIhr müsst ge'en in die Osten nach \"Stinkwerk\" und 'olen von ihnen etwas von die dreckische Goblinteschnique! Ihr werdet finden sie bei die Goblinteschniquer.\n\n<Professor Xakxak lacht spöttisch.>\n\nGoblinteschniquer? Was das sollen sein?\n\n<Professor Xakxak zuckt mit den Schultern.>\n\nEin Oxymoron?", sourceObjective = "Holt 8 Stücke dreckige Goblintechnologie.", progress = "Wo ist die Schrott? 'abt Ihr es?", completion = "Ah, die Schrott 'aben angekommen! Das ist die letzte Teil von die Puzzle! Jetzt isch muss machen fertisch! Achtüng, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25608] = { id = 25608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandrodung", description = "Der Sieg ist möglich, {name}.\n\nDieses Portal ist nicht nur dazu da, um Cenarius durch den Traum zurückzubringen. Denkt darüber nach, {name}. Sobald das Tor durch den Smaragdgrünen Traum geöffnet ist, können unsere Truppen sich darüber frei zur Mondlichtung, nach Nordrassil und sogar an den strategisch gut gelegenen Wyrmruhtempel bewegen.\n\nAlles, was Ysera braucht, ist Zeit. Es liegt an Euch, die Streitmächte des Schattenhammers daran zu hindern, sich in der Flüsternden Schlucht zusammenzuziehen und uns vom Osten her anzugreifen.\n\nNehmt einen der Smaragddrachen und versetzt ihnen einen empfindlichen Schlag!", sourceObjective = "Schwingt Euch auf einen Smaragddrachen und tötet 40 Einheiten des Schattenhammers und 5 Zwielichtdrachen.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Ausgezeichnete Arbeit, {name}. Vielleicht können wir ja doch noch gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25609] = { id = 25609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Tony Zweihauer, der Piratenadmiral, hat den Schlüssel für den Käfig - und ist von Ogern bewacht, die Ihr nicht töten können werdet!<Wizzel heult noch ein bisschen und schaut plötzlich nach oben. Man kann sehen, dass ihm eine Idee gekommen ist.>\n\nIch hab's! Was ist Piraten wichtiger, als alles andere? Sogar wichtiger als Grog? Genau... Schätze!\n\nSie hatten einst ein Schiff voller Schätze, das von einem riesigen Walhai versenkt wurde. Die Schätze sind überall im Illusionsschlund verteilt, nordwestlich von hier.\n\nGeht, und holt die Schätze ein!", sourceObjective = "Sammelt 8 versunkene Schatzkisten.", progress = "Oh Mann, habt Ihr etwa schon alle versunkenen Schatzkisten?", completion = "Oh, wie schön - seht Euch nur diese Beute an!\n\nMoment... bringt das mal näher her!", sourceObjectiveStatus = "unverified-source-field" }
quests[25610] = { id = 25610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Tony Zweihauer, der Piratenadmiral, hat den Schlüssel für den Käfig - und ist von Ogern bewacht, die Ihr nicht töten können werdet!<Wizzel heult noch ein bisschen und schaut plötzlich nach oben. Man kann sehen, dass ihm eine Idee gekommen ist.>\n\nIch hab's! Was ist Piraten wichtiger, als alles andere? Sogar wichtiger als Grog? Genau... Schätze!\n\nSie hatten einst ein Schiff voller Schätze, das von einem riesigen Walhai versenkt wurde. Die Schätze sind überall im Illusionsschlund verteilt, nordwestlich von hier.\n\nGeht, und holt die Schätze ein!", sourceObjective = "Sammelt 8 versunkene Schatzkisten.", progress = "Ihr habt schon alle versunkenen Schatzkisten?", completion = "Oh, wie schön - seht Euch nur diese Beute an!\n\nMoment... bringt das mal näher her!", sourceObjectiveStatus = "unverified-source-field" }
quests[25611] = { id = 25611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr aus den Feuerlanden", description = "Ich werde die restlichen Anhänger Goldrinns durch das Tor scheuchen und dieses Portal hinter uns versiegeln.\n\nDer Rest unserer Streitkräfte auf dem Hyjal will sicher von unserem Sieg erfahren. Kehrt zu Ian Duran zurück und lasst ihn wissen, was wir entdeckt und wie wir triumphiert haben!\n\nTretet einfach durch das Portal, um auf den Hyjal zurückzukehren.", sourceObjective = "Kehrt zu Ian Duran am Schrein von Goldrinn auf dem Hyjal zurück.", completion = "Sie bringen Verstärkung direkt über die Elementarebenen auf den Hyjal? Das erklärt natürlich einiges!\n\nGoldrinn ist gewiss stolz auf Euch, weil Ihr dieses Flammentor versiegelt habt, {name}, aber vielleicht gibt es noch mehr Portale, die versiegelt werden müssen. Ihr solltet auch die anderen Schreine untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25612] = { id = 25612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr aus den Feuerlanden", description = "Ich werde die restlichen Anhänger Lo'Goshs durch das Tor scheuchen und dieses Portal hinter uns versiegeln.\n\nDer Rest unserer Streitkräfte auf dem Hyjal will sicher von unserem Sieg erfahren. Kehrt zu Takrik Wutheuler zurück und lasst ihn wissen, was wir entdeckt und wie wir triumphiert haben!\n\nTretet einfach durch das Portal, um auf den Hyjal zurückzukehren.", sourceObjective = "Kehrt zu Takrik Wutheuler am Schrein von Goldrinn auf dem Hyjal zurück.", completion = "Sie bringen Verstärkung direkt über die Elementarebenen auf den Hyjal? Das erklärt natürlich einiges!\n\nLo'Gosh ist gewiss stolz auf Euch, weil Ihr dieses Flammentor versiegelt habt, {name}, aber vielleicht gibt es noch mehr Portale, die versiegelt werden müssen. Ihr solltet auch die anderen Schreine untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25613] = { id = 25613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euch selbst einen Gefallen", description = "Also diese Nachtelfen haben einen verzweifelten Hilferuf an uns geschickt, der sich so anhörte:\n\n<Gnombus verstellt seine Stimme, um wie eine Frau zu klingen.>\n\n\"Bitte kommt und helft uns! Die große, gemeine Horde hat Goblins! Oh, wir kommen mit Goblins nicht klar! Sie ziehen uns an den Haaren und bringen uns zum Weinen!\"\n\nGut, also, hier sind wir nun.\n\nDas erste, was ich gemacht habe, war ihre Luftverteidigung mit einigen meiner neuen Scharfschützengewehre auf Vordermann zu bringen. Das Problem ist... Sie benutzen keine Schusswaffen. Tut Euch selbst einen Gefallen und helft ihnen, ok? Ihr findet sie südlich von hier.", sourceObjective = "Sprecht mit Kalen Freipfeil am Volltrefferposten im Steinkrallengebirge.", completion = "<Kalen seufzt.>\n\nWir benutzen Schusswaffen ganz ohne Probleme, mein Freund. Gegen KANONEN habe ich allerdings etwas...", sourceObjectiveStatus = "unverified-source-field" }
quests[25614] = { id = 25614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einzige Weg nach unten ist im Leichensack", description = "Am Himmel wimmelt es nur so von schwerbewaffneten Orcs, die auf noch schwerer gepanzerten Windreitern sitzen. All unsere Bemühungen, sie vom Himmel zu holen sind gescheitert. Unsere Pfeile prallen normalerweise einfach von diesen widerwärtigen Kreaturen ab. Wenn es uns gelingen sollte, einen abzuschießen, benutzen die Orcs ihre Goblinfallschirme und landen sicher auf dem Boden.\n\nIhr müsst die Scharfschützenkanonen von Gnombus benutzen und damit erst die Windreiter des Kriegshymnenklans und danach die Orcs an den Fallschirmen abschießen.\n\nDer einzige Weg nach unten ist im Leichensack.", sourceObjective = "Tötet 8 Schwadronskommandanten des Kriegshymnenklans.", completion = "Ausgezeichnete Arbeit, {name}. Die Gnomtechnologie ist zwar leicht nervtötend, aber ziemlich wirksam. Jetzt sollten der Weg zur Scherwindfeste frei sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25615] = { id = 25615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Sternenstaubspitze zurück", description = "Jägerin Jalin wird erfreut sein zu hören, dass der Weg zur Scherwindfeste jetzt frei ist. Bitte kehrt zur Sternenstaubspitze zurück und informiert sie über unseren Erfolg. Sie wird mit ziemlicher Sicherheit noch mehr Arbeit für Euch haben, da der Weg jetzt frei ist.\n\nVielen Dank und viel Glück, <mein Freund/meine Liebe>.", sourceObjective = "Kehrt zu Jägerin Jalin an der Sternenstaubspitze im Eschental zurück.", completion = "Jetzt, da die Luft rein ist, sind unsere Hippogryphen in der Lage, sich frei ins Steinkrallengebirge zu bewegen. Gut gemacht, {name}!\n\nUnd jetzt wenden wir uns wichtigeren Dingen zu. \n\nWas Ihr am Volltrefferposten erlebt habt, war nur ein Beispiel für die Vernichtung, die Höllschrei hinter sich zurücklässt. Als Kriegshäuptling der Horde hat Höllschrei Kalimdor zum Territorium der Horde erklärt. Alle, die sich der Horde widersetzen, werden vernichtet.\n\nWir sind die letzte Verteidigungslinie von Kalimdor. Wenn wir fallen, fällt Kalimdor. Die Horde muss aufgehalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25616] = { id = 25616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Vermächtnis", description = "Begebt Euch über den Steinkrallenpass ins Steinkrallengebirge und lauft in Richtung der schwelenden Bäume. Sucht Verbrenner von Krom'gar, die den Wald zerstören und tötet so viele Ihr könnt! Aber Vorsicht, die Verbrenner sind mächtige Orcs. Wenn Ihr sie mit normalen Mitteln angreift, bedeutet das wahrscheinlich Euren Tod. Zerstört die Ölkanister auf ihren Rücken und sie werden von den Flammen verschlungen!\n\nWenn Ihr Erfolg habt, meldet Euch bei Schildwache Heliana an der Scherwindmine. Sie wird neue Befehle für Euch bereithalten.", sourceObjective = "Tötet 10 Verbrenner von Krom'gar.", completion = "Jetzt, da Ihr Euch um die Verbrenner von Krom'gar gekümmert habt, kann der Wald vielleicht wieder nachwachsen. Allein die Zeit kann die Wunden heilen, die die Horde hinterlassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25617] = { id = 25617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Ich weiß nicht, wohin es führt. Ich weiß nur, dass es nicht zu dieser Welt gehört und ich es nicht betreten kann. Und alle meine anderen Anhänger, die hineingegangen sind, kamen nie wieder heraus.\n\nIch möchte, dass Ihr dieses Reich betretet und meine Klauen und Zähne darin seid. Tretet durch das Flammentor. Wenn er noch lebt, dann trefft Euch auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr meine Macht in diesem Reich nutzen könnt.\n\nSeid mutig, {name}. Findet heraus, wohin das Flammentor führt, und vernichtet alles, was Ihr dahinter findet.", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", completion = "Ah, Ihr seid also der Champion, so wie Lo'Gosh es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Allianz auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Lo'Goshs Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[25618] = { id = 25618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Ich weiß nicht, wohin es führt. Ich weiß nur, dass es nicht zu dieser Welt gehört und ich es nicht betreten kann. Und alle meine anderen Anhänger, die hineingegangen sind, kamen nie wieder heraus.\n\nIch möchte, dass Ihr dieses Reich betretet und meine Klauen und Zähne darin seid. Tretet durch das Flammentor. Wenn er noch lebt, dann trefft Euch auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr meine Macht in diesem Reich nutzen könnt.\n\nSeid mutig, {name}. Findet heraus, wohin das Flammentor führt, und vernichtet alles, was Ihr dahinter findet.", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", completion = "Ah, Ihr seid also der Champion, so wie Goldrinn es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Horde auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Goldrinns Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[25619] = { id = 25619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbesetzung", description = "An Kvaldir zum Töten mangelt es hier nicht. Offensichtlich hat unser Angriff sie ganz schön aus der Bahn geworfen. Die Stadt war so lange verlassen, dass sie wahrscheinlich nicht damit gerechnet haben, auf Gegenwehr der Naga zu stoßen.\n\nÜber ihren Anführer haben wir bisher noch nichts erfahren. Ich bin mir sicher, dass wir diesen Feigling noch früh genug aus seinem Loch hervorlocken können, wenn wir seine Leute weiter abschlachten.\n\nWollen wir fortfahren?", sourceObjective = "Tötet 10 Verteidiger der Kvaldir in den Ruinen von Vashj'ir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Ich habe Geschichten von der Wildheit dieser Kvaldir gehört, aber bis jetzt scheint das nur heiße Luft zu sein.", completion = "Ha! Ihr hattet wohl Recht. Dieser zerbrochene Dreizack scheint Euch gute Dienste zu leisten. Ich schätze, ich werde heute nicht zu sehen bekommen, wie Ihr etwas mit bloßen Klauen zu Tode reißt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25620] = { id = 25620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ehrwürdige Lady", description = "Die ehrwürdige Lady sendet Euch eine Botschaft. Sie erwartet Euch auf der anderen Seite der Tempelgärten.\n\nWenn Ihr das Bedürfnis verspürt, die heldenhaften Taten Eures treuen Waffenbruders Azjentus zu erwähnen, bitte, tut Euch keinen Zwang an. Ich werde Eure Bewunderung für mich nicht als Schwäche auslegen.\n\nDoch jetzt halte ich Euch nicht länger auf. Die Dame wartet.", sourceObjective = "Sprecht mit Lady Naz'jar am nördlichen Ende der Gärten von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Ah, meine Kriegsmaid, da seid Ihr ja. Die Kriegerkaste spricht nur noch von Euren Siegen auf dem Schlachtfeld. Und das, wo wir unsere Bemühungen, die Stadt einzunehmen, doch gerade erst begonnen haben.\n\nIhr habt mir bisher treu gedient und mich mit Stolz erfüllt. Möge die Königin Euch ihre Gunst gewähren, damit dies auch in Zukunft so sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[25621] = { id = 25621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldversuch: Gnomcorder", description = "Die Gnomcordär ist fertisch! Jetzt wir müssen machen eine Test!\n\nIhr müsst ge'en nach die Steinkrallengebirge in die Südenosten und ge'en über die Steinkrallenpass bis zu die dreckische Goblinbohrmaschin'. Isch werde aktivieren die Gnomcordär wenn Ihr 'abt erreischt Eure Ziel!Ihr erlernt:", sourceObjective = "Begebt Euch ins Steinkrallengebirge und geht den Steinkrallenpass Richtung Süden entlang, bis Ihr die große Goblinbohrmaschine findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25622] = { id = 25622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn, Baby, Burn!", description = "Diese Verbrennär von die Orcs 'aben schlimme Waffen um zu brennen die Wald niedär! Ihr müsst sie töten und nehmen die Flammenwerfär. Wenn Ihr 'abt die Flammenwerfär, Ihr müsst suchen nach die Vorräte von die Kriegs'ymnenklan und benutzen die Flammenwerfär für abzufackeln!\n\nVerbrennt sie alle und isch werde Eusch belohnen! Ja, die Gnomcordär kann transportieren Dinge.\n\nWartet! 'ört Ihr das? Isch glaube, eine Orc is in die Näh'! Vorsischt!", sourceObjective = "Bringt einen Flammenwerfer des Kriegshymnenklans von einem Verbrenner von Krom'gar an Euch und benutzt ihn, um 8 Vorräte des Kriegshymnenklans zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25623] = { id = 25623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "{name}, da seid Ihr ja! Goldrinn hat eine Aufgabe, die nur sein Champion erfüllen kann. Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Wir wissen nicht, wohin es führt, aber Goldrinn kann es nicht betreten. Der Ahn möchte, dass Ihr seine Klauen und Zähne seid.\n\nTretet durch das Flammentor und sprecht auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr Goldrinns Macht in diesem Reich nutzen könnt. Findet heraus, wohin das Flammentor führt!", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[25624] = { id = 25624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "{name}! Lo'Gosh braucht Euch. Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Wir wissen nicht, wohin es führt, aber keiner, der es betreten hat, ist je zurückgekommen. Lo'Gosh möchte, dass Ihr hindurchgeht und seine Klauen und Zähne seid.\n\nTretet durch das Flammentor und sprecht auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr Lo'Goshs Macht in diesem Reich nutzen könnt. Findet heraus, wohin das Flammentor führt!", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[25626] = { id = 25626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", sourceObjective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", completion = "Diener des alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n{name}, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[25627] = { id = 25627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreibung für Zweihauer", description = "Diese Schätze sind alle nicht echt, aber die Knüppler im Unterschlupf werden den Unterschied nicht erkennen, so blöd, wie Oger sind!\n\nHier ist der Plan: Ihr begebt Euch in den Admiralsunterschlupf und verteilt diese \"Schätze\" an alle Oger, die Euch über den Weg laufen. Dann müsst Ihr Euch nur noch um Tony Zweihauer kümmern.\n\nSo bekommt Ihr den Schlüssel zum Käfig in null Komma nichts!", sourceObjective = "Erhaltet den rostigen Käfigschlüssel.", progress = "Was ist hier los? Holt Ihr mich hier raus?", completion = "Ja, ja... sicherlich war Euer kleines Abenteuer in die Höhle sehr interessant.\n\nWarum unterhalten wir uns nicht bei einem Drink auf dem Turbodampfer in Ruhe darüber, wenn Ihr es noch schafft, mich hier rauszulassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25628] = { id = 25628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreibung für Zweihauer", description = "Diese Schätze sind alle nicht echt, aber die Knüppler im Unterschlupf werden den Unterschied nicht erkennen, so blöd, wie Oger sind!\n\nHier ist der Plan: Ihr begebt Euch in den Admiralsunterschlupf und verteilt diese \"Schätze\" an alle Oger, die Euch über den Weg laufen. Dann müsst Ihr Euch nur noch um Tony Zweihauer kümmern.\n\nSo bekommt Ihr den Schlüssel zum Käfig in null Komma nichts!", sourceObjective = "Erhaltet den rostigen Käfigschlüssel.", progress = "Was ist hier los? Holt Ihr mich hier raus?", completion = "Ja, ja... sicherlich war Euer kleines Abenteuer in die Höhle sehr interessant.\n\nWarum unterhalten wir uns nicht bei einem Drink auf dem Turbodampfer in Ruhe darüber, wenn Ihr es noch schafft, mich hier rauszulassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25629] = { id = 25629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand der Lady", description = "Kriegsmaid!\n\nSucht nach meiner Ehrenwache auf dem Schlachtfeld und nehmt ihnen ihre Feinde ab. Sie müssen sofort zurückkehren, um die Priesterinnen zu beschützen.\n\nIch kümmere mich um den Eingang. Beeilt Euch!", sourceObjective = "Besiegt die Gegner von 8 Mitgliedern der Ehrenwache der Naz'jar und übergebt ihnen ihre neuen Befehle.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Als die Kämpfe ausbrachen, habe ich meine Ehrenwache losgeschickt. Sie sind besser ausgerüstet, um mit dem Chaos dieser Schlacht umzugehen und ich bedarf kaum ihrer Hilfe.", completion = "Gut gemacht, Kriegsmaid.\n\nIch sehe nach der östlichen Brücke. Ihr müsst Euch um den Tempel kümmern. Das Ritual darf nicht unterbrochen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25630] = { id = 25630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuer des Hyjal", description = "Seht Ihr das, {name}? Vom Bergrücken südwestlich von hier… steigen Schwaden schwarzen Rauchs in den Himmel auf.\n\nDer Hyjal brennt.\n\nWenn die Feuer schon so hoch oben am Berg angekommen sind, bedrohen sie sicher auch den Hain von Aessina und unsere Streitkräfte dort.\n\nSprecht mit Laina Nachthimmel in der Nähe des Hains von Aessina. Als ich zuletzt von ihr hörte, bemühte sie sich, den Angriff abzuwehren.", sourceObjective = "Sprecht mit Laina Nachthimmel in der Nähe des Hains von Aessina auf dem Hyjal.", completion = "Kann das warten, {class}? Die Schlacht steht schlecht für uns.\n\nOh, Ihr seid hier, um zu helfen. Ich hoffe, Ihr mögt es heiß…", sourceObjectiveStatus = "unverified-source-field" }
quests[25637] = { id = 25637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Ruf des Tiefenlords", description = "Tiefenlord Zin'jatar hat uns berichtet, dass der Anführer der Kvaldir sich gezeigt hat. Begebt Euch zu ihm. Er befindet sich am gegenüberliegenden Ende der Terrasse über uns, auf der mittleren Ebene der Ruinen: Die Terrasse von Nar'shola.\n\nTötet alle Kvaldir, die Euch im Weg stehen. Wir möchten, dass der Widerhall dieser Niederlage in ihren Köpfen gellt, auf dass sie es nicht wagen, zurückzukehren und unser Vorhaben hier zu stören.\n\nEuer hingebungsvoller Einsatz bleibt nicht unbemerkt, meine Kriegsmaid. Geht und wisst, dass Ihr meinen Segen habt.", sourceObjective = "Tötet 16 Kvaldir auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Wie schön, dass Ihr Euch mir anschließt, Kriegsmaid. Kampfgeräusche untermalten Eure Ankunft. Welch süßer Klang in meinen Ohren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25638] = { id = 25638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Bitte", description = "Die Nachricht in dieser Flasche ist nass aber immer noch lesbar.\n\nDer Schreiber behauptet, aus einem Nagagefängnis unter dem Meer entkommen zu sein.\n\nEr fürchtet deutlich um sein Leben. Ihr fragt Euch, ob es sich dabei um einen Eurer kürzlich entführten Schiffskameraden handeln könnte.\n\nDa Ihr nicht wisst, wie Ihr den Flüchtling finden sollt, beschließt Ihr, Euren Fund Erunak zu zeigen.", sourceObjective = "Bringt die durchnässte Notiz zu Erunak am Tiefgang.\n\nBereitgestellter Gegenstand:", completion = "Wenn sie noch am Leben ist, kann ich diese arme Seele vielleicht finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25640] = { id = 25640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei: Scherwindmine!", description = "Wir 'aben entdeckt die Ort von die große Goblinbomb', die Ihr 'abt gefunden in Silberwindzuflucht.\n\nIhr Eusch erinnern an Boog? Die Gnom, die Ihr 'abt gerettet von die Orcwagen? Er und Minx 'aben gefunden die Bomb' in die Scherwindmine. Ihr müsst ge'en dort'in toute de suite... sofort, {name}! Sie werden warten auf Eusch.", sourceObjective = "Sprecht mit Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", completion = "Schön, Euch wiederzusehen, {name}. Danke für die Rettung in Eschental. Sehr schade um die ganzen Gnome, die wir verloren haben.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25641] = { id = 25641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muiseknachschub", description = "Ich habe alles getan, was ich für Euch tun konnte. Aber ich bin noch nicht mächtig genug, um mit etwas mächtigerem als Hippogryphenmuisek zu arbeiten - vor dem Desaster, das dadurch entstehen könnte, verschone ich Euch zuerst.\n\nWährend Ihr beschäftigt wart, habe ich den Hippogryphenmuisek fertiggestellt. Bringt es zu meinem Meister, dem Hexenmeister Uzer'i in Camp Mojache. Er kann damit mächtige Waffen herstellen und hoffentlich wird er von meinen bisherigen Leistungen beeindruckt sein.", sourceObjective = "Bringt das Gefäß für Hippogryphenmuisek zu Hexendoktor Uzer'i in Camp Mojache in Feralas.", progress = "Ihr kommt mir bekannt vor...", completion = "Gute Arbeit, in der Tat... von meiner eigenen Tochter hätte ich allerdings auch nicht weniger erwartet. Sie wird noch eine gute Hexe werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25642] = { id = 25642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaut ihnen nicht in die Augen", description = "Zieht Euren Kopf ein, {name}. Wir wollen keine ungebetene Aufmerksamkeit auf uns lenken.\n\nAnscheinend beladen die Orcs den Ballon mit irgendeinem Erz aus der Mine. Geht dort hinein und nehmt den Orcs das Erz weg. Bringt mir alles, das ihr tragen könnt und ich werde es zur Untersuchung zum Professor schicken.\n\nBevor Ihr geht noch ein Ratschlag: Ihr könnt die Krom'gar leicht umgehen, weil sie (1) dumm wie Bohnenstroh sind und (2) nichts sehen können, wenn sie Erz tragen. Natürlich müsst Ihr sie töten, um an das Erz zu kommen.", sourceObjective = "Sammelt 10 Proben azurblaues Eisenerz ein.", progress = "Bringt mir die Erzproben!", completion = "Ich hoffe, das hat Euch nicht zu viel Mühe bereitet. Mit diesen Proben sollten wir in der Lage sein herauszufinden, was sie mit dem Erz und der großen Bombe vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25643] = { id = 25643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Graunebelruinen", description = "Ich werde von Visionen heimgesucht, {name}. Visionen eines großen Machtsymbols, das in die Hände eines dunklen Wesens fällt. Ich sehe ein Amulett, von den uralten Elfen gehalten... das in Vergessenheit geraten ist und alles in seiner Umgebung in Ruinen verwandelt, bis die Dämonen es durch Betrug und Bosheit erhalten.\n\nJede Nacht schleichen sich diese Bilder wieder und wieder in meine Träume. Die Geister schicken uns eine Warnung. Ich bin zu alt und die Kriegerhelden des Lagers sind damit beschäftigt, uns zu beschützen. Ich bitte Euch, folgt meinen Visionen in Richtung Süden zu den Graunebelruinen und macht das Amulett ausfindig.", sourceObjective = "Sucht in den Graunebelruinen nach dem Amulett, das der Weise Bleichlauf beschrieben hat.", completion = "<Als Ihr Euch dem Podest nähert, merkt Ihr, dass es leer ist. Kälte füllt den Raum und eine leise Stimme ertönt...>", sourceObjectiveStatus = "unverified-source-field" }
quests[25644] = { id = 25644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zwielichtei", description = "Dieses Ei ist anders als alles, was Ihr je gesehen habt. Die durchsichtige Schale scheint das Licht um sie herum zu brechen.\n\nDaneben findet Ihr eine Nachricht, die die Ankunft einer fruchtbaren Brutmutter im Zirkel des Aszendenten beschreibt.\n\nVielleicht solltet Ihr Aronus das hier zeigen.", sourceObjective = "Bringt das reine Zwielichtei zu Aronus an den Toren von Sothann auf dem Hyjal.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt richtig gehandelt, mir dies zu bringen, {name}. Dies ist eine große Bedrohung für uns, der wir uns unverzüglich und furchtlos stellen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25645] = { id = 25645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Weisen Bleichlauf zurück", description = "Das sanfte Leuchten bei dem Podest wird heller und Ihr könnt eine einfache Kette erkennen, die dort zurückgelassen wurde. Das muss das Amulett sein, wegen dem Euch der Weise Bleichlauf hergeschickt hat...", sourceObjective = "Bringt das Graunebelamulett zum Weisen Bleichlauf.", progress = "Ihr seid zurückgekehrt. Was habt Ihr gefunden?", completion = "Ich bin ein Narr... ich wurde in die Irre geleitet. Dies ist nur ein rostiges Stück Schmuck - meine Visionen haben sich zweifellos bewahrheitet.\n\nVergebt mir, {name}. Ich werde dafür beten, dass Ihr über diese Dämonin siegen werdet, so wie Ihr über Verinias gesiegt habt, solltet Ihr sie jemals wiedertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25646] = { id = 25646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Scherwindmine", description = "Die Horde hat die Scherwindmine eingenommen. Ich bin nicht sicher, was diese Orcs hier herausschleppen oder warum sie hier sind, aber ich weiß, das kann nichts Gutes bedeuten. Geht dort hinein und schaltet die Führung aus. Ohne die Goblinaufseher werden diese Peons noch nutzloser sein.\n\nWährend Ihr dort drin seid, haltet die Augen offen, ob Ihr noch weitere Informationen findet, was die Horde dort in den Minen treibt.\n\nViel Glück.", sourceObjective = "Tötet 6 Vorarbeiter der Scherwindmine.", completion = "Gute Arbeit, ich konnte ihre schrillen Schreie von hier aus hören! Ihr habt den ganzen Ort auf den Kopf gestellt!\n\nHabt Ihr noch weitere Informationen über die Vorgänge in der Mine gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25647] = { id = 25647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleserlicher Orcbrief", description = "Ihr habt ein Pergament mit einem beeindruckenden Hordensiegel darauf gefunden. Leider ist der Rest des Dokuments vollkommen unverständlich, weil es auf Orcisch ist.\n\nBringt den Brief zu Boog. Vielleicht weiß er etwas damit anzufangen!", sourceObjective = "Bringt den unleserlichen Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", progress = "Was habt Ihr da für mich?", completion = "<Boog nimmt Euch den Brief ab und studiert ihn.>\n\nInteressant.\n\n<Boog riecht an dem Pergament.>\n\nHrm... Beunruhigend...\n\n<Boog faltet das Papier auf der Hälfte und schaut Euch an.>\n\nIch verstehe absolut gar nichts von dem, was da geschrieben steht - wenn es überhaupt geschrieben ist. Könnte auch Klopapier sein. Riecht auf jeden Fall so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25648] = { id = 25648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jenseits von Durotar", description = "Hmpfff ... Eure Dienste werden anscheinend anderswo benötigt. Ag'tor Blutfaust sucht nach Rekruten, die die Unternehmungen der Horde in Azshara nördlich von Orgrimmar unterstützen.\n\nIhr habt sicherlich noch Arbeit hier in Durotar und ich hörte, dass man Euch bald um Hilfe im Brachland bitten wird. Also ich an Eurer Stelle würde nirgendwo hingehen, aber wenn Ihr unbedingt das Schicksal herausfordern wollt... Azshara wartet.", sourceObjective = "Meldet Euch bei Ag'tor Blutfaust am Hinteren Tor von Orgrimmar in Azshara.", completion = "Gut, Ihr seid hier. Willkommen in Azshara, der Bühne für den nächsten Akt der ruhmreichen Zukunft der Horde. Und jetzt an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25649] = { id = 25649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minx wird's schon richten", description = "Die gute Nachricht ist, dass Minx fließend Orcisch spricht und sie ist in der Nähe. Geht zurück in die Mine und findet sie. Sie ist wahrscheinlich etwas tiefer in der Mine und steht nutzlos herum.\n\nVergesst das Pergament nicht.", sourceObjective = "Bringt den unleserlichen Orcbrief zu Minx in der Scherwindmine im Steinkrallengebirge.", progress = "Was habt Ihr da für mich?", completion = "<Minx nimmt Euch den Brief ab und studiert ihn.>\n\nOha.\n\n<Minx riecht an dem Pergament.>\n\nIst ja widerlich!\n\n<Minx faltet das Papier auf der Hälfte und schaut Euch an.>\n\nDie gute Nachricht ist - es ist kein Klopapier. Die schlechte Nachricht ist, dass die Tinte auf diesem Papier eine Mischung aus Kododung und Blut ist. Und das ist noch nicht das Schlimmste...", sourceObjectiveStatus = "unverified-source-field" }
quests[25650] = { id = 25650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Oberkommandos", description = "Bei dem Brief handelt es sich um Befehle des Hordenoberkommandos. Jemand mit Namen Oberanführer Krom'gar hat angeordnet, dass diese Mine \"ausgeräumt\" werden soll, um einen Splitter von etwas zu erhalten, das \"Azurblaues Eisenerz\" heißt. Wahrscheinlich erhält man diesen Splitter, wenn man das Erz abbaut.\n\nEs wird noch schlimmer. Sie haben vor, diesen azurblauen Splitter mit Sprengstoffen in der riesigen Bombe zu vermischen und dann die Scherwindfeste in die Luft zu jagen.\n\nWir dürfen keine Zeit mehr verlieren, {name}! Nehmt diese Übersetzung des Briefs und kehrt zu Boog zurück! Er wird wissen, was als nächstes zu tun ist.", sourceObjective = "Bringt den übersetzten Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", progress = "Nun? Was steht da?", completion = "<Schweißperlen laufen Boog über die viel zu große Stirn, während er den übersetzten Brief liest.>\n\nDas ist übel. Richtig, richtig übel. Ihr müsst Lord Brachweiher in der Scherwindfeste warnen.\n\nWas zur…? Er BEWEGT sich! Der Goblinballon hebt ab! Wir kommen zu spät!", sourceObjectiveStatus = "unverified-source-field" }
quests[25651] = { id = 25651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh süßer Wahnsinn!", description = "Also, ich habe nachgedacht…\n\nWenn jemand total durchgeknallt ist, weiß er das dann?\n\nIch könnte zum Beispiel schwören, dass ich ein Fass mit Schießpulver von den Kanonenkugeln hier gesammelt habe, aber es ist einfach unauffindbar.\n\nIch erinnere mich noch genau daran, wie ich die Kanonenkugeln von den Gilblins westlich von hier stibitzt habe.\n\nVielleicht stimmen die Gerüchte ja... vielleicht habe ich wirklich nicht mehr alle Tassen im Schrank.", sourceObjective = "Sammelt 50 gestohlene Kanonenkugeln auf Gurboggels Fels und von Hamsterern der Gilblin. Benutzt die Kanonenkugeln, um ein Fass mit Schießpulver herzustellen.", progress = "Ihr wollt nichts mit mir zu tun haben, {race}.\n\nIch bin ein bisschen… meschugge.", completion = "Mein Schießpulver!\n\nIhr habt es gefunden! Ich bin also doch nicht verrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25652] = { id = 25652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschlagnahmt den Ballon!", description = "Wir dürfen keine Zeit verlieren, {name}. Ihr müsst diesen Heißluftballon beschlagnahmen und aufhalten!\n\nWie? Keine Ahnung! Wir haben keine Zeit, uns um Details zu streiten! Schnappt Euch die Strickleiter und klettert hinauf! Dann prügelt einfach auf alles ein, wenn Ihr drin seid!\n\nWenn Ihr den Ballon irgendwie anhalten könnt und überlebt, meldet Euch bei Lord Brachweiher in der Scherwindfeste im Westen.\n\nViel Glück, wir alle zählen auf Euch. Wenn Ihr mich jetzt entschuldigen wollt, ich muss um MEIN LEBEN RENNEN!", sourceObjective = "Fahrt mit dem Heißluftballon von Krom'gar und versucht zu verhindern, dass er die Scherwindfeste zerstört.", completion = "Unglaubliche Geschichte, mein Freund. Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich Euch nicht glauben. Ihr habt dem Ballon so viel Schaden zu gefügt, dass Ihr diese Unholde zum Rückzug gezwungen habt! Leider ist die Bedrohung noch längst nicht abgewendet! Wir haben den Angriff nur hinausgezögert. Es gibt noch viel zu tun, wenn wir die Horde davon abhalten wollen, das Steinkrallengebirge zu zerstören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25653] = { id = 25653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ahnen sind mit uns", description = "Nemesis… vernichtet.\n\nIch fühle mich jung.\nMächtig.\nErleuchtet.\n\nSagt Ysera, dass meine Stärke ganz ihr gehört.\n\nDer Schattenhammer wird fallen.", sourceObjective = "Kehrt zu Ysera in Nordrassil auf dem Hyjal zurück.", completion = "Indem Ihr Tortolla von seiner letzten Last befreit habt, habt Ihr uns einen ausgezeichneten Verbündeten verschafft… und das letzte Stück unseres Plans.\n\nMacht Euch bereit, {name}. Der schwierigste Teil unserer Reise steht kurz bevor.\n\nWir werden den Kampf in ihre Feste tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25654] = { id = 25654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Harpyien der Nordschwingen, die in den Ruinen westlich von hier leben. Es ist ihr bösartiger Wille, der die Harpyien dazu anregt, ihre Nester inmitten der Ruinen unseres Volkes zu verteidigen.\n\nDie Harpyien können sie mit einem speziellen Horn rufen. Wenn man das Horn bei den Hasskrallensteinen im nördlichen Teil der Ruinen bläst, so erscheint Edana.\n\nZeigt diesen garstigen Kreaturen keine Gnade. Tötet Edana, und bringt mir ihr dunkles Herz.", sourceObjective = "Tötet Edana Hasskralle und erhaltet Edanas dunkles Herz.", progress = "Wir dürfen den Einfall der Harpyien in die Ruinen unserer Vorfahren nicht einfach hinnehmen.", completion = "Diese Länder werden endlich von der Bosheit der Harpyien befreit sein. Ich kann Euch nicht genug danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25655] = { id = 25655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wurmschwingenproblem", description = "Himmelsfürst Omnuron war viel zu nachgiebig mit den Harpyien der Wurmschwingen und hat ihnen sogar gestattet, sich auf diesem Berg niederzulassen. Einfach nur, weil es Wesen der Luft sind. Nun, {class}, nicht alle Wesen der Luft sind gleichrangig.\n\nAls die Angriffe auf den Hyjal begannen, verfielen die Wurmschwingen in Raserei. Sie sind direkt dort oben und greifen einen heiligen Schrein an, den sie einst verehrten.\n\nAber kein Grund zur Klage. Schließlich haben wir jetzt einen Grund, sie vom Hyjal zu vertreiben, oder?", sourceObjective = "Tötet 10 Harpyien der Wurmschwingen (Kreischerinnen oder Schnellklauen).", completion = "<Thisalee nickt zufrieden und ihre Augen leuchten.>\n\nEs ist großartig, nicht mehr an der kurzen Leine gehalten zu werden, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25656] = { id = 25656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf beim Eierklau", description = "Hinter diesen Angriffen der Wurmschwingen steckt ein Muster. Während einige Gruppen einen aufsehenerregenden Angriff auf den Schrein selbst durchführen, durchforsten andere die Nester in der Nähe und machen sich mit den Eiern aller fliegenden Wesen des Hyjal aus dem Staub.\n\nDiese Tiere stehen unter unserem Schutz. Bis wir herausgefunden haben, warum die Wurmschwingen das tun, müssen wir so viele Eier wie möglich vor ihren Klauen retten.", sourceObjective = "Sammelt 8 Hyjaleier.", progress = "<Thisalee säubert ihre Fingernägel mit einem Dolch. Sie schaut Euch erwartungsvoll an.>", completion = "Gut, das ist zumindest ein Anfang.\n\nDie Vögel, die diese Eier gelegt haben, werden sie nicht wieder annehmen. Wir werden die Küken als Waisen im Schrein aufziehen müssen. Wenn Aviana hier wäre, hätte sie diese Schandtat nie zugelassen.\n\nAber zurück zum Geschäft...", sourceObjectiveStatus = "unverified-source-field" }
quests[25657] = { id = 25657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da dap… Da dap...", description = "Da Ihr so nett zu mir wart, werde ich Euch in ein ganz besonderes Geheimnis einweihen.\n\nIch habe den größten Glitzerkram von allen gefunden, keine 50 Schritt von uns entfernt!\n\nNur eines steht noch zwischen Euch, mir und einem großen Vermögen, und das ist Nager.\n\nAber keine Sorge, ich habe einen Plan.\n\nNager liebt Maden, also habe ich eine davon mit Schießpulver gefüllt, als Falle sozusagen. Versteht Ihr?\n\nLasst sie einfach im Riff vor sich hin treiben. Sobald der Hai tot ist, sind wir reich!", sourceObjective = "Budd möchte, dass Ihr den präparierten Köder bei der rostigen Harpunenkanone im Skelettriff benutzt.", completion = "Beeindruckend!\n\nDa beobachtet man, wie die große weiße Bestie in die Tiefen davon schwimmt und fragt sich, ob es irgendetwas gibt, das ihn erledigen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[25658] = { id = 25658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Ewigkeit gebaut", description = "Herrin, ich habe eine Bitte der Hohepriesterin, die ich an Euch weitergeben soll. Viele der Verteidigungsanlagen der Stadt stammen noch aus der Zeit, lange bevor sie in den Wellen versank. Sie erneut zu aktivieren ist nicht schwer, wären da nicht die zahllosen Kvaldir, die uns im Weg sind.\n\nEs wurde uns berichtet, dass Ihr oben auf der Terrasse von Nar'shola kämpfen werdet. Ihr würdet meiner Herrin einen großen Dienst erweisen, wenn Ihr im Vorbeigehen diese Geräte einfach berühren könntet. Euer edles Geblüt sollte mehr als ausreichen, um sie zu reaktivieren.", sourceObjective = "Reaktiviert 6 Barrieren von Nar'shola.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Die Hohepriesterin sendet Euch ihren Dank für Eure Hilfe bei unseren Pflichten.", completion = "Die Barrieren von Nar'shola funktionieren einwandfrei. Ich werde die Herrin der Gezeiten sofort über Eure Hilfe informieren.\n\nVielen Dank, edle Dame.", sourceObjectiveStatus = "unverified-source-field" }
quests[25659] = { id = 25659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvergesslich", description = "Der Anführer der Kvaldir hat sein verrottendes, hässliches Gesicht nicht weit von hier den westlichen Gang entlang gezeigt. Wenn wir ihn jetzt töten, findet die Belagerung unserer geliebten Stadt durch die Kvaldir endlich ein Ende.\n\nVorsicht, Kriegsmaid, denn er ist alles andere als ein Schwächling. Es stehen viele Kvaldir unter seinem Befehl. Einige Meerhexen der Sira'kess wurden losgeschickt, um ihn während Eures Angriffs zu schwächen, aber wenn Ihr zulasst, dass seine Kvaldir sie angreifen, werden sie unterbrochen.\n\nZeigt keine Gnade, Kriegsmaid.", sourceObjective = "Tötet Varkul den Unerbittlichen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "<Der General der Kvaldir bricht besiegt zusammen.>\n\n<Damit hat Lady Naz'jar die Ruinen von Vashj'ir erobert. Ihre eigentlichen Ziele kennt Ihr nicht, aber es ist klar, dass die Naga aus einem bestimmten Grund hierhergekommen sind.>\n\n<Ihr seid Euch sicher, dass der Schlüssel zum Sieg über die Naga in dieser Vision liegt. Wenn Ihr weitermachen könntet, würdet Ihr sicher die Antworten finden, aber die Magie der Wellensprecherin wird schwächer und Ihr verliert die Verbindung zur Kriegsmaid.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25660] = { id = 25660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgt", description = "Ihr meint wohl, ich lasse Euch für meinen Tod einfach so gehen, hm? Sicherlich nicht! Ich habe mein Piratenhandelsimperium mit nichts nicht aufgebaut, um Euch dabei zuzusehen, wie Ihr mich tötet.\n\nIhr werdet mir dabei helfen, wieder zum Leben zu finden. Findet meine Exfrau Ajamon im Norden des Stützpunkts. Immer der Nase nach - sie wird mit Sicherheit bei dem stinkenden Kessel sein.", sourceObjective = "Sprecht mit Ajamon Geistrufer in Südmeerstützpunkt in Tausend Nadeln.", completion = "Was wollt Ihr denn? Oh nein, ganz sicher nicht. Ich sehe, dass Ihr Tonys Geist bei Euch habt, und damit will ich wirklich nichts zu tun haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25661] = { id = 25661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ein bisschen Hilfe...", description = "Nun gut, ich werd' Euch helfen. So leicht wird er nicht darum kommen, mir Alimente zu zahlen! Un' außerdem muss er sich ja bald auch noch um das Kind kümmern, das er mit meiner Schwester zeugen musste!\n\nZuers' brauchen wir die Innereien seiner besten Freunde; das sind wohl die Kapitäne.\n\nGeht und stattet den drei einen Besuch ab.", sourceObjective = "Erhaltet Gruseldollys Herz, Seebär Fajardos Lungen und Lilly Landrattes Leber.", progress = "Wir brauchen ein frisches Herz, Lungen, und eine Leber. Die von seinen Kapitänen werden wohl ausreichen müssen, obwohl sie sicher nicht die frischsten sind.", completion = "<Ajamon verzieht ihr Gesicht, als sie sieht, in welchem Zustand die Organe sind.>\n\nEs geht wohl nicht anders. Ist ja nicht so, als hätte er viele Freunde gehabt. Nicht wahr, Zweihauer?", sourceObjectiveStatus = "unverified-source-field" }
quests[25662] = { id = 25662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit unsere Schwestern", description = "Gestern Morgen habe ich eine Schwadron Jägerinnen auf eine Mission zur Scherwindklippe geschickt, damit sie Informationen über die Bewegungen der Horde im Steinkrallengebirge beschaffen. Nach Geheimdienstinformationen sind sie alle gefangen genommen worden, einschließlich der Schwadronsführerin, Jägerin Illiona.\n\nGeht nach Osten zur Scherwindklippe und tötet Infanteristen von Krom'gar, die die Klippe eingenommen haben. Nehmt ihnen die Schlüssel ab, mit denen man die Hordenkäfige, in denen unsere Schwestern sitzen, öffnen kann.\n\nTut Euer Bestes, um Illiona zu finden, sobald Ihr die Jägerinnen befreit habt.", sourceObjective = "Bringt 5 Käfigschlüssel der Horde an Euch, um 5 gefangene Jägerinnen freizulassen.", completion = "Wir haben nicht viel Zeit. Um mich hier herauszuholen, müsst Ihr Kriegsfürst Roktrog ausschalten. Er hat den Schlüssel für dieses Gefängnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[25663] = { id = 25663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe für Aviana", description = "Obwohl die Wächterin aller geflügelten Wesen nicht mehr körperlich unter uns weilt, höre ich sie manchmal in den rauschenden Blättern flüstern.\n\n{name}, wir verlangen viel von Euch, um diesen Berg zu beschützen. Doch bevor Ihr weitermacht, nehmt Euch einen Augenblick Zeit für die Andacht.\n\nBringt diese Nektargabe zu Avianas Grabkreis, einem Steinkreis direkt jenseits des Haupteingangs zum Schrein. Vielleicht helfen ein paar Augenblicke alleine mit der Erinnerung an Aviana Euch dabei, Euren Geist zu schärfen.", sourceObjective = "Benutzt den heiligen Nektar an Avianas Grabkreis.", progress = "<Der Geist erscheint immer wieder in Eurer Vision und verschwindet gleich darauf, als ob er hier und gleichzeitig woanders wäre.>", completion = "<Ein geflüstertes Flehen ertönt in Eurem Kopf.>\n\nWieder geboren zu werden, aber in Dunkelheit…\n\nIch wurde geraubt.\n\n<Der Geist scheint aufgewühlt, wird jedoch stumm, als das Bild wieder schwindet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25664] = { id = 25664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gebet und ein Flügel", description = "Ein Gesicht mit Schwingen? Kann es etwa sein…?\n\n{name}, wir haben keine Zeit zu verlieren. Vielleicht habt Ihr mit Aviana selbst gesprochen, die versucht, zu uns zurückzukehren.\n\nIch benötige etwas aus Avianas Vergangenheit, um mit ihr Kontakt aufnehmen zu können. Hoch oben auf dem Gebirgskamm, der diesen Schrein überblickt, findet Ihr eine Reihe von riesigen Nestern. Sie gehören Blaithe, einem uralten Raubvogel, der einst ihr Gefährte war. Seit zehntausend Jahren vergeht er vor Kummer und hat dadurch seinen Verstand verloren.\n\nKlettert auf einen seiner Horste und benutzt diesen Lockruf, um ihn herbeizurufen. Tötet Blaithe und bringt mir eine seiner Federn.", sourceObjective = "Benutzt den riesigen Vogellockruf an einem von Blaithes Nestern oben am Rand der Welt. Tötet Blaithe und sammelt eine seiner uralten Federn.", progress = "Habt kein schlechtes Gewissen wegen Blaithes Verfassung. Der Kummer hat diesem Wesen vor Jahrhunderten die Seele geraubt. Er war nur noch ein Schatten seiner selbst, eine Bestie voll zügellosen Zorns.", completion = "Das war keine schöne Aufgabe, {name}, aber sie musste erledigt werden.\n\nWenn Aviana wirklich wieder zum Leben erweckt werden kann, kann Blaithe vielleicht eines Tages Dank Eurer Taten auch zurückkehren.\n\nUnd jetzt lasst uns sehen, ob wir mit unserer lange verlorenen Wächterin Kontakt aufnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25665] = { id = 25665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gesuch aus dem Jenseits", description = "<Ihr versteht nicht, worum der Geist Euch so dringend anfleht, aber vielleicht kann Choluna ja herausfinden, was hier vor sich geht.>\n\n<Sprecht mit Choluna innerhalb des Schreins!>", sourceObjective = "Kehrt zu Choluna im Schrein von Aviana auf dem Hyjal zurück.", completion = "Langsam, {class}! Ihr seht aus, als hättet Ihr einen Geist gesehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25666] = { id = 25666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht Euch die Hände schmutzig", description = "Lasst Euch nicht täuschen, {race}. Dieser Hai ist ganz schön gewitzt. Man überlebt hier unten nicht so lange, wenn man nicht das gewisse Etwas an Grips hat.\n\nIch will damit nur sagen, dass er sich sicher nicht so leicht reinlegen lässt. Wir müssen unseren Ansatz ein wenig überdenken.\n\nIch werde Euch jetzt noch nicht mit Details langweilen. Sammelt zunächst ein paar Innereien von diesen gigantischen Meeresraupen.\n\nMeint Ihr, Ihr schafft das?", sourceObjective = "Sammelt 5 schmierige Madeneingeweide von gigantischen Meeresraupen in der Nähe von Harrisons Ausgrabung.", sourceObjectiveStatus = "unverified-source-field" }
quests[25667] = { id = 25667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wendigos erlegen", description = "Die Wendigos im Graufelsbau südwestlich der Stadt sind uns schon lange ein Dorn im Auge. Ihre Kraft reicht zwar nicht aus, Kharanos direkt zu bedrohen, aber sie stellen Reisenden, Gebirgsjägerpatrouillen und Nachschubtransporten nach.\n\nIch werde meine Beobachter aus dem Graufelsbau abziehen, da ich sie an der Trollfront brauche. Würde es Euch etwas ausmachen, meinen Leuten bei der Verkleinerung des Wendigobestands zu helfen? Wenn sie nicht mehr so viele sind, können sie uns nicht länger angreifen.", sourceObjective = "Tötet 10 Wendigos im Graufelsbau. Ihr könnt Wendigos oder junge Wendigos töten.", completion = "Jetzt, da Ihr Euch um die Wendigos gekümmert habt, können wir unsere Bemühungen auf die Trolle der Frostmähnen im Osten konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25668] = { id = 25668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Vorräte", description = "Die Frostmähnen machen im Osten Ärger und die Wendigos spüren unsere Schwäche und werden mit ihren Überfällen immer dreister. Nur einer von vier Nachschubkarren ist in letzter Zeit hier sicher angekommen. Die Wendigos haben sich mit dem Rest davongemacht und bewahren alles im Graufelsbau, einer Höhle südwestlich von hier, auf. Wenn Ihr bereit seid, dorthin zu gehen und die gestohlenen Vorräte wiederzubeschaffen, wären Euch alle Einwohner der Stadt und die Gebirgsjäger, die Kharanos verteidigen, zutiefst dankbar.", sourceObjective = "Bergt 6 gestohlene Versorgungsgüter aus dem Graufelsbau.", progress = "Habt Ihr etwas von den vermissten Vorräten gefunden?", completion = "Gut gemacht, {name}. Die Gebirgsjäger werden froh sein zu hören, dass die halben Rationen der Vergangenheit angehören. Sie benötigen all ihre Kräfte, um gegen die Frostmähnen zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25669] = { id = 25669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es rappelt im Säge... Werk", description = "Seid bereit, {name}! Der Kriegsfürst kommt! Tötet ihn und nehmt seinen Schlüssel an Euch. Benutzt diesen Schlüssel, um mich freizulassen.\n\nWenn wir es hier heraus schaffen, meldet das Folgende bei Lord Brachweiher in der Scherwindfeste:\n\nDie Horde hat ihre Pläne, die Scherwindfeste zu zerstören, dank der Taten eines unserer Helden abgebrochen. Jetzt beabsichtigen sie, die Bombe zum Kriegsnarbental zu bringen und auf unsere Armeen abzuwerfen, die dort gegen die Horde kämpfen.\n\nSie müssen aufgehalten werden!", sourceObjective = "Tötet Kriegsfürst Roktrog und befreit Jägerin Illiona, indem Ihr Jägerin Illionas Käfigschlüssel benutzt.", completion = "Ein Held hat also ihre Pläne vereitelt, die Scherwindfeste zu zerstören, huh? Der Held wart Ihr, {name}. Ihr seid der Stolz der Allianz!\n\nAnscheinend habt Ihr uns allen ein wenig Zeit verschafft. Ich muss Pläne schmieden für den Kampf, der vor uns liegt. Geht zu den anderen Einwohnern der Scherwindfeste und bietet ihnen Eure Dienste an. Ich werde Euch rufen, wenn ich bereit bin, unsere Verteidigungsstrategie ins Leben zu rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25670] = { id = 25670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DA-dap-DA-dap-DA-dap", description = "Der alte Nager ist uns jetzt sicher auf den Fersen.\n\nZu Eurem Glück denke ich wie ein Hai.\n\nNager kocht vor Zorn und wir werden das zu unserem Vorteil nutzen.\n\nHier, ich habe auf meiner Schatzjagd diese Kette gefunden. Bindet sie an die Harpunenkanone.\n\nWenn Nager Euch sieht, wird er bestimmt vor Wut überschnappen. Und dann schlagen wir zu!\n\nIhr versucht, ihn alle zu machen und ich schleiche mich währenddessen dort hinein und schnappe mir den Glitzerkram.\n\nSchnell, {class}, bevor seine Zähne wieder nachwachsen!", sourceObjective = "Benutzt Budds Kette bei der rostigen Harpunenkanone im Skelettriff. Feuert die Harpune ab, wenn Nager sich über der Kanone befindet.", completion = "Es ist wirklich nicht so schlimm, wie es aussieht…", sourceObjectiveStatus = "unverified-source-field" }
quests[25671] = { id = 25671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde ausdünnen", description = "Die Zahl der Horde wächst, da Verstärkung aus dem Eschental und aus Azshara eintrifft. Diplomatie bringt bei diesen Unholden nichts. Das ist Höllschreis Horde und Höllschreis Horde will unser Blut! Wir werden nicht untätig herumsitzen und zulassen, dass sie unser Land einnehmen und unsere Leute töten. Wir müssen handeln!\n\nWir müssen die Horde ausdünnen! Betrachtet das als Eure tägliche Pflicht.\n\nGeht hinaus ins Steinkrallengebirge und tötet so viele Hordemitglieder, wie Ihr könnt. Zeigt ihnen, dass die Allianz sich nicht ergeben wird!", sourceObjective = "Tötet 20 beliebige Soldaten der Horde im Steinkrallengebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[25672] = { id = 25672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kadaversammlung", description = "Diese Organe hier sind schon mal ein guter Anfang, aber wir brauchen echt noch viel mehr anderes Zeugs. Normalerweise könnte man von der Familie was nehmen, aber es sind nur noch ich und Tony, der Sohn meiner Schwester übrig, und er ist es echt nicht wert!\n\nWir müssen also 'n Ersatz finden - 'ne Menge Kadaver, um genau zu sein!\n\nUnten in der Schimmernden Tiefe sind tonnenweise welche zu finden; die sind da, seit das Wasser alles überflutet hat. Hat alle Kreaturen dort getötet, das Wasser. Geht dorthin und bringt mir ein paar der Kadaver.", sourceObjective = "Sammelt 10 Kreaturenkadaver.", progress = "Mensch, Ihr müsst mir end viele von den Kadavern bringen! Sonst werden wir seinen törichten Geist nie loswerden!", completion = "Oh, das is' widerlich!\n\nAber wenigstens haben wir's bald. Nur noch eine Kleinigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[25673] = { id = 25673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach Alice fragen", description = "Herr Baunzer ist krank, <Onkel/Tante>. Kannst du ihm helfen? Du musst nur seinen Hut und seine Batterien finden, dann wird es ihm viel besser gehen. Ich würde sie ja selbst holen, aber ich kann Herrn Baunzer nicht alleine lassen!\n\nSein Hut wurde von den fiesen Typen der Venture Co. drüben am Wasserrad gestohlen und seine Batterien sind irgendwo in der Scherwindklippe versteckt. Du musst nur sehr gründlich nach ihnen suchen.\n\nWürdest du freundlicherweise Herrn Baunzers Sachen zurückholen, damit er den Fieslingen in der Horde eine Lektion erteilen kann?", sourceObjective = "Findet die BD-816 Kriegsmaschine, mechanisiertes Feuer, mechanisiertes Eis und mechanisierte Luft.", progress = "Herr Baunzer ist so traurig. Wir müssen ihn glücklich machen!", completion = "<Alice klatscht aufgeregt in die Hände.>\n\nHerr Baunzer, alles wird wieder gut! Hurrah!\n\n<Alice setzt fachmännisch alle Teile, die Ihr eingesammelt habt, in Baunzer ein.>\n\nOh, Herr Baunzer! Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[25674] = { id = 25674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergebener Stolz", description = "Dies hier ist eigentlich eine alte Orcstadt... eine der ältesten in Azeroth. Also, das war sie - bis die Oger uns hinausgedrängt haben.\n\nDie heutige Horde weigert sich, von Ogern besiegt zu werden. Meine Truppen und ich haben die Stadt mit Gewalt eingenommen und die Oger, die einmal hier gelebt haben, arbeiten jetzt als Sklaven. Jetzt fängt die Arbeit erst richtig an.\n\nIhr seht stark genug aus, aber ich will Beweise. Tötet einen der Oger, die uns immer noch belagern und kehrt zu mir zurück.", sourceObjective = "Tötet einen Wegelagerer der Schreckensfelsoger in der Feste Schreckensfels.", completion = "Gut gemacht, {race}. Ihr habt bewiesen, dass Ihr einen Oger niederstrecken könnt...eine beachtliche Leistung. Jetzt lasst uns doch mal sehen, ob Ihr eine Eisenmine der Allianz ebenfalls ausschalten könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[25675] = { id = 25675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogergefechte", description = "Ich habe Eure Handschrift da unten gesehen, {race}. Wie würde es Euch gefallen, noch weitere Oger zu jagen?\n\nWir haben nur diejenigen versklavt, derer wir habhaft werden konnten. Die meisten starken Oger brüten immer noch im Schreckensfelsposten und planen unser Ableben. Unsere Wachen können vereinzelte Angriffe aus dem Hinterhalt abwehren, aber wir haben uns noch nicht gut genug verschanzt und würden unter einem gut geführten Angriff schnell zusammenbrechen.\n\nGeht nach Süden zum Schreckensfelsposten und überbringt eine Nachricht, {name}. Tötet die stärksten Oger, bevor sie auf dumme Gedanken kommen.", sourceObjective = "Tötet 6 Raufer der Schreckensfelsoger und 5 Hexenmeister der Schreckensfelsoger.", completion = "Ihr habt Eure Sache heute gut gemacht, {name}. Ihr habt uns nicht nur Zeit bis zum nächsten Ogerangriff verschafft, sondern auch einige der Gefangenen eingeschüchtert, sodass sie jetzt härter arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25676] = { id = 25676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz", description = "Wir haben keine Hoffnung, die Mine von Nethergarde von der Allianz zurückerobern zu können... wenigstens noch nicht. Nethergarde wird gut verteidigt und ihre Nachschubrouten sind bewährt und stark. Unser Ziel ist es daher, ihrer Wirtschaft zu schaden. Wir können die Mine nicht mit Gewalt einnehmen, aber mit präzisen Einschnitten können wir die Wirtschaftlichkeit der Mine stark einschränken.\n\nIch werde dafür sorgen, dass meine Leute vor der Mine ein Ablenkungsmanöver ausführen. Geht nach Osten, schleicht Euch in die Mine und sprecht mit Rofilian Dane über Eure Rolle.", sourceObjective = "Meldet Euch bei Rofilian Dane in der Mine von Nethergarde in den Verwüsteten Landen.", completion = "Endlich lässt sich hier mal ein Verantwortlicher blicken. Ich hoffe, Ihr habt Euch locker gemacht... Zeit für ein kleines Tänzchen, Partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25677] = { id = 25677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles meins!", description = "Überall in dieser Höhle findet Ihr unbewachte Erzhaufen, die nur darauf warten, dass man an ihnen herumpfuscht. Am liebsten würden wir das Erz natürlich stehlen, aber dazu benötigt man Minenwagen, Schutz und Arbeiter - drei Dinge, die wir nicht haben. Also werden wir stattdessen die Schürfarbeiten mit ein wenig hochgradig ätzender Säure vereiteln.\n\nNehmt diese Flasche - VORSICHTIG - und träufelt den Inhalt auf diese Erzhaufen. Denn wenn wir das Erz nicht haben können, sollen sie es auch nicht haben.", sourceObjective = "Benutzt das konzentrierte Lösemittel auf 6 Erzhaufen in der Mine von Nethergarde.", completion = "Es gibt doch nichts Besseres, als einen richtig fetten Tritt in die Geldbörse, nicht wahr, ihr Allianzdummköpfe?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25678] = { id = 25678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Euer Schicksal", description = "Es kostet die Allianz ungefähr fünfzig Goldstücke, einen Minenarbeiter auszubilden, zweihundert, um einen Ingenieur auszubilden und dreihundert für einen Vorarbeiter. Jeder Allianzdummkopf, den wir töten ist nicht nur ein militärischer Sieg, es ist auch ein finanzieller Sieg.\n\nJetzt geht dort hinunter und vernichtet ihre Arbeiter!", sourceObjective = "Tötet 8 Minenarbeiter von Nethergarde, 3 Ingenieure von Nethergarde und 3 Großknechte von Nethergarde.", completion = "Hervorragende Arbeit Mir gefällt, wie Ihr an die Dinge herangeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25679] = { id = 25679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Berg hinein", description = "Die nächste Phase findet an einem noch tiefer gelegenen Ort in der Mine statt. Sprecht mit Tak'arili für Eure nächste Aufgabe. Folgt einfach den Schienen der Minenwagen nach Südosten um die Kurve herum. Ihr werdet ihn am Eingang zu den höher gelegenen Kammern der Mine sehen.\n\nEs war mir ein Vergnügen, mit Euch Geschäfte zu machen, {name}", sourceObjective = "Meldet Euch bei Tak'arili tiefer in der Mine von Nethergarde in den Verwüsteten Landen.", completion = "Gut, Ihr seid schon hier. Bleibt eine Weile, kleiner {race}. Wir werden mit der Allianz ein paar Spielchen treiben.\n\nIch liebe meinen Job, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25680] = { id = 25680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So sind wir nicht", description = "Das Wichtigste zuerst... sieht so aus, als ob wir ein Problem hätten. Die Minenarbeiter in dem Stollen rechts laufen herum wie ein Haufen aufgescheuchter, kopfloser Hühner. Ich kann nur vermuten, dass sie zu tief gegraben und etwas Unschönes gefunden haben... einen Dämon, ein Elementar oder irgendein Tentakelbiest.\n\nTak'arili mag keine Überraschungen. Findet heraus, was das Problem ist und kümmert Euch darum, dann können wir wie geplant weitermachen.", sourceObjective = "Findet und tötet das, was die Minenarbeiter in der Mine von Nethergarde so erschreckt hat.", completion = "Also war es ein Dämon? Diese Minenarbeiter haben noch nie einen Dämonen gesehen? Wir sind in den Verwüstete Landen, Mann! Dämonen sind überall!\n\n<Tak'arili seufzt.>\n\nNaja... wenden wir uns dem guten Zeug zu, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25681] = { id = 25681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Leute muss man einfach töten", description = "Wenn Ihr durch den Tunnel vor uns geht, der nach Westen führt, kommt Ihr direkt zum Büro von Chefausgrabungsleiter Hondo. Er ist hier der Obermotz und Tak'arili hat gehört, dass er ein richtig guter Minenarbeiter ist. Deshalb muss er sterben.\n\nEs gibt nur ein Problem: der Weg dorthin ist VOLL mit diesen lästigen Lakaien aus Nethergarde. Deshalb müsst Ihr Euch verkleiden. Hüpft in diese Kiste hier und schleicht Euch den Weg hinunter. Hoffentlich erregt Ihr nicht zu viel Verdacht auf dem Weg zu Eurem Opfer.", sourceObjective = "Tötet Chefausgrabungsleiter Hondo. Benutzt die unverdächtige Kiste, um Euch unterwegs zu tarnen.", completion = "Gute Arbeit, Mann! Ohne Hondo sind die Jungs hilflos. Die Mine wird schon bald uns gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25682] = { id = 25682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission abgeschlossen", description = "Wir sind hier fertig, Mann. Wir müssen nur noch einen Bericht an Okrilla schicken. Habt Ihr gerade etwas vor?", sourceObjective = "Liefert den Minenbericht von Nethergarde bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen ab.", progress = "Ihr seid zurückgekehrt, {name}?", completion = "<Okrilla überfliegt den Bericht.>\n\nBeeindruckend, {name}. Ich hätte mich zwar nicht in dieser Kiste versteckt, aber sonst habt Ihr Eure Sache tapfer und bewundernswert gemacht. Die Schlacht, die wir heute gewonnen haben, wird uns nicht unmittelbar zugutekommen, aber der Schaden, den Ihr der Allianz zugefügt habt, wird über lange Zeit anhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25683] = { id = 25683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreckensfelssenke", description = "Ich meinte das, was ich gesagt habe, {race}. Ihr habt mir geholfen, jetzt gebe ich weiter, was ich weiß.\n\nVor Kurzem machte ein Dämonenjäger kurz hier Halt. Er ging nach Süden und sprach von Dämonen. Eigentlich hätte ich den Nachtelfen sofort getötet, aber er schien nicht der übliche Allianzabschaum zu sein und jeder, der Dämonen tötet, ist in dem Moment nützlich für mich.\n\nIhr solltet Euch bei Lynnore und Drazial melden, zwei Blutmagier, die ich in die Richtung entsandt habe. Sie haben ihr Lager hinten in einer Ogerhöhle aufgeschlagen.", sourceObjective = "Meldet Euch bei Blutmagierin Lynnore hinten in der Schreckensfelssenke in den Verwüsteten Landen.", completion = "Okrilla hat Euch geschickt? Okrilla da Killa?\n\n<Lynnore hört sich Eure Geschichte an.>\n\nEr hieß Loramus? Es tut mir leid, aber wir haben Euren Dämonenjäger nicht gesehen... Aber wir haben Möglichkeiten, ihn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25684] = { id = 25684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmt den Blutstein ab", description = "Ich gebe zu, dass wir nicht gerade den... vorteilhaftesten Ort für unsere Studien ausgewählt haben, besonders, wenn vorüberziehende Abenteurer den Wunsch haben, unbehelligt einzutreten und wieder hinauszugehen. Unsere Übereinkunft mit den Ogern ist recht wackelig und ich fürchte, wir können sie nicht dazu bewegen, Euch nicht anzugreifen, wenn Ihr Euch nähert.\n\nIch kann Euch allerdings gestatten, Euch mit einem der Blutsteinteleporter zu verbinden. Legt einfach Eure Hände auf den Stein zu meiner Rechten und Ihr werdet aus der Höhle herausteleportiert. Dann benutzt den Stein draußen, um wieder hereinzuteleportieren!", sourceObjective = "Verbindet Euch mit den Blutsteinteleportern in der Schreckensfelssenke.", progress = "Der Verbindungsvorgang ist einfach, und er wird sich ganz bestimmt auf die Dauer bezahlt machen.", completion = "Ausgezeichnet. Jetzt, da das aus dem Weg ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[25685] = { id = 25685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Damit wir das Ritual, um das Ihr gebeten habt, durchführen können - und vielleicht noch weitere Rituale in Zukunft - benötigen wir Blut. Die Verwüsteten Lande sind voller Reagenzien, die wir für unsere Blutmagie brauchen... es ist nur eine Frage der richtigen Zusammenstellung.\n\n<Lynnore berät sich schnell und kurz mit Drazial.>\n\nBasilisken und Hyänen, zu gleichen Teilen. Und wir benötigen viel davon. Geht nach Osten ins Zentrum der Verwüsteten Lande. Und vergesst nicht - Ihr könnt den Teleporter benutzen!", sourceObjective = "Besorgt 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", progress = "Mit Ogerblut kommt man nicht sehr weit. Habt Ihr es?", completion = "<Lynnore beäugt das Blut hungrig.>\n\nMehr als genug - und immer noch warm! Dann lasst uns das Ritual beginnen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[25686] = { id = 25686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutritual", description = "Unser Ziel ist es, den Dämonenjäger Loramus Thalipedes zu finden. Lasst mich wissen, wenn Ihr bereit seid, das Blutritual zu beginnen. Dann zieht Euch einen Schritt zurück.", sourceObjective = "Sprecht mit Blutmagierin Lynnore, um das Blutritual zu beginnen.", progress = "Das Ritual ist noch nicht abgeschlossen.", completion = "Das Blutritual war ein voller Erfolg - ich kann ganz deutlich sehen, wo Loramus sich in diesem Moment befindet. Das heißt, ich kann sehen, wo seine Leichenteile sich befinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[25687] = { id = 25687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht irgendeine Leiche", description = "Loramus Thalipedes ist tot. Nun, das nehme ich zurück... das ist nur eine Annahme meinerseits, aber ich weiß, dass sein Körper in drei Teilen ruht.\n\n<Lynnore denkt kurz nach.>\n\nWenn Ihr mir die drei Teile bringt, haben wir noch eine Chance. Alle drei Teile sind in der Nähe...die Schreckensfelsoger haben sie in ihren Höhlen versteckt. Um genau zu sein ist ein Teil in der Truhe, den Vorsprung hinter mir hinunter....", sourceObjective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", progress = "Vertraut mir - egal, was mit Loramus geschehen ist, wir können es beheben. Die Grenzen der Blutmagie sind bisher noch nicht ausgelotet.", completion = "Ich verstehe...ja, damit können wir arbeiten.\n\n<Lynnore schaut auf den Kopf des Nachtelfen.>\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich darauf, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25688] = { id = 25688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Stürme", description = "Oben auf den Klippen über unserer gemütlichen Höhle befindet sich ein mächtiger Altar. Ein mächtiger DÄMONISCHER Altar, der von Kultisten bewacht wird, aber dennoch sehr große Kräfte birgt. Wenn Ihr es schafft, ihn zu erreichen, könnt Ihr damit Loramus zu uns zurückbringen.\n\nDer Altar wird wahrscheinlich Euren Bemühungen widerstehen, also müsst Ihr Loramus' Leichnam während des Rituals beschützen. Bringt den Dämonenjäger hinterher zu mir zurück.", sourceObjective = "Bringt Loramus' Leichnam zum Altar der Stürme, dann beschützt ihn während des Rituals.", completion = "Ihr... Ihr seid ein Narr! Was habt Ihr getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[25689] = { id = 25689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit ist knapp", description = "Ich jagte einen Dämonen mit Namen Razelikh. Grol, sein Ogerhauptmann, griff mich an. Er hat mich auf dem falschen Fuß erwischt und ich starb - genau wie Grol.\n\nRazelikh hat vor, in die Verwüsteten Lande zurückzukehren und sie mit seinen Dämonen zu überwältigen. Sogar jetzt bereitet er sich darauf vor, seine Legionen zusammenzurufen, damit sie uns auslöschen.\n\n<Der Dämonenjäger zieht schnell eine Rune hervor und übergibt sie Euch.>\n\nBringt das hier zu Wazzik am Dunklen Portal im Südosten. Er wird Euch führen. Schnell! Wir haben nicht viel Zeit!", sourceObjective = "Bringt die disharmonische Rune zu Behüter Wazzik am Dunklen Portal in den Verwüsteten Landen.", progress = "Kenne ich Euch, guter {race}??", completion = "Wie bitte? LORAMUS?!\n\nOh verflixt, sprecht leise, ja? Wenn mein Boss herausfindet, dass ich für Loramus gearbeitet habe, wisst Ihr, wie schnell ich dann auf meinen vier Buchstaben lande?\n\n<Wazzik nimmt Euch die Rune ab, drückt sie gegen seine Brust, schließt seine Augen und nickt.>\n\nNun, Ihr habt nicht gelogen. An die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25690] = { id = 25690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Blutmagier müssen essen", description = "Entgegen dem allgemeinen Irrglauben trinken Blutelfen Blutmagier KEIN Blut. Wir essen normale Speisen wie jeder andere auch - etwas, das in der hintersten Ecke einer Ogerfeste schwierig zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind zumindest ohne Weiteres essbar, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und unsere Nahrungsvorräte wieder aufstocken?", sourceObjective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", progress = "Ich bin ausgehungert! Wenn Ihr Euch nicht beeilt, sehe ich mich noch gezwungen, unsere Reagenzien zu trinken.", completion = "Die sind perfekt, {name}. Lynnore und ich werden in den nächsten Tagen gut zu essen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25691] = { id = 25691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verkohlte Granit des Dunklen Portals", description = "Loramus will, dass wir - äh, IHR - Granitsplitter aus den Felsbrocken um das Dunkle Portal herum sammelt. Ich weiß nicht, wofür er die Steine braucht, aber ich habe da so meinen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal.", sourceObjective = "Besorgt 24 verkohlte Granitsplitter.", progress = "Sprecht leise, ja?", completion = "Ich hoffe, das ist es, was er braucht. Wir haben wahrscheinlich nicht mehr die Zeit, dass Ihr noch einmal zurückkehrt und noch mehr schürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[25692] = { id = 25692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das abscheuliche Blut der Dämonen", description = "Thalipedes möchte mehr Blut. Für mich persönlich sieht das Zeug nicht einmal aus die Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt in reichlichen Mengen.", sourceObjective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", progress = "Uff, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Loramus' Bitte einmal abgesehen, bin ich sicher, dass Dar'toon für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25693] = { id = 25693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserung des Steins", description = "<Wazzik packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was Loramus von uns verlangt hat. Wenn Ihr ihn seht, denkt daran, ihm zu sagen, dass ich eine große Hilfe war. Ich fürchte, er wird meinen Anteil hieran nicht erkennen.", sourceObjective = "Bringt Wazziks Paket zu Loramus Thalipedes in der Schreckensfelssenke in den Verwüsteten Landen.", progress = "{class}... Ihr kehrt zurück...", completion = "Das reicht. Wenn Ihr Wazzik noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Ich werde dafür sorgen, dass die Blutmagier sich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange sie arbeiten, habe ich eine andere Aufgabe für Euch zu erledigen. Um genau zu sein sind es drei Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25694] = { id = 25694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückendeckung", description = "Den einzigen Grund, warum Ihr mich neben Soldaten der Allianz stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - und sei es noch so gering. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", sourceObjective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n<Der Kriegsfürst lehnt sich zu Euch hinüber und flüstert:>\n\n{race}, wenn Ihr noch interessiert seid, ich habe noch eine kleine Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[25695] = { id = 25695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhut", description = "<Kriegsherr Dar'toon spricht sehr leise.>\n\nIch habe Befehle von... oben... für die Ihr genau der Richtige seid. Ich habe gesehen, dass die Allianz regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", sourceObjective = "Untersucht die Pläne der Allianz am Dunklen Portal, ohne erwischt zu werden.", completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n<Dar'toon hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.>\n\nHmpf... das ist ziemlich harmloses Zeugs. Entweder ist die Allianz dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25696] = { id = 25696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenschleiers Exkursionstrupp", description = "Ach richtig - ich habe vor ein paar Tagen eine Nachricht von jemandem erhalten. Das archäologische Institut oder so ähnlich? Sie suchen jemanden, der... etwas tun soll...\n\n<Der Kriegsherr durchwühlt einige Papiere.>\n\nAh, hier ist es! Ja, Rohan Sonnenschleier vom archäologischen Institut sucht fähige Abenteurer, die ihm bei einer archäologischen Expedition in den Süden helfen sollen.\n\nHier, nehmt das mit. Warum geht Ihr nicht und sprecht mit dem Elfen?", sourceObjective = "Meldet Euch bei Rohan Sonnenschleier bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.\n\nBereitgestellter Gegenstand:", completion = "Willkommen, Reisender. Danke, dass Ihr Euch auf meinen Aufruf hin gemeldet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25697] = { id = 25697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Allistarj", description = "Als mein Meister mir half, meine Augen herauszunehmen, gab er mir das Geschenk der Sicht - einer Sicht, die weit besser ist, als Eure oder die dieser blutsüchtigen Elfen. Meine Sicht erlaubt mir, Gegenstände mit dämonischer Macht zu sehen, so wie das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in der Schlangenschlinge im Osten eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.", sourceObjective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", progress = "Alistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "<Lynnore untersucht das Amulett.>\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25698] = { id = 25698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Sevine", description = "Das Amulett von Sevine befindet sich weit im Osten in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nIch fühle eine stärkere Verbindung mit Sevine als mit den anderen Dienern Razelikhs - möglicherweise, weil sie den Altar der Stürme erbaut hat, auf dem Ihr mich wiederbelebt habt. Bringt ihr Amulett mit den anderen zu Lynnore.", sourceObjective = "Besorgt das Amulett von Sevine von Salzflopper in den Verwüsteten Landen.", progress = "Sevines Amulett - zusammen mit den anderen können wir die Anhöhe des Entweihers erreichen.", completion = "<Lynnore wiegt das Amulett in der Hand.>\n\nEin Kriegsherr... und ein mächtiger noch dazu. Ich werde das hier behalten, bis die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25699] = { id = 25699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Grol", description = "Grol - der Oger, der mich auseinandergerissen hat.\n\n<Loramus lacht.>\n\nOffensichtlich ist Grols Leichnam durch mehrere Hände gegangen, seit wir zusammen gestorben sind, aber er ist nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", sourceObjective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "<Lynnore umklammert das Amulett.>\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis Loramus bereit ist, fortzufahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25700] = { id = 25700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus Thalipedes wartet", description = "Die Verzauberung auf diesen Amuletten war nicht besonders kompliziert. Zusammengefügt wird ihre Macht Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, verschaffen.\n\nIch bin bereit, dieses Ritual für Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Blutmagierin Lynnore, um an ihrem Ritual teilzunehmen.", completion = "Wie es aussieht, sind wir bereit, uns unserem Dämonen zu stellen, {name}. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämonen: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25701] = { id = 25701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "Held, hört gut zu.\n\nZunächst müssen wir nach Nordosten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe begleiten. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Wazzik.", sourceObjective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", completion = "Ich verstehe. Also hatte Loramus das die ganze Zeit so geplant.\n\nIch hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben. Und jetzt ergibt seine letzte Anweisung an mich auch einen Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25702] = { id = 25702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause... Weg... Naga...", description = "<Der Murloc hat Schwierigkeiten, Eure Sprache zu sprechen.>\n\nSteinteich... angegriffen. Naga kommen, einnehmen Dorf, Dorfbewohner.\n\nSalzflopper entkommen, andere nicht. Geht Süden, sprecht mit Häuptling Neptool. Vielleicht er überlebt.", sourceObjective = "Salzflopper hat Euch gebeten, mit Neptool, Häuptling der Steinteichmurlocs, zu sprechen.", completion = "<Der Murlocgeist schaut Euch traurig an.>\n\nSalzflopper hat keine Schande über sich gebracht, indem er wegrannte. Schaut hinter mich und seht selbst.\n\nDer Steinteich hatte keine Chance gegen den Angriff der Naga.", sourceObjectiveStatus = "unverified-source-field" }
